	void ImVectorUniqueEdge( int& size, ImVector<ImWidgetsEdgeIdx>& edges )
	{
		size = edges.size();
		for ( int p = 0; p < size; ++p )
		{
			for ( int q = p + 1; q < size; ++q )
			{
				if ( edges[ p ].a == edges[ q ].a &&
					 edges[ p ].b == edges[ q ].b )
				{
					while ( edges[ p ].a == edges[ q ].a &&
							edges[ p ].b == edges[ q ].b )
					{
						// Flag non-unique edges with -index of the duplicate edge
						edges[ q ].a = -p;
						//edges[ q ].b = -p;
						//ImEdgeIdx last = vector[ size - 1 ];
						//vector[ size - 1 ] = vector[ q ];
						//vector[ q ] = last;
						--size;
					}
				}
			}
		}
		//vector.resize( size );
	}

	int GetEdgeIndex( ImVector<ImWidgetsEdgeIdx> const& edges, ImWidgetsEdgeIdx e )
	{
		int edge_count = edges.size();
		for ( int k = 0; k < edge_count; ++k )
		{
			ImWidgetsEdgeIdx const& cur = edges[ k ];
			if ( cur.a == e.a && cur.b == e.b )
				return k;
		}

		return -1;
	}

	ImDrawIdx GetOtherIdx( ImDrawIdx a, ImDrawIdx b, ImWidgetsTriIdx& tri )
	{
		if ( a == tri.a )
		{
			if ( b == tri.b )
			{
				return tri.c;
			}
			else if ( b == tri.c )
			{
				return tri.b;
			}
		}
		else if ( a == tri.b )
		{
			if ( b == tri.a )
			{
				return tri.c;
			}
			else if ( b == tri.c )
			{
				return tri.a;
			}
		}
		else if ( a == tri.c )
		{
			if ( b == tri.a )
			{
				return tri.b;
			}
			else if ( b == tri.b )
			{
				return tri.a;
			}
		}

		return ImDrawIdx( -1 );
	}

	void GetOtherIdxOrdered( ImDrawIdx& a, ImDrawIdx& b, ImWidgetsTriIdx& tri, ImDrawIdx p )
	{
		if ( p == tri.a )
		{
			a = tri.b;
			b = tri.c;
			return;
		}
		else if ( p == tri.b )
		{
			a = tri.c;
			b = tri.a;
			return;
		}
		else if ( p == tri.c )
		{
			a = tri.a;
			b = tri.b;
			return;
		}

		a = (ImDrawIdx)(-1);
		b = (ImDrawIdx)(-1);
	}

	float ImCross( ImVec2 v1, ImVec2 v2 )
	{
		return v1.x * v2.y - v1.y * v2.x;
	}

	float ImTriangleSignedArea( ImVec2 va, ImVec2 vb, ImVec2 vc )
	{
		return 0.5f * ( va.x * ( vb.y - vc.y ) + vb.x * ( vc.y - va.y ) + vc.x * ( va.y - vb.y ) );
	}

	int CheckWinding( ImVec2 va, ImVec2 vb, ImVec2 vc )
	{
		ImVec2 v1 = { vb.x - va.x, vb.y - va.y };
		ImVec2 v2 = { vc.x - va.x, vc.y - va.y };

		//float cross = ImCross( v1, v2 );
		float signed_area = ImTriangleSignedArea( va, vb, vc );

		if ( signed_area > 0.0f )
		{
			// Counterclockwise (CCW)
			return 1;
		}
		else if ( signed_area < 0.0f )
		{
			// Clockwise (CW)
			return -1;
		}
		else
		{
			// Collinear
			return 0;
		}
	}

	//////////////////////////////////////////////////////////////////////////
	// Geometry Generation
	//////////////////////////////////////////////////////////////////////////
#ifdef DEAR_WIDGETS_TESSELATION
	// Helper structures for tessellation (STL-free implementation)
	struct ImWidgetsEdge
	{
		ImDrawIdx a;
		ImDrawIdx b;

		bool operator==( const ImWidgetsEdge& other ) const
		{
			return a == other.a && b == other.b;
		}
	};

	struct ImWidgetsEdgeToVertex
	{
		ImWidgetsEdge edge;
		ImWidgetsVertex vertex;
	};

	struct ImWidgetsEdgeToIndex
	{
		ImWidgetsEdge edge;
		int index;
	};

	// Helper function to find edge in edge-to-vertex array
	static int FindEdgeToVertex( const ImVector<ImWidgetsEdgeToVertex>& arr, const ImWidgetsEdge& edge )
	{
		for ( int i = 0; i < arr.Size; ++i )
		{
			if ( arr[ i ].edge == edge )
				return i;
		}
		return -1;
	}

	// Helper function to find edge in edge-to-index array
	static int FindEdgeToIndex( const ImVector<ImWidgetsEdgeToIndex>& arr, const ImWidgetsEdge& edge )
	{
		for ( int i = 0; i < arr.Size; ++i )
		{
			if ( arr[ i ].edge == edge )
				return i;
		}
		return -1;
	}

	// Helper function to get or add edge-to-vertex mapping
	static void SetEdgeToVertex( ImVector<ImWidgetsEdgeToVertex>& arr, const ImWidgetsEdge& edge, const ImWidgetsVertex& vertex )
	{
		int idx = FindEdgeToVertex( arr, edge );
		if ( idx >= 0 )
		{
			arr[ idx ].vertex = vertex;
		}
		else
		{
			ImWidgetsEdgeToVertex ev;
			ev.edge = edge;
			ev.vertex = vertex;
			arr.push_back( ev );
		}
	}

	#pragma optimize( "", off )
	void	ShapeTesselationUniform( ImWidgetsShape& shape )
	{
		int vtx_count = shape.vertices.size();
		int tri_count = shape.triangles.size();

		ImVector<ImWidgetsEdgeToVertex> edge_to_vrtx;
		for ( int k = 0; k < tri_count; ++k )
		{
			ImWidgetsTriIdx const& tri = shape.triangles[ k ];

			ImDrawIdx a = tri.a;
			ImDrawIdx b = tri.b;
			ImDrawIdx c = tri.c;

			ImVec2 va = shape.vertices[ a ].pos;
			ImVec2 vb = shape.vertices[ b ].pos;
			ImVec2 vc = shape.vertices[ c ].pos;

			ImVec2 uva = shape.vertices[ a ].uv;
			ImVec2 uvb = shape.vertices[ b ].uv;
			ImVec2 uvc = shape.vertices[ c ].uv;

			ImVec4 cola = ImGui::ColorConvertU32ToFloat4( shape.vertices[ a ].col );
			ImVec4 colb = ImGui::ColorConvertU32ToFloat4( shape.vertices[ b ].col );
			ImVec4 colc = ImGui::ColorConvertU32ToFloat4( shape.vertices[ c ].col );

			ImWidgetsEdge ab = { ImMin( a, b ), ImMax( a, b ) };
			ImWidgetsEdge bc = { ImMin( b, c ), ImMax( b, c ) };
			ImWidgetsEdge ca = { ImMin( c, a ), ImMax( c, a ) };

			float ab_sqr = ImLengthSqr( va - vb );
			float bc_sqr = ImLengthSqr( vb - vc );
			float ca_sqr = ImLengthSqr( vc - va );

			if ( ab_sqr >= bc_sqr && ab_sqr >= ca_sqr )
			{
				ImVec2 v = va * 0.5f + vb * 0.5f;
				ImVec2 uv = uva * 0.5f + uvb * 0.5f;
				ImVec4 col = ImLerp( cola, colb, 0.5f );
				ImWidgetsVertex vtx = { v, uv, ImGui::GetColorU32( col ) };
				SetEdgeToVertex( edge_to_vrtx, ab, vtx );
			}
			else if ( bc_sqr >= ab_sqr && bc_sqr >= ca_sqr )
			{
				ImVec2 v = vb * 0.5f + vc * 0.5f;
				ImVec2 uv = uvb * 0.5f + uvc * 0.5f;
				ImVec4 col = ImLerp( colb, colc, 0.5f );
				ImWidgetsVertex vtx = { v, uv, ImGui::GetColorU32( col ) };
				SetEdgeToVertex( edge_to_vrtx, bc, vtx );
			}
			else if ( ca_sqr >= ab_sqr && ca_sqr >= bc_sqr )
			{
				ImVec2 v = vc * 0.5f + va * 0.5f;
				ImVec2 uv = uvc * 0.5f + uva * 0.5f;
				ImVec4 col = ImLerp( colc, cola, 0.5f );
				ImWidgetsVertex vtx = { v, uv, ImGui::GetColorU32( col ) };
				SetEdgeToVertex( edge_to_vrtx, ca, vtx );
			}
			else
			{
				__debugbreak();
			}
		}
		int new_vrtx_count = edge_to_vrtx.Size;
		ImVector<ImWidgetsEdgeToIndex> edge_to_idx;
		edge_to_idx.reserve( new_vrtx_count );
		for ( int i = 0; i < edge_to_vrtx.Size; ++i )
		{
			ImWidgetsEdgeToIndex ei;
			ei.edge = edge_to_vrtx[ i ].edge;
			ei.index = vtx_count + i;
			edge_to_idx.push_back( ei );
		}
		shape.vertices.resize( vtx_count + new_vrtx_count );
		for ( int i = 0; i < edge_to_vrtx.Size; ++i )
		{
			shape.vertices[ vtx_count + i ] = edge_to_vrtx[ i ].vertex;
		}

		ImVector<ImWidgetsTriIdx> new_indices;
		for ( int k = 0; k < tri_count; ++k )
		{
			ImWidgetsTriIdx const& tri = shape.triangles[ k ];

			ImDrawIdx a = tri.a;
			ImDrawIdx b = tri.b;
			ImDrawIdx c = tri.c;

			ImWidgetsEdge ab = { ImMin( a, b ), ImMax( a, b ) };
			ImWidgetsEdge bc = { ImMin( b, c ), ImMax( b, c ) };
			ImWidgetsEdge ca = { ImMin( c, a ), ImMax( c, a ) };

			int idx_ab = FindEdgeToVertex( edge_to_vrtx, ab );
			int idx_bc = FindEdgeToVertex( edge_to_vrtx, bc );
			int idx_ca = FindEdgeToVertex( edge_to_vrtx, ca );

			bool is_ab = ( idx_ab >= 0 );
			bool is_bc = ( idx_bc >= 0 );
			bool is_ca = ( idx_ca >= 0 );
			int new_vrtx_count = ( is_ab ? 1 : 0 ) + ( is_bc ? 1 : 0 ) + ( is_ca ? 1 : 0 );

			if ( new_vrtx_count == 0 )
			{
				new_indices.push_back( { a, b, c } );
				__debugbreak();
			}
			else if ( new_vrtx_count == 1 )
			{
				if ( is_ab )
				{
					int edge_idx = FindEdgeToIndex( edge_to_idx, ab );
					IM_ASSERT( edge_idx >= 0 );
					ImDrawIdx new_ab = edge_to_idx[ edge_idx ].index;
					IM_ASSERT( new_ab >= vtx_count );
					new_indices.push_back( { a, new_ab, c } );
					new_indices.push_back( { c, new_ab, b } );
				}
				else if ( is_bc )
				{
					int edge_idx = FindEdgeToIndex( edge_to_idx, bc );
					IM_ASSERT( edge_idx >= 0 );
					ImDrawIdx new_bc = edge_to_idx[ edge_idx ].index;
					IM_ASSERT( new_bc >= vtx_count );
					new_indices.push_back( { b, new_bc, a } );
					new_indices.push_back( { a, new_bc, c } );
				}
				else if ( is_ca )
				{
					int edge_idx = FindEdgeToIndex( edge_to_idx, ca );
					IM_ASSERT( edge_idx >= 0 );
					ImDrawIdx new_ca = edge_to_idx[ edge_idx ].index;
					IM_ASSERT( new_ca >= vtx_count );
					new_indices.push_back( { c, new_ca, b } );
					new_indices.push_back( { b, new_ca, a } );
				}
				else
				{
					__debugbreak();
				}
			}
			else if ( new_vrtx_count == 2 )
			{
				if ( is_ab && is_bc )
				{
					int edge_idx_ab = FindEdgeToIndex( edge_to_idx, ab );
					int edge_idx_bc = FindEdgeToIndex( edge_to_idx, bc );
					IM_ASSERT( edge_idx_ab >= 0 && edge_idx_bc >= 0 );
					ImDrawIdx new_ab = edge_to_idx[ edge_idx_ab ].index;
					ImDrawIdx new_bc = edge_to_idx[ edge_idx_bc ].index;
					IM_ASSERT( new_ab >= vtx_count );
					IM_ASSERT( new_bc >= vtx_count );
					new_indices.push_back( { a, new_ab, new_bc } );
					new_indices.push_back( { b, new_bc, new_ab } );
					new_indices.push_back( { c, a, new_bc } );
				}
				else if ( is_bc && is_ca )
				{
					int edge_idx_bc = FindEdgeToIndex( edge_to_idx, bc );
					int edge_idx_ca = FindEdgeToIndex( edge_to_idx, ca );
					IM_ASSERT( edge_idx_bc >= 0 && edge_idx_ca >= 0 );
					ImDrawIdx new_bc = edge_to_idx[ edge_idx_bc ].index;
					ImDrawIdx new_ca = edge_to_idx[ edge_idx_ca ].index;
					IM_ASSERT( new_bc >= vtx_count );
					IM_ASSERT( new_ca >= vtx_count );
					new_indices.push_back( { b, new_bc, new_ca } );
					new_indices.push_back( { a, b, new_ca } );
					new_indices.push_back( { c, new_ca, new_bc } );
				}
				else if ( is_ca && is_ab )
				{
					int edge_idx_ab = FindEdgeToIndex( edge_to_idx, ab );
					int edge_idx_ca = FindEdgeToIndex( edge_to_idx, ca );
					IM_ASSERT( edge_idx_ab >= 0 && edge_idx_ca >= 0 );
					ImDrawIdx new_ab = edge_to_idx[ edge_idx_ab ].index;
					ImDrawIdx new_ca = edge_to_idx[ edge_idx_ca ].index;
					IM_ASSERT( new_ab >= vtx_count );
					IM_ASSERT( new_ca >= vtx_count );
					new_indices.push_back( { a, new_ab, new_ca } );
					new_indices.push_back( { c, new_ca, new_ab } );
					new_indices.push_back( { b, c, new_ab } );
				}
				else
				{
					__debugbreak();
				}
			}
			else if ( new_vrtx_count == 3 )
			{
				int edge_idx_ab = FindEdgeToIndex( edge_to_idx, ab );
				int edge_idx_bc = FindEdgeToIndex( edge_to_idx, bc );
				int edge_idx_ca = FindEdgeToIndex( edge_to_idx, ca );
				IM_ASSERT( edge_idx_ab >= 0 && edge_idx_bc >= 0 && edge_idx_ca >= 0 );
				ImDrawIdx new_ab = edge_to_idx[ edge_idx_ab ].index;
				ImDrawIdx new_bc = edge_to_idx[ edge_idx_bc ].index;
				ImDrawIdx new_ca = edge_to_idx[ edge_idx_ca ].index;
				IM_ASSERT( new_ab >= vtx_count );
				IM_ASSERT( new_bc >= vtx_count );
				IM_ASSERT( new_ca >= vtx_count );

				new_indices.push_back( { a, new_ab, new_ca } );
				new_indices.push_back( { b, new_bc, new_ab } );
				new_indices.push_back( { c, new_ca, new_bc } );
				new_indices.push_back( { new_ab, new_bc, new_ca } );
			}
			else
			{
				__debugbreak();
			}
		}
		int new_tri_count = new_indices.size();
		for ( int k = 0; k < new_tri_count; ++k )
		{
			ImWidgetsTriIdx& tri = new_indices[ k ];

			ImDrawIdx a = tri.a;
			ImDrawIdx b = tri.b;
			ImDrawIdx c = tri.c;

			ImVec2 va = shape.vertices[ a ].pos;
			ImVec2 vb = shape.vertices[ b ].pos;
			ImVec2 vc = shape.vertices[ c ].pos;

			if ( CheckWinding( va, vb, vc ) == -1 )
			{
				//tri.a = a;
				tri.b = c;
				tri.c = b;
			}
		}
		shape.triangles = new_indices;
	}
#endif

	void	ShapeTranslate( ImWidgetsShape& shape, ImVec2 t )
	{
		int vtx_count = shape.vertices.size();
		for ( int k = 0; k < vtx_count; ++k )
		{
			shape.vertices[ k ].pos += t;
		}
		shape.bb.Min += t;
		shape.bb.Max += t;
	}

	void	ShapeSetDefaultUV( ImWidgetsShape& shape )
	{
		int vtx_count = shape.vertices.size();
		for ( int k = 0; k < vtx_count; ++k )
		{
			shape.vertices[ k ].uv = ImGui::GetFontTexUvWhitePixel();
		}
	}

	void	ShapeSetDefaultUVCol( ImWidgetsShape& shape )
	{
		int vtx_count = shape.vertices.size();
		for ( int k = 0; k < vtx_count; ++k )
		{
			shape.vertices[ k ].uv = ImGui::GetFontTexUvWhitePixel();
			shape.vertices[ k ].col = IM_COL32( 255, 255, 255, 255 );
		}
	}

	void	ShapeSetDefaultBoundUV( ImWidgetsShape& shape )
	{
		int vtx_count = shape.vertices.size();
		for ( int k = 0; k < vtx_count; ++k )
		{
			ImVec2 v = shape.vertices[ k ].pos;
			ImVec2 uv;
			uv.x = Normalize01( v.x, shape.bb.Min.x, shape.bb.Max.x );
			uv.y = Normalize01( v.y, shape.bb.Min.y, shape.bb.Max.y );
			shape.vertices[ k ].uv = uv;
		}
	}

	void	ShapeSetDefaultBoundUVWhiteCol( ImWidgetsShape& shape )
	{
		int vtx_count = shape.vertices.size();
		for ( int k = 0; k < vtx_count; ++k )
		{
			ImVec2 v = shape.vertices[ k ].pos;
			ImVec2 uv;
			uv.x = Normalize01( v.x, shape.bb.Min.x, shape.bb.Max.x );
			uv.y = Normalize01( v.y, shape.bb.Min.y, shape.bb.Max.y );
			shape.vertices[ k ].uv = uv;
			shape.vertices[ k ].col = IM_COL32( 255, 255, 255, 255 );
		}
	}

	void	ShapeSetDefaultWhiteCol( ImWidgetsShape& shape )
	{
		// Use ImGui's font atlas white pixel UV for solid colors (same as ImGui uses internally)
		ImVec2 uv_white = ImGui::GetFontTexUvWhitePixel();
		int vtx_count = shape.vertices.size();
		for ( int k = 0; k < vtx_count; ++k )
		{
			shape.vertices[ k ].uv = uv_white;
			shape.vertices[ k ].col = IM_COL32( 255, 255, 255, 255 );
		}
	}

	void	ShapeSetBound( ImWidgetsShape& shape )
	{
		shape.bb.Min = shape.vertices.front().pos;
		shape.bb.Max = shape.vertices.front().pos;
		int vtx_count = shape.vertices.size();
		for ( int k = 1; k < vtx_count; ++k )
		{
			shape.bb.Min.x = ImMin( shape.bb.Min.x, shape.vertices[ k ].pos.x );
			shape.bb.Min.y = ImMin( shape.bb.Min.y, shape.vertices[ k ].pos.y );
			shape.bb.Max.x = ImMax( shape.bb.Max.x, shape.vertices[ k ].pos.x );
			shape.bb.Max.y = ImMax( shape.bb.Max.y, shape.vertices[ k ].pos.y );
		}
	}

	void	ShapeLineSetBound( ImWidgetsShapeLine& shape )
	{
		shape.bb.Min = shape.vertices.front().pos;
		shape.bb.Max = shape.vertices.front().pos;
		//shape.bb.Min = shape.vertices->pos;
		//shape.bb.Max = shape.vertices->pos;
		int vtx_count = shape.vertices.size();
		//int vtx_count = shape.vertices_count;
		for ( int k = 1; k < vtx_count; ++k )
		{
			shape.bb.Min.x = ImMin( shape.bb.Min.x, shape.vertices[ k ].pos.x );
			shape.bb.Min.y = ImMin( shape.bb.Min.y, shape.vertices[ k ].pos.y );
			shape.bb.Max.x = ImMin( shape.bb.Max.x, shape.vertices[ k ].pos.x );
			shape.bb.Max.y = ImMin( shape.bb.Max.y, shape.vertices[ k ].pos.y );
		}
	}

	//////////////////////////////////////////////////////////////////////////
	// Shape Cache  (S-2: O(1) hash map lookup)
	//////////////////////////////////////////////////////////////////////////
	static ImWidgetsShapeCache g_ShapeCache;

	ImWidgetsShapeCache& GetShapeCache()
	{
		return g_ShapeCache;
	}

	// Fold 64-bit key to a hash-map slot index.
	static inline int ShapeCacheSlot( ImU64 key, int mask )
	{
		ImU32 k = (ImU32)( key ^ ( key >> 32 ) );
		return (int)( ( k * 2654435761u ) & (ImU32)mask );
	}

	// Rebuild the open-addressed map from scratch. Called on grow or after erase.
	static void ShapeCacheRebuildMap( ImWidgetsShapeCache& cache )
	{
		int cap = 8;
		while ( cap < cache.entries.Size * 2 ) cap <<= 1;
		cache.map.resize( cap );
		memset( cache.map.Data, 0, cap * sizeof(int) );
		int mask = cap - 1;
		for ( int i = 0; i < cache.entries.Size; i++ )
		{
			int slot = ShapeCacheSlot( cache.entries[i].key, mask );
			while ( cache.map[slot] ) slot = ( slot + 1 ) & mask;
			cache.map[slot] = i + 1; // store index+1; 0 = empty sentinel
		}
	}

	ImWidgetsShape* ShapeCacheGet( ImWidgetsShapeCache& cache, ImU64 key )
	{
		if ( cache.map.Size == 0 ) return nullptr;
		int mask = cache.map.Size - 1;
		int slot = ShapeCacheSlot( key, mask );
		while ( int v = cache.map[slot] )
		{
			int idx = v - 1;
			if ( cache.entries[idx].key == key )
				return cache.entries[idx].shape;
			slot = ( slot + 1 ) & mask;
		}
		return nullptr;
	}

	void ShapeCacheInsert( ImWidgetsShapeCache& cache, ImU64 key, const ImWidgetsShape& shape )
	{
		ImWidgetsShape* heap_shape = IM_NEW(ImWidgetsShape)();
		*heap_shape = shape;

		ImWidgetsShapeCacheEntry entry;
		entry.key   = key;
		entry.shape = heap_shape;
		cache.entries.push_back( entry );

		int n = cache.entries.Size; // new entry is at index n-1, stored value = n
		if ( cache.map.Size == 0 || n * 2 > cache.map.Size )
		{
			ShapeCacheRebuildMap( cache );
		}
		else
		{
			int mask = cache.map.Size - 1;
			int slot = ShapeCacheSlot( key, mask );
			while ( cache.map[slot] ) slot = ( slot + 1 ) & mask;
			cache.map[slot] = n;
		}
	}

	void ShapeCacheInvalidate( ImWidgetsShapeCache& cache, ImU64 key )
	{
		for ( int i = 0; i < cache.entries.Size; ++i )
			if ( cache.entries[i].key == key )
			{
				IM_DELETE( cache.entries[i].shape );
				cache.entries.erase( cache.entries.Data + i );
				ShapeCacheRebuildMap( cache ); // rebuild after erase (rare operation)
				break;
			}
	}

	void ShapeCacheClear( ImWidgetsShapeCache& cache )
	{
		for ( int i = 0; i < cache.entries.Size; ++i )
			IM_DELETE( cache.entries[i].shape );
		cache.entries.clear();
		cache.map.clear();
	}

	void ClearShapeCache()
	{
		ShapeCacheClear( GetShapeCache() );
	}

	void	GenShapeRect( ImWidgetsShape& shape, ImRect const& r )
	{
		ImVec2 size = r.Max - r.Min;
#ifdef DEAR_WIDGETS_SHAPE_CACHING
		struct { int type; ImVec2 size; } key_data = {};
		key_data.type = 0;
		key_data.size = size;
		ImU64 key = ImHashData( &key_data, sizeof( key_data ) );
		ImWidgetsShapeCache& cache = GetShapeCache();
		if ( ImWidgetsShape* cached = ShapeCacheGet( cache, key ) )
		{
			shape = *cached;
			ShapeTranslate( shape, r.Min );
			return;
		}
#endif
		shape.vertices.clear();
		shape.triangles.clear();
		shape.vertices.resize( 4 );
		shape.triangles.resize( 2 );
		// Zero-initialize all vertex data to avoid garbage values
		memset( shape.vertices.Data, 0, sizeof( ImWidgetsVertex ) * 4 );
		shape.vertices[ 0 ].pos = ImVec2( 0.0f, 0.0f );
		shape.vertices[ 1 ].pos = ImVec2( 0.0f, size.y );
		shape.vertices[ 2 ].pos = size;
		shape.vertices[ 3 ].pos = ImVec2( size.x, 0.0f );
		shape.bb.Min = ImVec2( 0.0f, 0.0f );
		shape.bb.Max = size;
		shape.triangles[ 0 ].a = 0;
		shape.triangles[ 0 ].b = 1;
		shape.triangles[ 0 ].c = 3;
		shape.triangles[ 1 ].a = 3;
		shape.triangles[ 1 ].b = 1;
		shape.triangles[ 1 ].c = 2;
#ifdef DEAR_WIDGETS_SHAPE_CACHING
		ShapeCacheInsert( cache, key, shape );
#endif
		ShapeTranslate( shape, r.Min );
	}

	void	GenShapeCircle( ImWidgetsShape& shape, ImVec2 center, float radius, int side_count )
	{
#ifdef DEAR_WIDGETS_SHAPE_CACHING
		struct { int type; float radius; int side_count; } key_data = {};
		key_data.type = 1;
		key_data.radius = radius;
		key_data.side_count = side_count;
		ImU64 key = ImHashData( &key_data, sizeof( key_data ) );
		ImWidgetsShapeCache& cache = GetShapeCache();
		if ( ImWidgetsShape* cached = ShapeCacheGet( cache, key ) )
		{
			shape = *cached;
			ShapeTranslate( shape, center );
			return;
		}
#endif
		shape.vertices.clear();
		shape.triangles.clear();
		float d0 = 2.0f * IM_PI / ( ( float )( side_count ) );
		shape.vertices.resize( side_count + 1 );
		shape.triangles.resize( side_count );
		// Zero-initialize all vertex data to avoid garbage values
		memset( shape.vertices.Data, 0, sizeof( ImWidgetsVertex ) * ( side_count + 1 ) );
		shape.vertices[ 0 ].pos = ImVec2( 0.0f, 0.0f );
		for ( int k = 0; k < side_count; ++k )
		{
			float _0 = ( ( float )k ) * d0;
			shape.vertices[ k + 1 ].pos.x = radius * ImCos( _0 );
			shape.vertices[ k + 1 ].pos.y = radius * ImSin( _0 );
		}
		for ( int k = 0; k < side_count; ++k )
		{
			shape.triangles[ k ].a = 0;
			shape.triangles[ k ].b = k + 1;
			shape.triangles[ k ].c = (k + 1) % side_count + 1;
		}
		shape.bb.Min = ImVec2( -radius, -radius );
		shape.bb.Max = ImVec2( radius, radius );
#ifdef DEAR_WIDGETS_SHAPE_CACHING
		ShapeCacheInsert( cache, key, shape );
#endif
		ShapeTranslate( shape, center );
	}
	void	GenShapeCircleArc( ImWidgetsShape& shape, ImVec2 center, float radius, float angle_min, float angle_max, int side_count )
	{
#ifdef DEAR_WIDGETS_SHAPE_CACHING
		struct { int type; float radius; float angle_min; float angle_max; int side_count; } key_data = {};
		key_data.type = 2;
		key_data.radius = radius;
		key_data.angle_min = angle_min;
		key_data.angle_max = angle_max;
		key_data.side_count = side_count;
		ImU64 key = ImHashData( &key_data, sizeof( key_data ) );
		ImWidgetsShapeCache& cache = GetShapeCache();
		if ( ImWidgetsShape* cached = ShapeCacheGet( cache, key ) )
		{
			shape = *cached;
			ShapeTranslate( shape, center );
			return;
		}
#endif
		shape.vertices.clear();
		shape.triangles.clear();
		float angle_range = angle_max - angle_min;
		float d0 = angle_range / ( ( float )( side_count ) );
		shape.vertices.resize( side_count + 2 );
		shape.triangles.resize( side_count );
		// Zero-initialize all vertex data to avoid garbage values
		memset( shape.vertices.Data, 0, sizeof( ImWidgetsVertex ) * ( side_count + 2 ) );
		shape.vertices[ 0 ].pos = ImVec2( 0.0f, 0.0f );
		shape.bb.Min.x =  FLT_MAX;
		shape.bb.Min.y =  FLT_MAX;
		shape.bb.Max.x = -FLT_MAX;
		shape.bb.Max.y = -FLT_MAX;
		for ( int k = 0; k < side_count + 1; ++k )
		{
			float _0 = angle_min + ( ( float )k ) * d0;
			ImVec2 v;
			v.x = radius * ImCos( - _0 );
			v.y = radius * ImSin( - _0 );
			shape.vertices[ k + 1 ].pos.x = v.x;
			shape.vertices[ k + 1 ].pos.y = v.y;
			shape.bb.Min.x = ImMin( shape.bb.Min.x, v.x );
			shape.bb.Min.y = ImMin( shape.bb.Min.y, v.y );
			shape.bb.Max.x = ImMax( shape.bb.Max.x, v.x );
			shape.bb.Max.y = ImMax( shape.bb.Max.y, v.y );
		}
		for ( int k = 0; k < side_count; ++k )
		{
			shape.triangles[ k ].a = 0;
			shape.triangles[ k ].b = k + 1;
			shape.triangles[ k ].c = k + 2;
		}
#ifdef DEAR_WIDGETS_SHAPE_CACHING
		ShapeCacheInsert( cache, key, shape );
#endif
		ShapeTranslate( shape, center );
	}
	void	GenShapeRegularNGon( ImWidgetsShape& shape, ImVec2 center, float radius, int side_count )
	{
		GenShapeCircle( shape, center, radius, side_count );
	}
	void	GenShapeSquircle( ImWidgetsShape& shape, ImVec2 center, float radius, int side_count, float n )
	{
#ifdef DEAR_WIDGETS_SHAPE_CACHING
		struct { int type; float radius; int side_count; float n; } key_data = {};
		key_data.type = 4;
		key_data.radius = radius;
		key_data.side_count = side_count;
		key_data.n = n;
		ImU64 key = ImHashData( &key_data, sizeof( key_data ) );
		ImWidgetsShapeCache& cache = GetShapeCache();
		if ( ImWidgetsShape* cached = ShapeCacheGet( cache, key ) )
		{
			shape = *cached;
			ShapeTranslate( shape, center );
			return;
		}
#endif
		shape.vertices.clear();
		shape.triangles.clear();

		// Squircle is defined by the superellipse equation: |x/a|^n + |y/b|^n = 1
		// We'll sample points around the shape parametrically
		float d0 = 2.0f * IM_PI / ( ( float )( side_count ) );
		shape.vertices.resize( side_count + 1 );
		shape.triangles.resize( side_count );
		// Zero-initialize all vertex data to avoid garbage values
		memset( shape.vertices.Data, 0, sizeof( ImWidgetsVertex ) * ( side_count + 1 ) );
		shape.vertices[ 0 ].pos = ImVec2( 0.0f, 0.0f );

		// Generate vertices using parametric form of superellipse
		for ( int k = 0; k < side_count; ++k )
		{
			float angle = ( ( float )k ) * d0;
			float cos_angle = ImCos( angle );
			float sin_angle = ImSin( angle );

			// Superellipse parametric equations
			// x = a * sgn(cos(t)) * |cos(t)|^(2/n)
			// y = b * sgn(sin(t)) * |sin(t)|^(2/n)
			float exp = 2.0f / n;
			float x = ImPow( ImFabs( cos_angle ), exp ) * ( cos_angle >= 0 ? 1.0f : -1.0f );
			float y = ImPow( ImFabs( sin_angle ), exp ) * ( sin_angle >= 0 ? 1.0f : -1.0f );

			shape.vertices[ k + 1 ].pos.x = radius * x;
			shape.vertices[ k + 1 ].pos.y = radius * y;
		}

		// Generate triangles as a fan from center
		for ( int k = 0; k < side_count; ++k )
		{
			shape.triangles[ k ].a = 0;
			shape.triangles[ k ].b = k + 1;
			shape.triangles[ k ].c = (k + 1) % side_count + 1;
		}

		shape.bb.Min = ImVec2( -radius, -radius );
		shape.bb.Max = ImVec2( radius, radius );
#ifdef DEAR_WIDGETS_SHAPE_CACHING
		ShapeCacheInsert( cache, key, shape );
#endif
		ShapeTranslate( shape, center );
	}

	// S-1: Concave polygon tessellation with shape cache.
	// pts must be in local/normalized space (not screen-space); origin is added back after tessellation.
	// Cache key is the hash of the normalized points — same polygon shape always hits, regardless of position.
	void	GenShapeConcavePoly( ImWidgetsShape& shape, const ImVec2* pts, int pts_count, ImVec2 origin )
	{
		if ( pts_count < 3 ) { shape.vertices.clear(); shape.triangles.clear(); return; }

#ifdef DEAR_WIDGETS_SHAPE_CACHING
		ImU64 key = ImHashData( pts, (size_t)pts_count * sizeof(ImVec2) );
		ImWidgetsShapeCache& cache = GetShapeCache();
		if ( ImWidgetsShape* cached = ShapeCacheGet( cache, key ) )
		{
			shape = *cached;
			ShapeTranslate( shape, origin );
			return;
		}
#endif
		int tri_count = pts_count - 2;
		shape.vertices.resize( pts_count );
		shape.triangles.resize( tri_count );
		memset( shape.vertices.Data, 0, (size_t)pts_count * sizeof(ImWidgetsVertex) );
		shape.bb.Min = ImVec2(  FLT_MAX,  FLT_MAX );
		shape.bb.Max = ImVec2( -FLT_MAX, -FLT_MAX );
		for ( int i = 0; i < pts_count; i++ )
		{
			shape.vertices[i].pos = pts[i];
			shape.bb.Min.x = ImMin( shape.bb.Min.x, pts[i].x );
			shape.bb.Min.y = ImMin( shape.bb.Min.y, pts[i].y );
			shape.bb.Max.x = ImMax( shape.bb.Max.x, pts[i].x );
			shape.bb.Max.y = ImMax( shape.bb.Max.y, pts[i].y );
		}

		// Ear-clipping triangulation (ImTriangulator0) — O(n²) worst case, cached after first call
		int scratch_bytes = ImTriangulator0::EstimateScratchBufferSize( pts_count );
		void* scratch = IM_ALLOC( scratch_bytes );
		ImTriangulator0 triangulator;
		triangulator.Init( pts, pts_count, scratch );
		for ( int i = 0; i < tri_count; i++ )
		{
			unsigned int tri[3];
			triangulator.GetNextTriangle( tri );
			shape.triangles[i].a = tri[0];
			shape.triangles[i].b = tri[1];
			shape.triangles[i].c = tri[2];
		}
		IM_FREE( scratch );

#ifdef DEAR_WIDGETS_SHAPE_CACHING
		ShapeCacheInsert( cache, key, shape );
#endif
		ShapeTranslate( shape, origin );
	}

