	void PrebuildShaders()
	{
#if IMPLATFORM_GFX_SUPPORT_CUSTOM_SHADER
		ImWidgetsContext* ctx = gs_pContext;
		IM_ASSERT( ctx != NULL && "PrebuildShaders() requires an active ImWidgets context (call CreateContext() first)" );
		if ( ctx == NULL )
			return;

		if ( ctx->markerShader.program == NULL )
			CreateMarkersShaders( ctx );
		if ( ctx->lineShader.program == NULL )
			CreateInternalShader( &ctx->lineShader, "lines", 0, NULL, 0, NULL );
		if ( ctx->strokeShader.program == NULL )
			CreateInternalShader( &ctx->strokeShader, "stroke", 0, NULL, 0, NULL );
		if ( ctx->imageInspectorShader.program == NULL )
			CreateInternalShader( &ctx->imageInspectorShader, "image_inspector", 0, NULL, 0, NULL );
		if ( ctx->blurShader.program == NULL )
			CreateInternalShader( &ctx->blurShader, "blur", 0, NULL, 0, NULL );

		// Slug family is feature-gated: matches CreateContext() behavior.
		if ( GlobalData.features & ( ImWidgetsFeatures_RichFont | ImWidgetsFeatures_LaTeX ) )
		{
			if ( ctx->slugShader.program == NULL )
				CreateInternalShader( &ctx->slugShader, "slug", 0, NULL, 0, NULL );
			if ( ctx->slugColorShader.program == NULL )
				CreateInternalShader( &ctx->slugColorShader, "slug_color", 0, NULL, 0, NULL );
			if ( ctx->slugGradientShader.program == NULL )
				CreateInternalShader( &ctx->slugGradientShader, "slug_gradient", 0, NULL, 0, NULL );
			if ( ctx->slugDebugShader.program == NULL )
				CreateInternalShader( &ctx->slugDebugShader, "slug_debug", 0, NULL, 0, NULL );
			if ( ctx->slugFillShader.program == NULL )
				CreateInternalShader( &ctx->slugFillShader, "slug_fill", 0, NULL, 0, NULL );
		}
#endif
	}

	void SetFeatures( ImWidgetsFeatures features )
	{
		GlobalData.features = features;
	}

	void AddFeatures( ImWidgetsFeatures features )
	{
		GlobalData.features |= features;
	}

	void RemoveFeature( ImWidgetsFeatures features )
	{
		GlobalData.features &= ~features;
	}

	ImWidgetsContext* CreateContext()
	{
		ImWidgetsContext* ctx = IM_NEW( ImWidgetsContext );
		// Default config: focus on CPU path initially (user can enable GPU path later)
		GlobalData.dashedLinesUseGPU = false;
		// Ensure shader handles are zero-initialized to avoid random garbage checks
		memset(&ctx->blurShader,        0, sizeof(ImDrawShader));
		ctx->blurBackbufferCopy = NULL;
		ctx->blurIntermediate = NULL;
		ctx->blurTexW = ctx->blurTexH = 0;
		memset(&ctx->markerShader,      0, sizeof(ImDrawShader));
		memset(&ctx->lineShader,        0, sizeof(ImDrawShader));
		memset(&ctx->slugShader,        0, sizeof(ImDrawShader));
		memset(&ctx->slugColorShader,   0, sizeof(ImDrawShader));
		memset(&ctx->slugFillShader,    0, sizeof(ImDrawShader));
		memset(&ctx->strokeShader,     0, sizeof(ImDrawShader));
		memset(&ctx->imageInspectorShader, 0, sizeof(ImDrawShader));
		ctx->slugState = NULL;

		// Register debug callback for slug draw commands in ImGui Metrics viewer
		ImGui::GetIO().DebugDrawCmdCallback = SlugDebugDrawCmdCallback;

		if ( gs_pContext == NULL )
			gs_pContext = ctx;

		int width;
		int height;
		width = height = 4;
		int channel = 4;
		ImU8* black_data = ( ImU8* )IM_ALLOC( width * height * channel );
		ImU8* white_data = ( ImU8* )IM_ALLOC( width * height * channel );
		for ( int j = 0; j < height; ++j )
		{
			for ( int i = 0; i < width; ++i )
			{
				black_data[ channel * ( j * height + i ) + 0 ] = 0x00u;
				black_data[ channel * ( j * height + i ) + 1 ] = 0x00u;
				black_data[ channel * ( j * height + i ) + 2 ] = 0x00u;
				black_data[ channel * ( j * height + i ) + 3 ] = 0xFFu;

				white_data[ channel * ( j * height + i ) + 0 ] = 0xFFu;
				white_data[ channel * ( j * height + i ) + 1 ] = 0xFFu;
				white_data[ channel * ( j * height + i ) + 2 ] = 0xFFu;
				white_data[ channel * ( j * height + i ) + 3 ] = 0xFFu;
			}
		}
		// Use new ImPlatform C API for texture creation
		ImPlatform_TextureDesc tex_desc = ImPlatform_TextureDesc_Default( width, height );
		ImTextureID img_white = ImPlatform_CreateTexture( white_data, &tex_desc );
		ImTextureID img_black = ImPlatform_CreateTexture( black_data, &tex_desc );
		IM_FREE( black_data );
		IM_FREE( white_data );

		ctx->blackImg = img_black;
		ctx->whiteImg = img_white;

		OwnTexture( img_black );
		OwnTexture( img_white );

		// Note: Marker shaders are now lazily initialized on first DrawMarker() call
		// This ensures they're created regardless of when AddFeatures() is called
		// The code below is kept for backwards compatibility if features are pre-set
		if ( GlobalData.features & ImWidgetsFeatures_Markers )
			CreateMarkersShaders( ctx );

		if ( GlobalData.features & (ImWidgetsFeatures_RichFont | ImWidgetsFeatures_LaTeX) )
		{
			CreateInternalShader(&ctx->slugShader, "slug", 0, NULL, 0, NULL);
			CreateInternalShader(&ctx->slugColorShader, "slug_color", 0, NULL, 0, NULL);
			CreateInternalShader(&ctx->slugGradientShader, "slug_gradient", 0, NULL, 0, NULL);
			CreateInternalShader(&ctx->slugDebugShader, "slug_debug", 0, NULL, 0, NULL);
			CreateInternalShader(&ctx->slugFillShader, "slug_fill", 0, NULL, 0, NULL);
		}

		return ctx;
	}
	void	OwnTexture( ImTextureID tex )
	{
		gs_pContext->ressources.push_back( tex );
	}

	void	DestroyContext( ImWidgetsContext* ctx )
	{
		if ( ctx != NULL )
		{
			// Clean up resources BEFORE deleting the context
			int img_count = ctx->ressources.size();
			for ( int k = 0; k < img_count; ++k )
			{
				ImPlatform_DestroyTexture( ctx->ressources[ k ] );
			}

#if IMPLATFORM_GFX_SUPPORT_CUSTOM_SHADER
			// Clean up Slug font atlases and GPU textures
			if ( ctx->slugState )
			{
				for ( int k = 0; k < ctx->slugState->atlases.Size; ++k )
					SlugDestroyAtlas( ctx->slugState->atlases[ k ] );
				IM_DELETE( ctx->slugState );
				ctx->slugState = NULL;
			}

			// Clean up Slug shaders
			if ( ctx->slugShader.program )
			{
				ImPlatform_DestroyShaderProgram( ctx->slugShader.program );
				ImPlatform_DestroyShader( ctx->slugShader.vs );
				ImPlatform_DestroyShader( ctx->slugShader.ps );
				memset( &ctx->slugShader, 0, sizeof( ImDrawShader ) );
			}
			if ( ctx->slugColorShader.program )
			{
				ImPlatform_DestroyShaderProgram( ctx->slugColorShader.program );
				ImPlatform_DestroyShader( ctx->slugColorShader.vs );
				ImPlatform_DestroyShader( ctx->slugColorShader.ps );
				memset( &ctx->slugColorShader, 0, sizeof( ImDrawShader ) );
			}
			if ( ctx->slugFillShader.program )
			{
				ImPlatform_DestroyShaderProgram( ctx->slugFillShader.program );
				ImPlatform_DestroyShader( ctx->slugFillShader.vs );
				ImPlatform_DestroyShader( ctx->slugFillShader.ps );
				memset( &ctx->slugFillShader, 0, sizeof( ImDrawShader ) );
			}
			if ( ctx->imageInspectorShader.program )
			{
				ImPlatform_DestroyShaderProgram( ctx->imageInspectorShader.program );
				ImPlatform_DestroyShader( ctx->imageInspectorShader.vs );
				ImPlatform_DestroyShader( ctx->imageInspectorShader.ps );
				memset( &ctx->imageInspectorShader, 0, sizeof( ImDrawShader ) );
			}
#endif  // IMPLATFORM_GFX_SUPPORT_CUSTOM_SHADER

			// If this is the global context, null it out
			if ( ctx == gs_pContext )
				gs_pContext = NULL;

			IM_DELETE( ctx );
		}
	}

	void	SetCurrentContext( ImWidgetsContext* ctx )
	{
		gs_pContext = ctx;
	}

	ImWidgetsContext* GetCurrentContext()
	{
		return gs_pContext;
	}

	ImTextureID GetWhiteTexture()
	{
		return gs_pContext ? gs_pContext->whiteImg : NULL;
	}

