		float r, g, b;
		ImGui::ColorConvertHSVtoRGB( h, ImLerp( 0.0f, 1.0f, t ) * s, ImLerp( 0.5f, 1.0f, t ) * v, r, g, b );
		int const ur = static_cast< int >( 255.0f * r );
