	bool CurveEditor( char const* label, ImCurveEditorData* curve, ImVec2 size )
	{
		ImGuiWindow* window = ImGui::GetCurrentWindow();
		if ( window->SkipItems )
			return false;

		ImGuiContext& g = *GImGui;
		const ImGuiStyle& style = g.Style;
		const ImGuiID id = window->GetID( label );
		ImWidgetsStyle& dwStyle = GetStyle();
		const float w = ( size.x > 0.0f ) ? size.x : ImGui::CalcItemWidth();
		const float h = ( size.y > 0.0f ) ? size.y : dwStyle.CurveEditor_DefaultHeight;

		ImVec2 label_size = ImGui::CalcTextSize( label, NULL, true );
		float fontH = ImGui::GetFontSize();
		float axisLabelMarginLeft = ImGui::CalcTextSize( "-0.00" ).x + 4.0f;
		float axisLabelMarginBottom = fontH + 2.0f;

		const ImRect frame_bb( window->DC.CursorPos + ImVec2( axisLabelMarginLeft, 0.0f ), window->DC.CursorPos + ImVec2( w, h - axisLabelMarginBottom ) );
		const ImRect total_bb( window->DC.CursorPos, ImVec2( frame_bb.Max.x + ( label_size.x > 0.0f ? style.ItemInnerSpacing.x + label_size.x : 0.0f ), window->DC.CursorPos.y + h ) );

		ImGui::ItemSize( total_bb, style.FramePadding.y );
		if ( !ImGui::ItemAdd( total_bb, id, &frame_bb, 0 ) )
			return false;

		bool hovered = ImGui::ItemHoverable( frame_bb, id, g.LastItemData.ItemFlags );
		if ( IsMouseOverExpandButton( id, frame_bb ) ) hovered = false;

		bool value_changed = false;
		int& selected = curve->SelectedIdx;
		int& dragTarget = curve->DragTarget;
		ImVec2 const& rangeMin = curve->RangeMin;
		ImVec2 const& rangeMax = curve->RangeMax;

		const float keyRadius = dwStyle.CurveEditor_KeyRadius;
		const float tangentRadius = dwStyle.CurveEditor_TangentRadius;
		const float hitRadius = dwStyle.CurveEditor_HitRadius;

		// --- PAN (apply before drawing so range is up-to-date) ---
		ImGuiID panKey = id + ImHashStr( "##pan" );
		int* pPanActive = ImGui::GetStateStorage()->GetIntRef( panKey, 0 );
		if ( *pPanActive )
		{
			if ( ImGui::IsMouseDragging( ImGuiMouseButton_Right ) )
			{
				ImVec2 delta = ScreenVecToCurve( g.IO.MouseDelta, frame_bb, rangeMin, rangeMax );
				curve->RangeMin.x -= delta.x;
				curve->RangeMax.x -= delta.x;
				curve->RangeMin.y -= delta.y;
				curve->RangeMax.y -= delta.y;
			}
			if ( ImGui::IsMouseReleased( ImGuiMouseButton_Right ) )
				*pPanActive = 0;
		}

		// --- HIT TESTING (before drawing for hover feedback) ---
		ImDrawList* dl = window->DrawList;
		bool frame_contains_mouse = frame_bb.Contains( g.IO.MousePos );

		// Find hovered key
		int hovered_key = -1;
		float closest_dist_sq = hitRadius * hitRadius;
		for ( int i = 0; i < curve->Keys.Size; ++i )
		{
			ImVec2 kScreen = CurveToScreen( curve->Keys[ i ].Pos, frame_bb, rangeMin, rangeMax );
			float dSq = ImLengthSqr( g.IO.MousePos - kScreen );
			if ( dSq < closest_dist_sq )
			{
				closest_dist_sq = dSq;
				hovered_key = i;
			}
		}

		// Find hovered tangent handle (only for selected key)
		int hovered_tangent = 0; // -1 = left, 1 = right, 0 = none
		if ( selected >= 0 && selected < curve->Keys.Size )
		{
			ImCurveEditorKey const& sk = curve->Keys[ selected ];
			bool showRight = ( sk.Segment == ImCurveEditorSeg_CubicBezier && selected < curve->Keys.Size - 1 );
			bool showLeft = ( selected > 0 && curve->Keys[ selected - 1 ].Segment == ImCurveEditorSeg_CubicBezier );
			float tanHitSq = ( hitRadius + 2.0f ) * ( hitRadius + 2.0f );
			ImVec2 tanLScreen = showLeft ? CurveToScreen( sk.Pos + sk.TangentLeft, frame_bb, rangeMin, rangeMax ) : ImVec2();
			ImVec2 tanRScreen = showRight ? CurveToScreen( sk.Pos + sk.TangentRight, frame_bb, rangeMin, rangeMax ) : ImVec2();
			hovered_tangent = HitTestBezierHandles( g.IO.MousePos, tanLScreen, tanRScreen, showLeft, showRight, tanHitSq );
		}

		// --- DRAWING ---

		// Frame background
		ImU32 frame_col = ImGui::GetColorU32( g.ActiveId == id ? ImGuiCol_FrameBgActive : hovered ? ImGuiCol_FrameBgHovered : ImGuiCol_FrameBg );
		ImGui::RenderFrame( frame_bb.Min, frame_bb.Max, frame_col, true, g.Style.FrameRounding );

		dl->PushClipRect( frame_bb.Min, frame_bb.Max, true );

		// Grid lines
		ImU32 gridCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_CurveEditor_GridMinor ] );
		ImU32 gridColMajor = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_CurveEditor_GridMajor ] );
		int gridDivX = 10;
		int gridDivY = 10;
		for ( int i = 0; i <= gridDivX; ++i )
		{
			float sx = frame_bb.Min.x + ( frame_bb.GetWidth() * i / ( float )gridDivX );
			dl->AddLine( ImVec2( sx, frame_bb.Min.y ), ImVec2( sx, frame_bb.Max.y ), ( i == 0 || i == gridDivX ) ? gridColMajor : gridCol );
		}
		for ( int i = 0; i <= gridDivY; ++i )
		{
			float sy = frame_bb.Min.y + ( frame_bb.GetHeight() * i / ( float )gridDivY );
			dl->AddLine( ImVec2( frame_bb.Min.x, sy ), ImVec2( frame_bb.Max.x, sy ), ( i == 0 || i == gridDivY ) ? gridColMajor : gridCol );
		}

		// Zero lines (if visible)
		{
			ImVec2 zeroScreen = CurveToScreen( ImVec2( 0.0f, 0.0f ), frame_bb, rangeMin, rangeMax );
			ImVec2 oneScreen  = CurveToScreen( ImVec2( 1.0f, 1.0f ), frame_bb, rangeMin, rangeMax );
			ImU32 zeroCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_CurveEditor_ZeroLine ] );
			float zeroThick = dwStyle.CurveEditor_ZeroLineThickness;
			if ( zeroScreen.x > frame_bb.Min.x && zeroScreen.x < frame_bb.Max.x )
				dl->AddLine( ImVec2( zeroScreen.x, frame_bb.Min.y ), ImVec2( zeroScreen.x, frame_bb.Max.y ), zeroCol, zeroThick );
			if ( zeroScreen.y > frame_bb.Min.y && zeroScreen.y < frame_bb.Max.y )
				dl->AddLine( ImVec2( frame_bb.Min.x, zeroScreen.y ), ImVec2( frame_bb.Max.x, zeroScreen.y ), zeroCol, zeroThick );
			// x=1 and y=1 lines
			if ( oneScreen.x > frame_bb.Min.x && oneScreen.x < frame_bb.Max.x )
				dl->AddLine( ImVec2( oneScreen.x, frame_bb.Min.y ), ImVec2( oneScreen.x, frame_bb.Max.y ), zeroCol, zeroThick );
			if ( oneScreen.y > frame_bb.Min.y && oneScreen.y < frame_bb.Max.y )
				dl->AddLine( ImVec2( frame_bb.Min.x, oneScreen.y ), ImVec2( frame_bb.Max.x, oneScreen.y ), zeroCol, zeroThick );
		}

		// Draw curve segments
		ImU32 curveCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_CurveEditor_Line ] );
		float curveThickness = dwStyle.CurveEditor_LineThickness;

		for ( int seg = 0; seg < curve->Keys.Size - 1; ++seg )
		{
			ImCurveEditorKey const& k0 = curve->Keys[ seg ];
			ImCurveEditorKey const& k1 = curve->Keys[ seg + 1 ];
			ImCurveEditorSeg segType = k0.Segment;

			if ( segType == ImCurveEditorSeg_StepStart )
			{
				ImVec2 a = CurveToScreen( k0.Pos, frame_bb, rangeMin, rangeMax );
				ImVec2 b = CurveToScreen( ImVec2( k1.Pos.x, k0.Pos.y ), frame_bb, rangeMin, rangeMax );
				ImVec2 c = CurveToScreen( k1.Pos, frame_bb, rangeMin, rangeMax );
				dl->AddLine( a, b, curveCol, curveThickness );
				dl->AddLine( b, c, curveCol, curveThickness );
			}
			else if ( segType == ImCurveEditorSeg_StepEnd )
			{
				ImVec2 a = CurveToScreen( k0.Pos, frame_bb, rangeMin, rangeMax );
				ImVec2 b = CurveToScreen( ImVec2( k0.Pos.x, k1.Pos.y ), frame_bb, rangeMin, rangeMax );
				ImVec2 c = CurveToScreen( k1.Pos, frame_bb, rangeMin, rangeMax );
				dl->AddLine( a, b, curveCol, curveThickness );
				dl->AddLine( b, c, curveCol, curveThickness );
			}
			else if ( segType == ImCurveEditorSeg_StepCenter )
			{
				float midX = ( k0.Pos.x + k1.Pos.x ) * 0.5f;
				ImVec2 a = CurveToScreen( k0.Pos, frame_bb, rangeMin, rangeMax );
				ImVec2 b = CurveToScreen( ImVec2( midX, k0.Pos.y ), frame_bb, rangeMin, rangeMax );
				ImVec2 c = CurveToScreen( ImVec2( midX, k1.Pos.y ), frame_bb, rangeMin, rangeMax );
				ImVec2 d = CurveToScreen( k1.Pos, frame_bb, rangeMin, rangeMax );
				dl->AddLine( a, b, curveCol, curveThickness );
				dl->AddLine( b, c, curveCol, curveThickness );
				dl->AddLine( c, d, curveCol, curveThickness );
			}
			else if ( segType == ImCurveEditorSeg_Linear )
			{
				ImVec2 a = CurveToScreen( k0.Pos, frame_bb, rangeMin, rangeMax );
				ImVec2 b = CurveToScreen( k1.Pos, frame_bb, rangeMin, rangeMax );
				dl->AddLine( a, b, curveCol, curveThickness );
			}
			else
			{
				// Easing or Bezier: sample polyline
				int sampleCount = 64;
				ImVec2 prev = CurveToScreen( k0.Pos, frame_bb, rangeMin, rangeMax );
				for ( int s = 1; s <= sampleCount; ++s )
				{
					float lx = ImLerp( k0.Pos.x, k1.Pos.x, ( float )s / ( float )sampleCount );
					float ly = CurveEditorSample( *curve, lx );
					ImVec2 cur = CurveToScreen( ImVec2( lx, ly ), frame_bb, rangeMin, rangeMax );
					dl->AddLine( prev, cur, curveCol, curveThickness );
					prev = cur;
				}
			}
		}

		// Draw tangent handles for selected bezier key
		if ( selected >= 0 && selected < curve->Keys.Size )
		{
			ImCurveEditorKey const& sk = curve->Keys[ selected ];
			bool showRight = ( sk.Segment == ImCurveEditorSeg_CubicBezier && selected < curve->Keys.Size - 1 );
			bool showLeft = ( selected > 0 && curve->Keys[ selected - 1 ].Segment == ImCurveEditorSeg_CubicBezier );
			ImVec2 keyScreen = CurveToScreen( sk.Pos, frame_bb, rangeMin, rangeMax );
			ImU32 tangentCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_CurveEditor_TangentLine ] );
			ImU32 tangentHovCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_CurveEditor_TangentHovered ] );
			ImVec2 tanLScreen = showLeft ? CurveToScreen( sk.Pos + sk.TangentLeft, frame_bb, rangeMin, rangeMax ) : ImVec2();
			ImVec2 tanRScreen = showRight ? CurveToScreen( sk.Pos + sk.TangentRight, frame_bb, rangeMin, rangeMax ) : ImVec2();
			DrawBezierHandles( dl, keyScreen, tanLScreen, tanRScreen, showLeft, showRight,
							   hovered_tangent, tangentCol, tangentHovCol, curveThickness, tangentRadius );
		}

		// Draw keys with hover feedback
		for ( int i = 0; i < curve->Keys.Size; ++i )
		{
			ImVec2 kScreen = CurveToScreen( curve->Keys[ i ].Pos, frame_bb, rangeMin, rangeMax );
			bool isSelected = ( i == selected );
			bool isHovered = ( i == hovered_key );
			float radius = isHovered ? keyRadius + 2.0f : keyRadius;
			ImU32 keyCol = ImGui::GetColorU32( dwStyle.Colors[ isSelected ? StyleColor_CurveEditor_KeySelected : ( isHovered ? StyleColor_CurveEditor_KeyHovered : StyleColor_CurveEditor_Key ) ] );
			ImU32 outCol = ImGui::GetColorU32( dwStyle.Colors[ isSelected ? StyleColor_CurveEditor_KeyOutlineSelected : ( isHovered ? StyleColor_CurveEditor_KeyOutlineHovered : StyleColor_CurveEditor_KeyOutline ) ] );
			dl->AddCircleFilled( kScreen, radius, keyCol );
			dl->AddCircle( kScreen, radius, outCol, 0, isSelected ? dwStyle.CurveEditor_KeyOutlineThickness * 1.33f : dwStyle.CurveEditor_KeyOutlineThickness );
		}

		// Hover feedback: crosshair + "add" indicator when hovering empty space
		if ( hovered && frame_contains_mouse && g.ActiveId != id )
		{
			ImVec2 mp = g.IO.MousePos;
			if ( hovered_key >= 0 || hovered_tangent != 0 )
			{
				// Over a key or tangent: show move arrows cursor
				ImGui::SetMouseCursor( ImGuiMouseCursor_Hand );
			}
			else
			{
				// Over empty area: show crosshair and "+" to indicate add
				ImU32 crossCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_CurveEditor_Crosshair ] );
				dl->AddLine( ImVec2( mp.x, frame_bb.Min.y ), ImVec2( mp.x, frame_bb.Max.y ), crossCol, 1.0f );
				dl->AddLine( ImVec2( frame_bb.Min.x, mp.y ), ImVec2( frame_bb.Max.x, mp.y ), crossCol, 1.0f );

				// "+" sign near cursor
				float plusSize = keyRadius;
				float plusOffset = keyRadius * 2.4f;
				ImVec2 pc( mp.x + plusOffset, mp.y - plusOffset );
				ImU32 plusCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_CurveEditor_AddIndicator ] );
				dl->AddLine( ImVec2( pc.x - plusSize, pc.y ), ImVec2( pc.x + plusSize, pc.y ), plusCol, curveThickness );
				dl->AddLine( ImVec2( pc.x, pc.y - plusSize ), ImVec2( pc.x, pc.y + plusSize ), plusCol, curveThickness );

				ImGui::SetMouseCursor( ImGuiMouseCursor_Arrow );
			}
		}

		dl->PopClipRect();

		// Axis labels at frame edges and at 0/1 tick positions
		{
			ImU32 axisTextCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_CurveEditor_AxisLabel ] );
			float pad = 3.0f;
			char buf[ 16 ];

			// Y axis: range min/max (left side, outside frame)
			ImFormatString( buf, sizeof( buf ), "%.3g", rangeMax.y );
			ImVec2 sz = ImGui::CalcTextSize( buf );
			dl->AddText( ImVec2( frame_bb.Min.x - sz.x - pad, frame_bb.Min.y ), axisTextCol, buf );

			ImFormatString( buf, sizeof( buf ), "%.3g", rangeMin.y );
			sz = ImGui::CalcTextSize( buf );
			dl->AddText( ImVec2( frame_bb.Min.x - sz.x - pad, frame_bb.Max.y - sz.y ), axisTextCol, buf );

			// X axis: range min/max (bottom, outside frame)
			ImFormatString( buf, sizeof( buf ), "%.3g", rangeMin.x );
			dl->AddText( ImVec2( frame_bb.Min.x, frame_bb.Max.y + pad ), axisTextCol, buf );

			ImFormatString( buf, sizeof( buf ), "%.3g", rangeMax.x );
			sz = ImGui::CalcTextSize( buf );
			dl->AddText( ImVec2( frame_bb.Max.x - sz.x, frame_bb.Max.y + pad ), axisTextCol, buf );

			// 0 and 1 tick labels on axes (if visible and not too close to range edges)
			ImVec2 zeroS = CurveToScreen( ImVec2( 0.0f, 0.0f ), frame_bb, rangeMin, rangeMax );
			ImVec2 oneS  = CurveToScreen( ImVec2( 1.0f, 1.0f ), frame_bb, rangeMin, rangeMax );
			float edgeThr = 20.0f; // pixels threshold to avoid overlapping with range labels

			// Y=0 label (left side)
			if ( zeroS.y > frame_bb.Min.y + edgeThr && zeroS.y < frame_bb.Max.y - edgeThr )
			{
				sz = ImGui::CalcTextSize( "0" );
				dl->AddText( ImVec2( frame_bb.Min.x - sz.x - pad, zeroS.y - sz.y * 0.5f ), axisTextCol, "0" );
			}
			// Y=1 label (left side)
			if ( oneS.y > frame_bb.Min.y + edgeThr && oneS.y < frame_bb.Max.y - edgeThr )
			{
				sz = ImGui::CalcTextSize( "1" );
				dl->AddText( ImVec2( frame_bb.Min.x - sz.x - pad, oneS.y - sz.y * 0.5f ), axisTextCol, "1" );
			}
			// X=0 label (bottom)
			if ( zeroS.x > frame_bb.Min.x + edgeThr && zeroS.x < frame_bb.Max.x - edgeThr )
			{
				sz = ImGui::CalcTextSize( "0" );
				dl->AddText( ImVec2( zeroS.x - sz.x * 0.5f, frame_bb.Max.y + pad ), axisTextCol, "0" );
			}
			// X=1 label (bottom)
			if ( oneS.x > frame_bb.Min.x + edgeThr && oneS.x < frame_bb.Max.x - edgeThr )
			{
				sz = ImGui::CalcTextSize( "1" );
				dl->AddText( ImVec2( oneS.x - sz.x * 0.5f, frame_bb.Max.y + pad ), axisTextCol, "1" );
			}
		}

		// Border
		dl->AddRect( frame_bb.Min, frame_bb.Max, ImGui::GetColorU32( ImGuiCol_Border ) );

		// Label
		if ( label_size.x > 0.0f )
			ImGui::RenderText( ImVec2( frame_bb.Max.x + style.ItemInnerSpacing.x, frame_bb.Min.y + style.FramePadding.y ), label );

		// --- INTERACTIONS ---
		ImGui::PushID( id );

		// Click on tangent handle: select and start drag
		if ( hovered_tangent != 0 && ImGui::IsMouseClicked( ImGuiMouseButton_Left ) && hovered && frame_contains_mouse )
		{
			dragTarget = hovered_tangent;
			ImGui::SetActiveID( id, window );
			ImGui::SetFocusID( id, window );
			ImGui::FocusWindow( window );
			ImGui::SetKeyOwner( ImGuiKey_MouseLeft, id );
		}
		// Click on key: select and start drag
		else if ( hovered_key >= 0 && ImGui::IsMouseClicked( ImGuiMouseButton_Left ) && hovered && frame_contains_mouse )
		{
			selected = hovered_key;
			dragTarget = 0;
			ImGui::SetActiveID( id, window );
			ImGui::SetFocusID( id, window );
			ImGui::FocusWindow( window );
			ImGui::SetKeyOwner( ImGuiKey_MouseLeft, id );
		}
		// Click on empty area: add key
		else if ( hovered_key == -1 && hovered_tangent == 0 && ImGui::IsMouseClicked( ImGuiMouseButton_Left ) && hovered && frame_contains_mouse )
		{
			ImVec2 curvePos = ScreenToCurve( g.IO.MousePos, frame_bb, rangeMin, rangeMax );
			// Inherit segment type from the left neighbor
			ImCurveEditorSeg newSeg = ImCurveEditorSeg_Linear;
			for ( int i = 0; i < curve->Keys.Size; ++i )
			{
				if ( curve->Keys[ i ].Pos.x < curvePos.x )
					newSeg = curve->Keys[ i ].Segment;
			}
			int newIdx = curve->AddKey( curvePos, newSeg );
			selected = newIdx;
			dragTarget = 0;
			value_changed = true;
			ImGui::SetActiveID( id, window );
			ImGui::SetFocusID( id, window );
			ImGui::FocusWindow( window );
			ImGui::SetKeyOwner( ImGuiKey_MouseLeft, id );
		}

		// Drag
		if ( g.ActiveId == id && ImGui::IsMouseDragging( ImGuiMouseButton_Left ) && selected >= 0 && selected < curve->Keys.Size )
		{
			ImVec2 delta = ScreenVecToCurve( g.IO.MouseDelta, frame_bb, rangeMin, rangeMax );

			if ( dragTarget == 0 )
			{
				// Drag key
				ImVec2 newPos = curve->Keys[ selected ].Pos + delta;
				// Constrain X to not cross adjacent keys
				if ( selected > 0 )
					newPos.x = ImMax( newPos.x, curve->Keys[ selected - 1 ].Pos.x + 1e-4f );
				if ( selected < curve->Keys.Size - 1 )
					newPos.x = ImMin( newPos.x, curve->Keys[ selected + 1 ].Pos.x - 1e-4f );
				curve->Keys[ selected ].Pos = newPos;
				value_changed = true;
			}
			else if ( dragTarget == -1 )
			{
				// Drag left tangent
				ImCurveEditorKey& k = curve->Keys[ selected ];
				k.TangentLeft = k.TangentLeft + delta;
				if ( k.TangentLeft.x > 0.0f ) k.TangentLeft.x = 0.0f;
				EnforceTangentMode( k.TangentLeft, k.TangentRight, k.TangentMode, -1 );
				value_changed = true;
			}
			else if ( dragTarget == 1 )
			{
				// Drag right tangent
				ImCurveEditorKey& k = curve->Keys[ selected ];
				k.TangentRight = k.TangentRight + delta;
				if ( k.TangentRight.x < 0.0f ) k.TangentRight.x = 0.0f;
				EnforceTangentMode( k.TangentLeft, k.TangentRight, k.TangentMode, 1 );
				value_changed = true;
			}
		}

		// Release
		if ( g.ActiveId == id && ImGui::IsMouseReleased( ImGuiMouseButton_Left ) )
		{
			ImGui::ClearActiveID();
		}

		// Right-click: context menu on key, or start pan on empty area
		if ( ImGui::IsMouseClicked( ImGuiMouseButton_Right ) && hovered && frame_contains_mouse )
		{
			if ( hovered_key >= 0 )
			{
				selected = hovered_key;
				ImGui::OpenPopup( "##CurveKeyCtx" );
			}
			else
			{
				*pPanActive = 1;
			}
		}

		// Context menu
		if ( ImGui::BeginPopup( "##CurveKeyCtx" ) )
		{
			if ( selected >= 0 && selected < curve->Keys.Size )
			{
				ImGui::Text( "Key %d: (%.3f, %.3f)", selected, curve->Keys[ selected ].Pos.x, curve->Keys[ selected ].Pos.y );
				ImGui::Separator();

				ImGui::Text( "Segment: %s", CurveEditorSegName( curve->Keys[ selected ].Segment ) );
				if ( ImCurveEditorSegmentMenu( &curve->Keys[ selected ].Segment, curve->Keys[ selected ].Segment ) )
				{
					// When switching to bezier, set reasonable default tangents
					if ( curve->Keys[ selected ].Segment == ImCurveEditorSeg_CubicBezier )
					{
						float segWidth = 0.1f;
						if ( selected < curve->Keys.Size - 1 )
							segWidth = ( curve->Keys[ selected + 1 ].Pos.x - curve->Keys[ selected ].Pos.x ) * 0.33f;
						curve->Keys[ selected ].TangentRight = ImVec2( segWidth, 0.0f );
						if ( selected < curve->Keys.Size - 1 )
						{
							float leftWidth = segWidth;
							curve->Keys[ selected + 1 ].TangentLeft = ImVec2( -leftWidth, 0.0f );
						}
					}
					value_changed = true;
				}
				// Tangent mode submenu (only relevant for bezier keys)
				bool hasBezier = ( curve->Keys[ selected ].Segment == ImCurveEditorSeg_CubicBezier )
					|| ( selected > 0 && curve->Keys[ selected - 1 ].Segment == ImCurveEditorSeg_CubicBezier );
				if ( hasBezier )
				{
					ImGui::Separator();
					ImGui::Text( "Tangent: %s", CurveEditorTangentModeName( curve->Keys[ selected ].TangentMode ) );
					for ( int m = 0; m < ImCurveEditorTangentMode_COUNT; ++m )
					{
						bool isCur = ( curve->Keys[ selected ].TangentMode == m );
						if ( ImGui::MenuItem( CurveEditorTangentModeName( ( ImCurveEditorTangentMode )m ), NULL, isCur ) )
						{
							curve->Keys[ selected ].TangentMode = ( ImCurveEditorTangentMode )m;
							// When switching to mirrored, sync right to match left
							if ( m == ImCurveEditorTangentMode_Mirrored )
							{
								ImVec2& tL = curve->Keys[ selected ].TangentLeft;
								curve->Keys[ selected ].TangentRight = ImVec2( -tL.x, -tL.y );
								if ( curve->Keys[ selected ].TangentRight.x < 0.0f )
									curve->Keys[ selected ].TangentRight.x = 0.0f;
							}
							value_changed = true;
						}
					}
				}

				ImGui::Separator();
				if ( ImGui::MenuItem( "Remove Key", NULL, false, curve->Keys.Size > 2 ) )
				{
					if ( curve->RemoveKey( selected ) )
					{
						selected = -1;
						value_changed = true;
					}
				}
			}
			ImGui::EndPopup();
		}

		// Double-click on key: reset Y to default (midpoint of range)
		if ( hovered_key >= 0 && ImGui::IsMouseDoubleClicked( ImGuiMouseButton_Left ) && hovered && frame_contains_mouse )
		{
			float defaultY = ( rangeMin.y + rangeMax.y ) * 0.5f;
			curve->Keys[ hovered_key ].Pos.y = defaultY;
			selected = hovered_key;
			value_changed = true;
		}

		// Delete key
		if ( selected >= 0 && ImGui::IsKeyPressed( ImGuiKey_Delete ) && hovered )
		{
			if ( curve->RemoveKey( selected ) )
			{
				selected = -1;
				value_changed = true;
			}
		}

		// Arrow key nudging
		if ( selected >= 0 && selected < curve->Keys.Size && hovered )
		{
			ImGui::SetKeyOwner( ImGuiKey_LeftArrow, id );
			ImGui::SetKeyOwner( ImGuiKey_RightArrow, id );
			ImGui::SetKeyOwner( ImGuiKey_UpArrow, id );
			ImGui::SetKeyOwner( ImGuiKey_DownArrow, id );
			float stepX = ( rangeMax.x - rangeMin.x ) / ImMax( frame_bb.GetWidth(), 1.0f );
			float stepY = ( rangeMax.y - rangeMin.y ) / ImMax( frame_bb.GetHeight(), 1.0f );
			if ( ImGui::GetIO().KeyShift )
			{
				stepX *= 10.0f;
				stepY *= 10.0f;
			}
			bool nudged = false;
			ImVec2 newPos = curve->Keys[ selected ].Pos;
			if ( ImGui::IsKeyPressed( ImGuiKey_LeftArrow ) )  { newPos.x -= stepX; nudged = true; }
			if ( ImGui::IsKeyPressed( ImGuiKey_RightArrow ) ) { newPos.x += stepX; nudged = true; }
			if ( ImGui::IsKeyPressed( ImGuiKey_UpArrow ) )    { newPos.y += stepY; nudged = true; }
			if ( ImGui::IsKeyPressed( ImGuiKey_DownArrow ) )  { newPos.y -= stepY; nudged = true; }
			if ( nudged )
			{
				if ( selected > 0 )
					newPos.x = ImMax( newPos.x, curve->Keys[ selected - 1 ].Pos.x + 1e-4f );
				if ( selected < curve->Keys.Size - 1 )
					newPos.x = ImMin( newPos.x, curve->Keys[ selected + 1 ].Pos.x - 1e-4f );
				curve->Keys[ selected ].Pos = newPos;
				value_changed = true;
			}
		}

		// Tooltip on hovered key
		if ( hovered_key >= 0 && hovered_key < curve->Keys.Size && hovered && g.ActiveId != id )
		{
			ImGui::SetTooltip( "Key %d: (%.3f, %.3f)", hovered_key,
				curve->Keys[ hovered_key ].Pos.x, curve->Keys[ hovered_key ].Pos.y );
		}

		ImGui::PopID();

		if ( value_changed )
			ImGui::MarkItemEdited( id );

		// Expand button
		bool* pExpanded = WidgetExpandButton( id, frame_bb );
		if ( pExpanded && *pExpanded )
		{
			if ( BeginExpandedWindow( label, id, pExpanded, ImVec2( 800, 400 ) ) )
			{
				ImVec2 avail = ImGui::GetContentRegionAvail();
				float widgetW = avail.x * 0.75f;
				// Left: widget
				if ( CurveEditor( "##exp", curve, ImVec2( widgetW, avail.y ) ) )
					value_changed = true;
				ImGui::SameLine();
				// Right: info / edit
				ImGui::BeginChild( "##info", ImVec2( 0, avail.y ), ImGuiChildFlags_Borders );
				ImGui::TextUnformatted( "Keys" );
				ImGui::Text( "%d", curve->Keys.Size );
				ImGui::Spacing();
				ImGui::TextUnformatted( "Range X" );
				ImGui::SetNextItemWidth( -FLT_MIN );
				if ( ImGui::DragFloatRange2( "##rxMinMax", &curve->RangeMin.x, &curve->RangeMax.x, 0.01f, -FLT_MAX, FLT_MAX, "%.2f", "%.2f" ) )
				{
					if ( curve->RangeMin.x >= curve->RangeMax.x )
						curve->RangeMax.x = curve->RangeMin.x + 0.01f;
				}
				ImGui::Spacing();
				ImGui::TextUnformatted( "Range Y" );
				ImGui::SetNextItemWidth( -FLT_MIN );
				if ( ImGui::DragFloatRange2( "##ryMinMax", &curve->RangeMin.y, &curve->RangeMax.y, 0.01f, -FLT_MAX, FLT_MAX, "%.2f", "%.2f" ) )
				{
					if ( curve->RangeMin.y >= curve->RangeMax.y )
						curve->RangeMax.y = curve->RangeMin.y + 0.01f;
				}
				if ( curve->SelectedIdx >= 0 && curve->SelectedIdx < curve->Keys.Size )
				{
					ImCurveEditorKey& sk = curve->Keys[ curve->SelectedIdx ];
					ImGui::Separator();
					ImGui::TextUnformatted( "Selected" );
					ImGui::Text( "%d", curve->SelectedIdx );
					ImGui::Spacing();
					ImGui::TextUnformatted( "X" );
					ImGui::SetNextItemWidth( -FLT_MIN );
					if ( ImGui::DragFloat( "##posx", &sk.Pos.x, 0.001f, curve->RangeMin.x, curve->RangeMax.x, "%.3f" ) )
						value_changed = true;
					ImGui::TextUnformatted( "Y" );
					ImGui::SetNextItemWidth( -FLT_MIN );
					if ( ImGui::DragFloat( "##posy", &sk.Pos.y, 0.001f, curve->RangeMin.y, curve->RangeMax.y, "%.3f" ) )
						value_changed = true;
					ImGui::Spacing();
					ImGui::TextUnformatted( "Segment" );
					if ( ImGui::Button( CurveEditorSegName( sk.Segment ), ImVec2( -FLT_MIN, 0 ) ) )
						ImGui::OpenPopup( "##segPopup" );
					if ( ImGui::BeginPopup( "##segPopup" ) )
					{
						if ( ImCurveEditorSegmentMenu( &sk.Segment, sk.Segment ) )
						{
							// When switching to bezier, set reasonable default tangents
							if ( sk.Segment == ImCurveEditorSeg_CubicBezier )
							{
								int si = curve->SelectedIdx;
								float segWidth = 0.1f;
								if ( si < curve->Keys.Size - 1 )
									segWidth = ( curve->Keys[ si + 1 ].Pos.x - sk.Pos.x ) * 0.33f;
								sk.TangentRight = ImVec2( segWidth, 0.0f );
								if ( si < curve->Keys.Size - 1 )
									curve->Keys[ si + 1 ].TangentLeft = ImVec2( -segWidth, 0.0f );
							}
							value_changed = true;
						}
						ImGui::EndPopup();
					}
					// Tangent mode (only for bezier keys)
					bool hasBezier = ( sk.Segment == ImCurveEditorSeg_CubicBezier )
						|| ( curve->SelectedIdx > 0 && curve->Keys[ curve->SelectedIdx - 1 ].Segment == ImCurveEditorSeg_CubicBezier );
					if ( hasBezier )
					{
						if ( TangentModeUI( sk.TangentLeft, sk.TangentRight, sk.TangentMode ) )
							value_changed = true;
					}
				}
				ImGui::EndChild();
			}
			EndExpandedWindow();
		}

		return value_changed;
	}

	//////////////////////////////////////////////////////////////////////////
	// Color Wheel
	//////////////////////////////////////////////////////////////////////////

	static const float kOkLCHMaxChroma = 0.37f;

	static ImU32 ColorWheelSampleDisc( ImColorWheelMode mode, float normRadius, float angle, float thirdAxis )
	{
		float r, g, b;

		if ( mode == ImColorWheelMode_HSV )
		{
			float h = angle / ( 2.0f * IM_PI );
			if ( h < 0.0f ) h += 1.0f;
			if ( h > 1.0f ) h -= 1.0f;
			ImGui::ColorConvertHSVtoRGB( h, normRadius, thirdAxis, r, g, b );
		}
		else // OkLCH
		{
			float h = angle / ( 2.0f * IM_PI );
			if ( h < 0.0f ) h += 1.0f;
			if ( h > 1.0f ) h -= 1.0f;
			float c = normRadius * kOkLCHMaxChroma;
			ColorConvertOKLCHtosRGB( r, g, b, thirdAxis, c, h );
		}

		r = ImClamp( r, 0.0f, 1.0f );
		g = ImClamp( g, 0.0f, 1.0f );
		b = ImClamp( b, 0.0f, 1.0f );

		return IM_COL32( ( int )( r * 255.0f + 0.5f ), ( int )( g * 255.0f + 0.5f ), ( int )( b * 255.0f + 0.5f ), 255 );
	}

	void DrawColorDisc( ImDrawList* pDrawList, ImVec2 center, float radius, ImColorWheelMode mode, float thirdAxis, int numSectors, int numRings )
	{
		ImVec2 const uv = ImGui::GetFontTexUvWhitePixel();
		int totalQuads = numSectors * numRings;
		pDrawList->PrimReserve( totalQuads * 6, totalQuads * 4 );

		float const sectorAngle = 2.0f * IM_PI / ( float )numSectors;

		for ( int ring = 0; ring < numRings; ++ring )
		{
			float innerR = ( float )ring / numRings * radius;
			float outerR = ( float )( ring + 1 ) / numRings * radius;
			float innerNorm = ( float )ring / numRings;
			float outerNorm = ( float )( ring + 1 ) / numRings;

			for ( int sector = 0; sector < numSectors; ++sector )
			{
				float a0 = sector * sectorAngle;
				float a1 = ( sector + 1 ) * sectorAngle;

				ImVec2 p00 = center + ImVec2( ImCos( a0 ) * innerR, ImSin( a0 ) * innerR );
				ImVec2 p10 = center + ImVec2( ImCos( a0 ) * outerR, ImSin( a0 ) * outerR );
				ImVec2 p11 = center + ImVec2( ImCos( a1 ) * outerR, ImSin( a1 ) * outerR );
				ImVec2 p01 = center + ImVec2( ImCos( a1 ) * innerR, ImSin( a1 ) * innerR );

				ImU32 c00 = ColorWheelSampleDisc( mode, innerNorm, a0, thirdAxis );
				ImU32 c10 = ColorWheelSampleDisc( mode, outerNorm, a0, thirdAxis );
				ImU32 c11 = ColorWheelSampleDisc( mode, outerNorm, a1, thirdAxis );
				ImU32 c01 = ColorWheelSampleDisc( mode, innerNorm, a1, thirdAxis );

				ImDrawIdx idx = ( ImDrawIdx )pDrawList->_VtxCurrentIdx;
				pDrawList->PrimWriteIdx( idx + 0 );
				pDrawList->PrimWriteIdx( idx + 1 );
				pDrawList->PrimWriteIdx( idx + 2 );
				pDrawList->PrimWriteIdx( idx + 0 );
				pDrawList->PrimWriteIdx( idx + 2 );
				pDrawList->PrimWriteIdx( idx + 3 );

				pDrawList->PrimWriteVtx( p00, uv, c00 );
				pDrawList->PrimWriteVtx( p10, uv, c10 );
				pDrawList->PrimWriteVtx( p11, uv, c11 );
				pDrawList->PrimWriteVtx( p01, uv, c01 );
			}
		}
	}

	void DrawCircularGradientIndicator( ImDrawList* pDrawList, ImVec2 center, float outerRadius, float innerRadius, float t )
	{
		ImVec2 uv = ImGui::GetFontTexUvWhitePixel();
		int segments = 128;
		pDrawList->PrimReserve( segments * 6, segments * 4 );

		for ( int s = 0; s < segments; ++s )
		{
			float st0 = ( float )s / segments;
			float st1 = ( float )( s + 1 ) / segments;
			float a0 = -IM_PI * 0.5f + st0 * 2.0f * IM_PI;
			float a1 = -IM_PI * 0.5f + st1 * 2.0f * IM_PI;

			ImU32 col0, col1;
			if ( st0 < t )
			{
				// Filled portion: gradient from black (st0=0) to white (st0=t)
				float g0 = ( t > 0.0f ) ? ( st0 / t ) : 0.0f;
				float g1 = ( t > 0.0f ) ? ImMin( st1 / t, 1.0f ) : 0.0f;
				ImU8 gray0 = ( ImU8 )( g0 * 255.0f );
				ImU8 gray1 = ( ImU8 )( g1 * 255.0f );
				col0 = IM_COL32( gray0, gray0, gray0, 255 );
				col1 = IM_COL32( gray1, gray1, gray1, 255 );
			}
			else
			{
				// Unfilled portion: black
				col0 = IM_COL32( 0, 0, 0, 255 );
				col1 = IM_COL32( 0, 0, 0, 255 );
			}

			ImVec2 outer0( center.x + ImCos( a0 ) * outerRadius, center.y + ImSin( a0 ) * outerRadius );
			ImVec2 outer1( center.x + ImCos( a1 ) * outerRadius, center.y + ImSin( a1 ) * outerRadius );
			ImVec2 inner0( center.x + ImCos( a0 ) * innerRadius, center.y + ImSin( a0 ) * innerRadius );
			ImVec2 inner1( center.x + ImCos( a1 ) * innerRadius, center.y + ImSin( a1 ) * innerRadius );

			ImDrawIdx idx = ( ImDrawIdx )pDrawList->_VtxCurrentIdx;
			pDrawList->PrimWriteIdx( idx + 0 );
			pDrawList->PrimWriteIdx( idx + 1 );
			pDrawList->PrimWriteIdx( idx + 2 );
			pDrawList->PrimWriteIdx( idx + 0 );
			pDrawList->PrimWriteIdx( idx + 2 );
			pDrawList->PrimWriteIdx( idx + 3 );

			pDrawList->PrimWriteVtx( outer0, uv, col0 );
			pDrawList->PrimWriteVtx( outer1, uv, col1 );
			pDrawList->PrimWriteVtx( inner1, uv, col1 );
			pDrawList->PrimWriteVtx( inner0, uv, col0 );
		}

		// Ring outlines
		pDrawList->AddCircle( center, outerRadius, ImGui::GetColorU32( ImGuiCol_Border ) );
		pDrawList->AddCircle( center, innerRadius, ImGui::GetColorU32( ImGuiCol_Border ) );
	}

	bool ColorWheel( char const* label, ImVec4* color, ImColorWheelMode mode, float hdr_max, bool fixedIntensity, ImVec2 size )
	{
		ImGuiWindow* window = ImGui::GetCurrentWindow();
		if ( window->SkipItems )
			return false;

		ImGuiContext& g = *GImGui;
		const ImGuiStyle& style = g.Style;
		ImWidgetsStyle& dwStyle = GetStyle();
		const ImGuiID id = window->GetID( label );

		const float w = ( size.x > 0.0f ) ? size.x : ImGui::CalcItemWidth();
		const float sliderHeight = fixedIntensity ? 0.0f : dwStyle.ColorWheel_SliderHeight;
		const float spacing = fixedIntensity ? 0.0f : style.ItemInnerSpacing.y;
		const float discDiameter = w;
		const float discRadius = discDiameter * 0.5f;
		const float totalH = ( size.y > 0.0f ) ? size.y : ( discDiameter + spacing + sliderHeight );

		ImVec2 label_size = ImGui::CalcTextSize( label, NULL, true );

		const ImVec2 discCenter( window->DC.CursorPos.x + discRadius, window->DC.CursorPos.y + discRadius );
		const ImRect disc_bb( window->DC.CursorPos, window->DC.CursorPos + ImVec2( discDiameter, discDiameter ) );
		const ImRect slider_bb( ImVec2( window->DC.CursorPos.x, window->DC.CursorPos.y + discDiameter + spacing ),
								ImVec2( window->DC.CursorPos.x + w, window->DC.CursorPos.y + discDiameter + spacing + sliderHeight ) );
		const ImRect total_bb( window->DC.CursorPos,
							   ImVec2( window->DC.CursorPos.x + w + ( label_size.x > 0.0f ? style.ItemInnerSpacing.x + label_size.x : 0.0f ), window->DC.CursorPos.y + totalH ) );

		ImGui::ItemSize( total_bb, style.FramePadding.y );
		if ( !ImGui::ItemAdd( total_bb, id, &total_bb, 0 ) )
			return false;

		bool hovered = ImGui::ItemHoverable( total_bb, id, g.LastItemData.ItemFlags );
		if ( IsMouseOverExpandButton( id, disc_bb ) ) hovered = false;

		bool value_changed = false;
		float alpha = color->w;

		// --- Convert input color to working space ---
		float hue, sat, thirdAxis;

		if ( mode == ImColorWheelMode_HSV )
		{
			ImGui::ColorConvertRGBtoHSV( color->x, color->y, color->z, hue, sat, thirdAxis );
		}
		else // OkLCH
		{
			float L, C, H;
			ColorConvertsRGBtoOKLCH( L, C, H, color->x, color->y, color->z );
			hue = H;
			sat = ImClamp( C / kOkLCHMaxChroma, 0.0f, 1.0f );
			thirdAxis = L;
		}

		// --- Dot position ---
		float dotAngle = hue * 2.0f * IM_PI;
		float dotRadius = dwStyle.ColorWheel_DotRadius;
		float ringThick = dwStyle.ColorWheel_RingThickness;
		float innerDiscRadius = ringThick > 0.0f ? discRadius - ringThick - 1.0f : discRadius;
		ImVec2 dotPos = discCenter + ImVec2( ImCos( dotAngle ) * sat * innerDiscRadius, ImSin( dotAngle ) * sat * innerDiscRadius );

		// --- HIT TESTING ---
		ImVec2 mp = g.IO.MousePos;
		float dxDisc = mp.x - discCenter.x;
		float dyDisc = mp.y - discCenter.y;
		float distFromCenter = ImSqrt( dxDisc * dxDisc + dyDisc * dyDisc );
		bool mouseInDisc = ( distFromCenter <= discRadius );
		bool mouseInSlider = !fixedIntensity && slider_bb.Contains( mp );

		float dxDot = mp.x - dotPos.x;
		float dyDot = mp.y - dotPos.y;
		float dotDistSq = dxDot * dxDot + dyDot * dyDot;
		float dotHitRadius = dotRadius * 2.0f;
		bool mouseNearDot = ( dotDistSq < dotHitRadius * dotHitRadius );

		// --- Drag state: 0=none, 1=disc, 2=slider ---
		int* pDragMode = ImGui::GetStateStorage()->GetIntRef( id, 0 );

		ImDrawList* dl = window->DrawList;

		// --- DRAWING ---

		// Disc background
		ImU32 frame_col = ImGui::GetColorU32( g.ActiveId == id ? ImGuiCol_FrameBgActive : hovered ? ImGuiCol_FrameBgHovered : ImGuiCol_FrameBg );
		dl->AddCircleFilled( discCenter, discRadius + 1.0f, frame_col );

		// Outer hue ring
		if ( ringThick > 0.0f )
		{
			int ringDivs = 128;
			float ringAngleStep = 2.0f * IM_PI / ( float )ringDivs;
			ImVec2 const uv = ImGui::GetFontTexUvWhitePixel();
			dl->PrimReserve( ringDivs * 6, ringDivs * 4 );

			for ( int i = 0; i < ringDivs; ++i )
			{
				float a0 = i * ringAngleStep;
				float a1 = ( i + 1 ) * ringAngleStep;

				ImVec2 outer0 = discCenter + ImVec2( ImCos( a0 ) * discRadius, ImSin( a0 ) * discRadius );
				ImVec2 outer1 = discCenter + ImVec2( ImCos( a1 ) * discRadius, ImSin( a1 ) * discRadius );
				ImVec2 inner0 = discCenter + ImVec2( ImCos( a0 ) * ( innerDiscRadius + 1.0f ), ImSin( a0 ) * ( innerDiscRadius + 1.0f ) );
				ImVec2 inner1 = discCenter + ImVec2( ImCos( a1 ) * ( innerDiscRadius + 1.0f ), ImSin( a1 ) * ( innerDiscRadius + 1.0f ) );

				float h0 = a0 / ( 2.0f * IM_PI );
				float h1 = a1 / ( 2.0f * IM_PI );

				float r0, g0, b0, r1, g1, b1;
				if ( mode == ImColorWheelMode_OkLCH )
				{
					ColorConvertOKLCHtosRGB( r0, g0, b0, 0.75f, kOkLCHMaxChroma, h0 );
					ColorConvertOKLCHtosRGB( r1, g1, b1, 0.75f, kOkLCHMaxChroma, h1 );
					r0 = ImClamp( r0, 0.0f, 1.0f ); g0 = ImClamp( g0, 0.0f, 1.0f ); b0 = ImClamp( b0, 0.0f, 1.0f );
					r1 = ImClamp( r1, 0.0f, 1.0f ); g1 = ImClamp( g1, 0.0f, 1.0f ); b1 = ImClamp( b1, 0.0f, 1.0f );
				}
				else
				{
					ImGui::ColorConvertHSVtoRGB( h0, 1.0f, 1.0f, r0, g0, b0 );
					ImGui::ColorConvertHSVtoRGB( h1, 1.0f, 1.0f, r1, g1, b1 );
				}

				ImU32 col0 = IM_COL32( ( int )( r0 * 255.0f + 0.5f ), ( int )( g0 * 255.0f + 0.5f ), ( int )( b0 * 255.0f + 0.5f ), 255 );
				ImU32 col1 = IM_COL32( ( int )( r1 * 255.0f + 0.5f ), ( int )( g1 * 255.0f + 0.5f ), ( int )( b1 * 255.0f + 0.5f ), 255 );

				ImDrawIdx idx = ( ImDrawIdx )dl->_VtxCurrentIdx;
				dl->PrimWriteIdx( idx + 0 );
				dl->PrimWriteIdx( idx + 1 );
				dl->PrimWriteIdx( idx + 2 );
				dl->PrimWriteIdx( idx + 0 );
				dl->PrimWriteIdx( idx + 2 );
				dl->PrimWriteIdx( idx + 3 );

				dl->PrimWriteVtx( outer0, uv, col0 );
				dl->PrimWriteVtx( outer1, uv, col1 );
				dl->PrimWriteVtx( inner1, uv, col1 );
				dl->PrimWriteVtx( inner0, uv, col0 );
			}
		}

		// Color disc
		DrawColorDisc( dl, discCenter, innerDiscRadius, mode, thirdAxis, ( int )dwStyle.ColorWheel_DiscSectors, ( int )dwStyle.ColorWheel_DiscRings );

		// Disc outline
		dl->AddCircle( discCenter, discRadius, ImGui::GetColorU32( ImGuiCol_Border ) );
		if ( ringThick > 0.0f )
			dl->AddCircle( discCenter, innerDiscRadius, ImGui::GetColorU32( ImGuiCol_Border ), 0, 0.5f );

		// Radial guide lines: hue line from center to disc edge + saturation ring
		{
			ImU32 crossCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_ColorWheel_Crosshair ] );
			// Hue line: from center through dot to disc edge
			float cosA = ImCos( dotAngle );
			float sinA = ImSin( dotAngle );
			dl->AddLine( discCenter, ImVec2( discCenter.x + cosA * innerDiscRadius, discCenter.y + sinA * innerDiscRadius ), crossCol );
			// Saturation ring at current sat radius
			float satRadius = sat * innerDiscRadius;
			if ( satRadius > 1.0f )
				dl->AddCircle( discCenter, satRadius, crossCol, 0, 1.0f );
		}

		// Control dot (filled with current color)
		bool isDraggingDisc = ( g.ActiveId == id && *pDragMode == 1 );
		ImU32 dotOutCol = ImGui::GetColorU32( dwStyle.Colors[ isDraggingDisc ? StyleColor_ColorWheel_DotOutlineActive : StyleColor_ColorWheel_DotOutline ] );
		{
			// Current selected color for dot fill
			float dr, dg, db;
			if ( mode == ImColorWheelMode_HSV )
				ImGui::ColorConvertHSVtoRGB( hue, sat, thirdAxis, dr, dg, db );
			else
			{
				float c = sat * kOkLCHMaxChroma;
				ColorConvertOKLCHtosRGB( dr, dg, db, thirdAxis, c, hue );
			}
			dr = ImClamp( dr, 0.0f, 1.0f ); dg = ImClamp( dg, 0.0f, 1.0f ); db = ImClamp( db, 0.0f, 1.0f );
			ImU32 dotFillCol = IM_COL32( ( int )( dr * 255.0f + 0.5f ), ( int )( dg * 255.0f + 0.5f ), ( int )( db * 255.0f + 0.5f ), 255 );

			dl->AddCircleFilled( dotPos, dotRadius + 1.0f, IM_COL32( 0, 0, 0, 120 ) ); // Shadow
			dl->AddCircleFilled( dotPos, dotRadius, dotFillCol );
			dl->AddCircle( dotPos, dotRadius, IM_COL32_WHITE, 0, 2.0f ); // White border
			dl->AddCircle( dotPos, dotRadius + 1.0f, dotOutCol, 0, isDraggingDisc ? 2.0f : 1.0f );
		}

		// Master slider (hidden when fixedIntensity)
		if ( !fixedIntensity )
		{
			// Slider background
			ImGui::RenderFrame( slider_bb.Min, slider_bb.Max, ImGui::GetColorU32( ImGuiCol_FrameBg ), true, g.Style.FrameRounding );

			// Slider gradient
			{
				int sliderSegs = 16;
				float segW = slider_bb.GetWidth() / ( float )sliderSegs;
				for ( int i = 0; i < sliderSegs; ++i )
				{
					float t0 = ( float )i / ( float )sliderSegs;
					float t1 = ( float )( i + 1 ) / ( float )sliderSegs;

					float v0 = t0 * hdr_max;
					float v1 = t1 * hdr_max;

					float r0, g0, b0, r1, g1, b1;
					if ( mode == ImColorWheelMode_HSV )
					{
						ImGui::ColorConvertHSVtoRGB( hue, sat, v0, r0, g0, b0 );
						ImGui::ColorConvertHSVtoRGB( hue, sat, v1, r1, g1, b1 );
					}
					else
					{
						float c = sat * kOkLCHMaxChroma;
						ColorConvertOKLCHtosRGB( r0, g0, b0, v0, c, hue );
						ColorConvertOKLCHtosRGB( r1, g1, b1, v1, c, hue );
					}

					r0 = ImClamp( r0, 0.0f, 1.0f ); g0 = ImClamp( g0, 0.0f, 1.0f ); b0 = ImClamp( b0, 0.0f, 1.0f );
					r1 = ImClamp( r1, 0.0f, 1.0f ); g1 = ImClamp( g1, 0.0f, 1.0f ); b1 = ImClamp( b1, 0.0f, 1.0f );

					ImU32 col0 = IM_COL32( ( int )( r0 * 255.0f + 0.5f ), ( int )( g0 * 255.0f + 0.5f ), ( int )( b0 * 255.0f + 0.5f ), 255 );
					ImU32 col1 = IM_COL32( ( int )( r1 * 255.0f + 0.5f ), ( int )( g1 * 255.0f + 0.5f ), ( int )( b1 * 255.0f + 0.5f ), 255 );

					ImVec2 segMin( slider_bb.Min.x + segW * i, slider_bb.Min.y );
					ImVec2 segMax( slider_bb.Min.x + segW * ( i + 1 ), slider_bb.Max.y );
					dl->AddRectFilledMultiColor( segMin, segMax, col0, col1, col1, col0 );
				}
			}

			// Slider border
			dl->AddRect( slider_bb.Min, slider_bb.Max, ImGui::GetColorU32( ImGuiCol_Border ), g.Style.FrameRounding );

			// Slider handle
			{
				float handleT = ImClamp( thirdAxis / hdr_max, 0.0f, 1.0f );
				float handleX = ImLerp( slider_bb.Min.x, slider_bb.Max.x, handleT );
				float handleHalf = 4.0f;
				ImVec2 handleMin( handleX - handleHalf, slider_bb.Min.y - 1.0f );
				ImVec2 handleMax( handleX + handleHalf, slider_bb.Max.y + 1.0f );

				// Fill handle with the current color at this position
				float hr, hg, hb;
				if ( mode == ImColorWheelMode_HSV )
					ImGui::ColorConvertHSVtoRGB( hue, sat, thirdAxis, hr, hg, hb );
				else
				{
					float c = sat * kOkLCHMaxChroma;
					ColorConvertOKLCHtosRGB( hr, hg, hb, thirdAxis, c, hue );
				}
				hr = ImClamp( hr, 0.0f, 1.0f ); hg = ImClamp( hg, 0.0f, 1.0f ); hb = ImClamp( hb, 0.0f, 1.0f );
				ImU32 handleFill = IM_COL32( ( int )( hr * 255.0f + 0.5f ), ( int )( hg * 255.0f + 0.5f ), ( int )( hb * 255.0f + 0.5f ), 255 );

				dl->AddRectFilled( handleMin, handleMax, handleFill, 2.0f );
				dl->AddRect( handleMin, handleMax, IM_COL32_WHITE, 2.0f, 0, 1.5f );
				dl->AddRect( ImVec2( handleMin.x - 0.5f, handleMin.y - 0.5f ), ImVec2( handleMax.x + 0.5f, handleMax.y + 0.5f ), ImGui::GetColorU32( dwStyle.Colors[ StyleColor_ColorWheel_SliderOutline ] ), 2.0f );
			}
		}

		// Label
		if ( label_size.x > 0.0f )
			ImGui::RenderText( ImVec2( disc_bb.Max.x + style.ItemInnerSpacing.x, disc_bb.Min.y + style.FramePadding.y ), label );

		// Hover feedback
		if ( hovered && g.ActiveId != id )
		{
			if ( mouseNearDot || mouseInDisc )
				ImGui::SetMouseCursor( ImGuiMouseCursor_Hand );
		}

		// --- INTERACTIONS ---
		ImGui::PushID( id );

		// Click to start drag
		if ( hovered && ImGui::IsMouseClicked( ImGuiMouseButton_Left ) )
		{
			if ( mouseNearDot || mouseInDisc )
			{
				*pDragMode = 1;
				ImGui::SetActiveID( id, window );
				ImGui::SetFocusID( id, window );
				ImGui::FocusWindow( window );
				ImGui::SetKeyOwner( ImGuiKey_MouseLeft, id );
			}
			else if ( mouseInSlider )
			{
				*pDragMode = 2;
				ImGui::SetActiveID( id, window );
				ImGui::SetFocusID( id, window );
				ImGui::FocusWindow( window );
				ImGui::SetKeyOwner( ImGuiKey_MouseLeft, id );

				// Immediate jump to click position
				thirdAxis = ImClamp( ( mp.x - slider_bb.Min.x ) / slider_bb.GetWidth() * hdr_max, 0.0f, hdr_max );
				value_changed = true;
			}
		}

		// Update during drag
		if ( g.ActiveId == id && ImGui::IsMouseDown( ImGuiMouseButton_Left ) )
		{
			if ( *pDragMode == 1 )
			{
				float angle = ImAtan2( mp.y - discCenter.y, mp.x - discCenter.x );
				float radius = ImMin( ImSqrt( ( mp.x - discCenter.x ) * ( mp.x - discCenter.x ) + ( mp.y - discCenter.y ) * ( mp.y - discCenter.y ) ) / innerDiscRadius, 1.0f );
				hue = angle / ( 2.0f * IM_PI );
				if ( hue < 0.0f ) hue += 1.0f;
				sat = radius;
				value_changed = true;
			}
			else if ( *pDragMode == 2 )
			{
				thirdAxis = ImClamp( ( mp.x - slider_bb.Min.x ) / slider_bb.GetWidth() * hdr_max, 0.0f, hdr_max );
				value_changed = true;
			}
		}

		// Release
		if ( g.ActiveId == id && ImGui::IsMouseReleased( ImGuiMouseButton_Left ) )
		{
			ImGui::ClearActiveID();
			*pDragMode = 0;
		}

		// Double-click on disc center to reset
		if ( hovered && mouseInDisc && ImGui::IsMouseDoubleClicked( ImGuiMouseButton_Left ) )
		{
			sat = 0.0f;
			if ( mode == ImColorWheelMode_HSV )
				thirdAxis = 1.0f;
			else
				thirdAxis = 0.5f;
			ImGui::ClearActiveID();
			*pDragMode = 0;
			value_changed = true;
		}

		// Right-click context menu
		if ( hovered && ( mouseInDisc || mouseInSlider ) && ImGui::IsMouseClicked( ImGuiMouseButton_Right ) )
			ImGui::OpenPopup( "##ColorWheelCtx" );

		if ( ImGui::BeginPopup( "##ColorWheelCtx" ) )
		{
			if ( ImGui::MenuItem( "Reset Color" ) )
			{
				hue = 0.0f;
				sat = 0.0f;
				if ( mode == ImColorWheelMode_HSV )
					thirdAxis = 1.0f;
				else
					thirdAxis = 0.5f;
				alpha = 1.0f;
				value_changed = true;
			}
			if ( ImGui::MenuItem( "Copy Hex" ) )
			{
				float r = color->x, gg = color->y, b = color->z;
				char hex[ 16 ];
				ImFormatString( hex, IM_ARRAYSIZE( hex ), "#%02X%02X%02X%02X",
					( int )( r * 255.0f + 0.5f ), ( int )( gg * 255.0f + 0.5f ),
					( int )( b * 255.0f + 0.5f ), ( int )( alpha * 255.0f + 0.5f ) );
				ImGui::SetClipboardText( hex );
			}
			ImGui::EndPopup();
		}

		// Tooltip
		if ( hovered && ( mouseNearDot || mouseInDisc ) && g.ActiveId != id )
		{
			if ( mode == ImColorWheelMode_HSV )
				ImGui::SetTooltip( "H: %.3f  S: %.3f  V: %.3f\nR: %.3f  G: %.3f  B: %.3f  A: %.2f", hue, sat, thirdAxis, color->x, color->y, color->z, alpha );
			else
				ImGui::SetTooltip( "H: %.3f  C: %.3f  L: %.3f\nR: %.3f  G: %.3f  B: %.3f  A: %.2f", hue, sat * kOkLCHMaxChroma, thirdAxis, color->x, color->y, color->z, alpha );
		}

		ImGui::PopID();

		// Convert back to sRGB
		if ( value_changed )
		{
			if ( mode == ImColorWheelMode_HSV )
			{
				ImGui::ColorConvertHSVtoRGB( hue, sat, thirdAxis, color->x, color->y, color->z );
			}
			else // OkLCH
			{
				float c = sat * kOkLCHMaxChroma;
				ColorConvertOKLCHtosRGB( color->x, color->y, color->z, thirdAxis, c, hue );
			}
			color->w = alpha;
			ImGui::MarkItemEdited( id );
		}

		// Expand button
		bool* pExpanded = WidgetExpandButton( id, disc_bb );
		if ( pExpanded && *pExpanded )
		{
			if ( BeginExpandedWindow( label, id, pExpanded, ImVec2( 800, 400 ) ) )
			{
				ImVec2 avail = ImGui::GetContentRegionAvail();
				float widgetW = avail.x * 0.75f;
				// Left: widget
				if ( ColorWheel( "##exp", color, mode, hdr_max, false, ImVec2( widgetW, avail.y ) ) )
					value_changed = true;
				ImGui::SameLine();
				// Right: info / edit
				ImGui::BeginChild( "##info", ImVec2( 0, avail.y ), ImGuiChildFlags_Borders );
				char const* modeNames[] = { "HSV", "OkLCH" };
				ImGui::TextUnformatted( "Mode" );
				ImGui::TextUnformatted( modeNames[ ImClamp( ( int )mode, 0, 1 ) ] );
				ImGui::Separator();
				float r, g, b;
				ImGui::ColorConvertHSVtoRGB( color->x, color->y, color->z, r, g, b );
				ImGui::TextUnformatted( "R" );
				ImGui::SetNextItemWidth( -FLT_MIN );
				if ( ImGui::DragFloat( "##r", &r, 0.001f, 0.0f, hdr_max, "%.3f" ) ) { float h, s, v; ImGui::ColorConvertRGBtoHSV( r, g, b, h, s, v ); color->x = h; color->y = s; color->z = v; value_changed = true; }
				ImGui::TextUnformatted( "G" );
				ImGui::SetNextItemWidth( -FLT_MIN );
				if ( ImGui::DragFloat( "##g", &g, 0.001f, 0.0f, hdr_max, "%.3f" ) ) { float h, s, v; ImGui::ColorConvertRGBtoHSV( r, g, b, h, s, v ); color->x = h; color->y = s; color->z = v; value_changed = true; }
				ImGui::TextUnformatted( "B" );
				ImGui::SetNextItemWidth( -FLT_MIN );
				if ( ImGui::DragFloat( "##b", &b, 0.001f, 0.0f, hdr_max, "%.3f" ) ) { float h, s, v; ImGui::ColorConvertRGBtoHSV( r, g, b, h, s, v ); color->x = h; color->y = s; color->z = v; value_changed = true; }
				ImGui::TextUnformatted( "A" );
				ImGui::SetNextItemWidth( -FLT_MIN );
				if ( ImGui::DragFloat( "##a", &color->w, 0.001f, 0.0f, 1.0f, "%.3f" ) ) value_changed = true;
				if ( hdr_max > 1.0f )
				{
					ImGui::Spacing();
					ImGui::TextUnformatted( "HDR Max" );
					ImGui::Text( "%.1f", hdr_max );
				}
				ImGui::Separator();
				ImGui::TextUnformatted( "Preview" );
				ImVec4 preview( r, g, b, color->w );
				ImGui::ColorButton( "##preview", preview, 0, ImVec2( ImGui::GetContentRegionAvail().x, 30 ) );
				ImGui::EndChild();
			}
			EndExpandedWindow();
		}

		return value_changed;
	}

	//////////////////////////////////////////////////////////////////////////
	// Primaries Wheel (ColorWheel + circular gradient indicator ring)
	//////////////////////////////////////////////////////////////////////////

	bool PrimariesWheel( char const* label, ImVec4* color, float* yValue, float yMin, float yMax, ImColorWheelMode mode, float ringThickness, ImVec2 size )
	{
		ImGuiWindow* window = ImGui::GetCurrentWindow();
		if ( window->SkipItems )
			return false;

		const ImGuiID id = window->GetID( label );
		const float ringGap = 2.0f;
		const float outerSize = ( size.x > 0.0f ) ? size.x : ImGui::CalcItemWidth();
		const float innerSize = outerSize - 2.0f * ( ringThickness + ringGap );
		const float margin = ringThickness + ringGap;

		ImVec2 startPos = window->DC.CursorPos;
		bool value_changed = false;

		// 1) Draw gradient ring indicator
		ImVec2 center( startPos.x + outerSize * 0.5f, startPos.y + outerSize * 0.5f );
		float outerR = outerSize * 0.5f - 1.0f;
		float innerR = outerR - ringThickness;
		float t = ( yMax > yMin ) ? ImClamp( ( *yValue - yMin ) / ( yMax - yMin ), 0.0f, 1.0f ) : 0.0f;
		DrawCircularGradientIndicator( window->DrawList, center, outerR, innerR, t );

		// 2) Suppress inner ColorWheel's expand button
		bool prevExpanded = s_InsideExpandedWidget;
		s_InsideExpandedWidget = true;

		// 3) Place ColorWheel inside (fixedIntensity, disc-only)
		window->DC.CursorPos = ImVec2( startPos.x + margin, startPos.y + margin );
		if ( ColorWheel( "##cw", color, mode, 1.0f, true, ImVec2( innerSize, innerSize ) ) )
			value_changed = true;

		s_InsideExpandedWidget = prevExpanded;

		// 4) Ensure cursor advances past the full outer area
		window->DC.CursorPos.x = startPos.x;
		if ( window->DC.CursorPos.y < startPos.y + outerSize )
			window->DC.CursorPos.y = startPos.y + outerSize;
		window->DC.CursorMaxPos.x = ImMax( window->DC.CursorMaxPos.x, startPos.x + outerSize );
		window->DC.CursorMaxPos.y = ImMax( window->DC.CursorMaxPos.y, startPos.y + outerSize );

		// 5) Expand button at top-right of outer square
		ImRect outerBB( startPos, startPos + ImVec2( outerSize, outerSize ) );
		bool* pExpanded = WidgetExpandButton( id, outerBB );
		if ( pExpanded && *pExpanded )
		{
			if ( BeginExpandedWindow( label, id, pExpanded, ImVec2( 800, 400 ) ) )
			{
				ImVec2 avail = ImGui::GetContentRegionAvail();
				float widgetW = avail.x * 0.75f;
				float widgetSize = ImMin( widgetW, avail.y );
				// Left: larger PrimariesWheel
				ImGui::SetNextItemWidth( widgetSize );
				if ( PrimariesWheel( "##exp", color, yValue, yMin, yMax, mode, ringThickness ) )
					value_changed = true;
				ImGui::SameLine();
				// Right: controls
				ImGui::BeginChild( "##info", ImVec2( 0, avail.y ), ImGuiChildFlags_Borders );
				ImGui::TextUnformatted( "Y Value" );
				ImGui::SetNextItemWidth( -FLT_MIN );
				if ( ImGui::DragFloat( "##yval", yValue, 0.01f, yMin, yMax, "%.2f" ) )
					value_changed = true;
				ImGui::Spacing();
				ImGui::TextUnformatted( "Red" );
				ImGui::SetNextItemWidth( -FLT_MIN );
				if ( ImGui::DragFloat( "##r", &color->x, 0.01f, 0.0f, 1.0f, "%.3f" ) )
					value_changed = true;
				ImGui::TextUnformatted( "Green" );
				ImGui::SetNextItemWidth( -FLT_MIN );
				if ( ImGui::DragFloat( "##g", &color->y, 0.01f, 0.0f, 1.0f, "%.3f" ) )
					value_changed = true;
				ImGui::TextUnformatted( "Blue" );
				ImGui::SetNextItemWidth( -FLT_MIN );
				if ( ImGui::DragFloat( "##b", &color->z, 0.01f, 0.0f, 1.0f, "%.3f" ) )
					value_changed = true;
				ImGui::EndChild();
			}
			EndExpandedWindow();
		}

		return value_changed;
	}

	//////////////////////////////////////////////////////////////////////////
	// HDR Wheel (PrimariesWheel + two arc sliders)
	//////////////////////////////////////////////////////////////////////////

	// Internal helper: arc slider interaction and drawing
	static bool HDRWheelArcSlider( ImGuiID arcId, ImDrawList* dl, ImVec2 center,
		float outerR, float innerR, float grabR,
		float angleStart, float angleEnd,
		float* value, float vMin, float vMax,
		bool gradient, ImU32 col0, ImU32 col1 )
	{
		ImGuiContext& g = *GImGui;
		ImGuiWindow* window = g.CurrentWindow;
		ImWidgetsStyle& dwStyle = GetStyle();
		float midR = ( outerR + innerR ) * 0.5f;
		float thickness = outerR - innerR;
		bool changed = false;

		float t = ( vMax > vMin ) ? ImClamp( ( *value - vMin ) / ( vMax - vMin ), 0.0f, 1.0f ) : 0.0f;

		// Normalize arc range
		float aStart = angleStart;
		float aEnd = angleEnd;
		if ( aEnd < aStart ) aEnd += 2.0f * IM_PI;
		float span = aEnd - aStart;

		// Interaction: hit-test by distance and angle
		ImVec2 mp = g.IO.MousePos;
		float dx = mp.x - center.x;
		float dy = mp.y - center.y;
		float dist = ImSqrt( dx * dx + dy * dy );
		bool inRing = ( dist >= innerR - grabR && dist <= outerR + grabR );

		bool inArc = false;
		if ( inRing )
		{
			float mouseAngle = ImAtan2( dy, dx );
			float rel = mouseAngle - aStart;
			while ( rel < 0.0f )       rel += 2.0f * IM_PI;
			while ( rel >= 2.0f * IM_PI ) rel -= 2.0f * IM_PI;
			inArc = ( rel <= span + 0.2f );
		}

		ImGui::KeepAliveID( arcId );

		if ( inArc && g.ActiveId == 0 && ImGui::IsMouseClicked( 0, ImGuiInputFlags_None, arcId ) )
		{
			ImGui::SetKeyOwner( ImGuiKey_MouseLeft, arcId );
			ImGui::SetActiveID( arcId, window );
			ImGui::SetFocusID( arcId, window );
			ImGui::FocusWindow( window );
		}

		if ( g.ActiveId == arcId )
		{
			if ( ImGui::IsMouseDown( 0 ) )
			{
				float angle = ImAtan2( dy, dx );
				float rel = angle - aStart;
				while ( rel < 0.0f )       rel += 2.0f * IM_PI;
				while ( rel >= 2.0f * IM_PI ) rel -= 2.0f * IM_PI;
				if ( rel > span )
					t = ( rel - span < 2.0f * IM_PI - rel ) ? 1.0f : 0.0f;
				else
					t = rel / span;
				t = ImClamp( t, 0.0f, 1.0f );
				float newVal = vMin + t * ( vMax - vMin );
				if ( newVal != *value ) { *value = newVal; changed = true; }
				t = ( vMax > vMin ) ? ImClamp( ( *value - vMin ) / ( vMax - vMin ), 0.0f, 1.0f ) : 0.0f;
			}
			else
			{
				ImGui::ClearActiveID();
			}
		}

		bool isActive = ( g.ActiveId == arcId );

		// Drawing
		if ( gradient )
		{
			// Gradient track: segments with interpolated colors
			const int nSeg = 48;
			ImVec2 uv = dl->_Data->TexUvWhitePixel;
			dl->PrimReserve( nSeg * 6, ( nSeg + 1 ) * 2 );
			unsigned int vtxBase = dl->_VtxCurrentIdx;

			ImVec4 c0f = ImGui::ColorConvertU32ToFloat4( col0 );
			ImVec4 c1f = ImGui::ColorConvertU32ToFloat4( col1 );

			for ( int s = 0; s <= nSeg; ++s )
			{
				float frac = ( float )s / ( float )nSeg;
				float a = aStart + frac * span;
				float cs = ImCos( a );
				float sn = ImSin( a );
				ImVec4 ci( c0f.x + ( c1f.x - c0f.x ) * frac,
						   c0f.y + ( c1f.y - c0f.y ) * frac,
						   c0f.z + ( c1f.z - c0f.z ) * frac,
						   c0f.w + ( c1f.w - c0f.w ) * frac );
				ImU32 col = ImGui::ColorConvertFloat4ToU32( ci );
				dl->PrimWriteVtx( ImVec2( center.x + outerR * cs, center.y + outerR * sn ), uv, col );
				dl->PrimWriteVtx( ImVec2( center.x + innerR * cs, center.y + innerR * sn ), uv, col );
			}

			for ( int s = 0; s < nSeg; ++s )
			{
				unsigned int i0 = vtxBase + s * 2;
				dl->PrimWriteIdx( ( ImDrawIdx )( i0 ) );
				dl->PrimWriteIdx( ( ImDrawIdx )( i0 + 1 ) );
				dl->PrimWriteIdx( ( ImDrawIdx )( i0 + 2 ) );
				dl->PrimWriteIdx( ( ImDrawIdx )( i0 + 2 ) );
				dl->PrimWriteIdx( ( ImDrawIdx )( i0 + 1 ) );
				dl->PrimWriteIdx( ( ImDrawIdx )( i0 + 3 ) );
			}
		}
		else
		{
			// Solid track with fill
			ImU32 colTrack = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_SliderRing_Track ] );
			const int arcSegs = 48;
			dl->PathArcTo( center, midR, angleStart, angleEnd, arcSegs );
			dl->PathStroke( colTrack, 0, thickness );

			// Filled portion from start to current value
			float grabAngle = aStart + t * span;
			if ( t > 0.001f )
			{
				dl->PathArcTo( center, midR, angleStart, grabAngle, ( int )( arcSegs * t ) + 2 );
				dl->PathStroke( col0, 0, thickness );
			}
		}

		// Grab handle
		float grabAngle = aStart + t * span;
		ImVec2 grabPos( center.x + midR * ImCos( grabAngle ), center.y + midR * ImSin( grabAngle ) );
		ImU32 colGrab = ImGui::GetColorU32( dwStyle.Colors[ isActive ? StyleColor_SliderRing_GrabActive : StyleColor_SliderRing_Grab ] );
		dl->AddCircleFilled( grabPos, grabR, colGrab );
		dl->AddCircle( grabPos, grabR, ImGui::GetColorU32( ImGuiCol_Border ), 0, 1.5f );

		return changed;
	}

	bool HDRWheel( char const* label, ImVec4* color, float* yValue, float yMin, float yMax,
		float* rightValue, float rightMin, float rightMax,
		float* leftValue, float leftMin, float leftMax,
		ImColorWheelMode mode, float ringThickness, ImVec2 size )
	{
		ImGuiWindow* window = ImGui::GetCurrentWindow();
		if ( window->SkipItems )
			return false;

		ImWidgetsStyle& dwStyle = GetStyle();
		const ImGuiID id = window->GetID( label );

		// Style values
		const float arcGap     = dwStyle.HDRWheel_ArcGap;
		const float arcThick   = dwStyle.HDRWheel_ArcThickness;
		const float arcGrabR   = dwStyle.HDRWheel_ArcGrabRadius;
		const float rightStart = dwStyle.HDRWheel_RightArcStart * ( IM_PI / 180.0f );
		const float rightEnd   = dwStyle.HDRWheel_RightArcEnd   * ( IM_PI / 180.0f );
		const float leftStart  = dwStyle.HDRWheel_LeftArcStart  * ( IM_PI / 180.0f );
		const float leftEnd    = dwStyle.HDRWheel_LeftArcEnd    * ( IM_PI / 180.0f );
		const float ringGap    = 2.0f;

		// Layout
		// size.x is the desired disc+ring footprint (same semantics as PrimariesWheel).
		// Arcs are placed outside that footprint, so the total widget is larger.
		const float discRingSize = ( size.x > 0.0f ) ? size.x : ImGui::CalcItemWidth();
		const float outerSize    = discRingSize + 2.0f * ( arcGrabR + arcThick + arcGap );
		const float halfSize     = outerSize * 0.5f;

		// Radii from outside in
		const float arcOuterR  = halfSize - arcGrabR;
		const float arcInnerR  = arcOuterR - arcThick;
		const float ringOuterR = arcInnerR - arcGap;
		const float ringInnerR = ringOuterR - ringThickness;
		const float innerSize  = ( ringInnerR - ringGap ) * 2.0f;
		const float margin     = halfSize - innerSize * 0.5f;

		ImVec2 startPos = window->DC.CursorPos;
		ImVec2 center( startPos.x + halfSize, startPos.y + halfSize );
		bool value_changed = false;

		// 1) Draw gradient ring indicator
		float yT = ( yMax > yMin ) ? ImClamp( ( *yValue - yMin ) / ( yMax - yMin ), 0.0f, 1.0f ) : 0.0f;
		DrawCircularGradientIndicator( window->DrawList, center, ringOuterR, ringInnerR, yT );

		// 2) Arc sliders
		ImGuiID rightId = id + 1;
		ImGuiID leftId  = id + 2;

		ImU32 colRight    = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_HDRWheel_RightArc ] );
		ImU32 colLeftMin  = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_HDRWheel_LeftArcMin ] );
		ImU32 colLeftMax  = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_HDRWheel_LeftArcMax ] );

		if ( HDRWheelArcSlider( rightId, window->DrawList, center,
				arcOuterR, arcInnerR, arcGrabR, rightStart, rightEnd,
				rightValue, rightMin, rightMax, false, colRight, 0 ) )
			value_changed = true;

		if ( HDRWheelArcSlider( leftId, window->DrawList, center,
				arcOuterR, arcInnerR, arcGrabR, leftStart, leftEnd,
				leftValue, leftMin, leftMax, true, colLeftMin, colLeftMax ) )
			value_changed = true;

		// 3) Suppress inner ColorWheel's expand button
		bool prevExpanded = s_InsideExpandedWidget;
		s_InsideExpandedWidget = true;

		// 4) Place ColorWheel inside (fixedIntensity, disc-only)
		window->DC.CursorPos = ImVec2( startPos.x + margin, startPos.y + margin );
		if ( ColorWheel( "##cw", color, mode, 1.0f, true, ImVec2( innerSize, innerSize ) ) )
			value_changed = true;

		s_InsideExpandedWidget = prevExpanded;

		// 5) Ensure cursor advances past the full outer area
		window->DC.CursorPos.x = startPos.x;
		if ( window->DC.CursorPos.y < startPos.y + outerSize )
			window->DC.CursorPos.y = startPos.y + outerSize;
		window->DC.CursorMaxPos.x = ImMax( window->DC.CursorMaxPos.x, startPos.x + outerSize );
		window->DC.CursorMaxPos.y = ImMax( window->DC.CursorMaxPos.y, startPos.y + outerSize );

		// 6) Expand button at top-right of outer square
		ImRect outerBB( startPos, startPos + ImVec2( outerSize, outerSize ) );
		bool* pExpanded = WidgetExpandButton( id, outerBB );
		if ( pExpanded && *pExpanded )
		{
			if ( BeginExpandedWindow( label, id, pExpanded, ImVec2( 800, 400 ) ) )
			{
				ImVec2 avail = ImGui::GetContentRegionAvail();
				float widgetW = avail.x * 0.75f;
				float widgetSize = ImMin( widgetW, avail.y );
				// Left: larger HDRWheel
				ImGui::SetNextItemWidth( widgetSize );
				if ( HDRWheel( "##exp", color, yValue, yMin, yMax,
						rightValue, rightMin, rightMax, leftValue, leftMin, leftMax,
						mode, ringThickness ) )
					value_changed = true;
				ImGui::SameLine();
				// Right: controls
				ImGui::BeginChild( "##info", ImVec2( 0, avail.y ), ImGuiChildFlags_Borders );
				ImGui::TextUnformatted( "Y Value" );
				ImGui::SetNextItemWidth( -FLT_MIN );
				if ( ImGui::DragFloat( "##yval", yValue, 0.01f, yMin, yMax, "%.2f" ) )
					value_changed = true;
				ImGui::Spacing();
				ImGui::TextUnformatted( "Right Arc" );
				ImGui::SetNextItemWidth( -FLT_MIN );
				if ( ImGui::DragFloat( "##right", rightValue, 0.01f, rightMin, rightMax, "%.2f" ) )
					value_changed = true;
				ImGui::Spacing();
				ImGui::TextUnformatted( "Left Arc" );
				ImGui::SetNextItemWidth( -FLT_MIN );
				if ( ImGui::DragFloat( "##left", leftValue, 0.01f, leftMin, leftMax, "%.2f" ) )
					value_changed = true;
				ImGui::Spacing();
				ImGui::TextUnformatted( "Red" );
				ImGui::SetNextItemWidth( -FLT_MIN );
				if ( ImGui::DragFloat( "##r", &color->x, 0.01f, 0.0f, 1.0f, "%.3f" ) )
					value_changed = true;
				ImGui::TextUnformatted( "Green" );
				ImGui::SetNextItemWidth( -FLT_MIN );
				if ( ImGui::DragFloat( "##g", &color->y, 0.01f, 0.0f, 1.0f, "%.3f" ) )
					value_changed = true;
				ImGui::TextUnformatted( "Blue" );
				ImGui::SetNextItemWidth( -FLT_MIN );
				if ( ImGui::DragFloat( "##b", &color->z, 0.01f, 0.0f, 1.0f, "%.3f" ) )
					value_changed = true;
				ImGui::EndChild();
			}
			EndExpandedWindow();
		}

		return value_changed;
	}

	//////////////////////////////////////////////////////////////////////////
	// Color Picker Collection
	//////////////////////////////////////////////////////////////////////////

	struct ImColorPickerSpaceDesc
	{
		void ( *sRGBToSpace )( float&, float&, float&, float, float, float );
		void ( *spaceToSRGB )( float&, float&, float&, float, float, float );
		const char* axisName[3];
		const char* axisFormat[3];
		float axisMin[3];
		float axisMax[3];
		int planeAxisX, planeAxisY, sliderAxis;
	};

	// 2D plane callback data
	struct ImColorPickerPlaneData
	{
		ImColorPickerSpaceDesc const* desc;
		float sliderValue;
	};

	static ImU32 ColorPickerPlaneCallback( float u, float v, void* pUserData )
	{
		ImColorPickerPlaneData* data = ( ImColorPickerPlaneData* )pUserData;
		ImColorPickerSpaceDesc const& desc = *data->desc;
		float comp[3];
		comp[ desc.sliderAxis ] = data->sliderValue;
		comp[ desc.planeAxisX ] = u;
		comp[ desc.planeAxisY ] = v;
		float r, g, b;
		desc.spaceToSRGB( r, g, b, comp[0], comp[1], comp[2] );
		r = ImSaturate( r ); g = ImSaturate( g ); b = ImSaturate( b );
		return IM_COL32( ( int )( r * 255.0f + 0.5f ), ( int )( g * 255.0f + 0.5f ), ( int )( b * 255.0f + 0.5f ), 255 );
	}

	// 1D component slider callback data
	struct ImColorPickerSlider1DData
	{
		ImColorPickerSpaceDesc const* desc;
		float comp[3];
		int varyAxis;
	};

	static ImU32 ColorPickerSlider1DCallback( float t, void* pUserData )
	{
		ImColorPickerSlider1DData* data = ( ImColorPickerSlider1DData* )pUserData;
		ImColorPickerSpaceDesc const& desc = *data->desc;
		float c[3] = { data->comp[0], data->comp[1], data->comp[2] };
		c[ data->varyAxis ] = t;
		float r, g, b;
		desc.spaceToSRGB( r, g, b, c[0], c[1], c[2] );
		r = ImSaturate( r ); g = ImSaturate( g ); b = ImSaturate( b );
		return IM_COL32( ( int )( r * 255.0f + 0.5f ), ( int )( g * 255.0f + 0.5f ), ( int )( b * 255.0f + 0.5f ), 255 );
	}

	static bool ColorPickerInternal( char const* label, ImVec4* color, ImColorPickerSpaceDesc const& desc )
	{
		ImGuiWindow* window = ImGui::GetCurrentWindow();
		if ( window->SkipItems )
			return false;

		ImGuiContext& g = *GImGui;
		const ImGuiStyle& style = g.Style;
		ImWidgetsStyle& dwStyle = GetStyle();
		const ImGuiID id = window->GetID( label );

		const float w = ImGui::CalcItemWidth();
		const float sliderWidth = dwStyle.ColorPicker_SliderWidth;
		const float compSliderH = dwStyle.ColorPicker_ComponentSliderHeight;
		const float spacing = style.ItemInnerSpacing.x;
		const float vSpacing = style.ItemInnerSpacing.y;
		const float planeSide = w - sliderWidth - spacing;
		const int planeRes = ( int )dwStyle.ColorPicker_PlaneResolution;
		const int sliderRes = ( int )dwStyle.ColorPicker_SliderResolution;
		const float dotRadius = dwStyle.ColorPicker_DotRadius;

		const float totalH = planeSide + vSpacing + ( compSliderH + vSpacing ) * 3.0f;

		ImVec2 label_size = ImGui::CalcTextSize( label, NULL, true );
		const ImVec2 cursorPos = window->DC.CursorPos;

		const ImRect plane_bb( cursorPos, ImVec2( cursorPos.x + planeSide, cursorPos.y + planeSide ) );
		const ImRect vslider_bb( ImVec2( cursorPos.x + planeSide + spacing, cursorPos.y ),
								 ImVec2( cursorPos.x + planeSide + spacing + sliderWidth, cursorPos.y + planeSide ) );
		const float compY0 = cursorPos.y + planeSide + vSpacing;
		ImRect comp_bb[3];
		for ( int i = 0; i < 3; ++i )
		{
			float y = compY0 + ( compSliderH + vSpacing ) * i;
			comp_bb[i] = ImRect( ImVec2( cursorPos.x, y ), ImVec2( cursorPos.x + w, y + compSliderH ) );
		}
		const ImRect total_bb( cursorPos,
			ImVec2( cursorPos.x + w + ( label_size.x > 0.0f ? style.ItemInnerSpacing.x + label_size.x : 0.0f ),
					cursorPos.y + totalH ) );

		ImGui::ItemSize( total_bb, style.FramePadding.y );
		if ( !ImGui::ItemAdd( total_bb, id, &total_bb, 0 ) )
			return false;

		bool hovered = ImGui::ItemHoverable( total_bb, id, g.LastItemData.ItemFlags );
		bool value_changed = false;
		float alpha = color->w;

		// Drag state: 0=none, 1=plane, 2=vslider, 3/4/5=comp0/1/2
		ImGuiStorage* storage = ImGui::GetStateStorage();
		int* pDragMode = storage->GetIntRef( id, 0 );

		// Persistent space-native components to avoid lossy sRGB round-trips
		// during drag (out-of-gamut clamping would corrupt untouched axes).
		const ImGuiID idC0 = id + 0x100;
		const ImGuiID idC1 = id + 0x200;
		const ImGuiID idC2 = id + 0x300;

		float comp[3];
		if ( *pDragMode != 0 && g.ActiveId == id )
		{
			// While dragging, use stored space values as truth
			comp[0] = storage->GetFloat( idC0, 0.0f );
			comp[1] = storage->GetFloat( idC1, 0.0f );
			comp[2] = storage->GetFloat( idC2, 0.0f );
		}
		else
		{
			// Not dragging: derive from sRGB input
			desc.sRGBToSpace( comp[0], comp[1], comp[2], color->x, color->y, color->z );
			storage->SetFloat( idC0, comp[0] );
			storage->SetFloat( idC1, comp[1] );
			storage->SetFloat( idC2, comp[2] );
		}

		ImDrawList* dl = window->DrawList;

		// --- DRAWING ---

		// 2D plane
		{
			ImColorPickerPlaneData cbData;
			cbData.desc = &desc;
			cbData.sliderValue = comp[ desc.sliderAxis ];

			DrawProceduralColor2DBilinear( dl, ColorPickerPlaneCallback, &cbData,
				desc.axisMin[ desc.planeAxisX ], desc.axisMax[ desc.planeAxisX ],
				desc.axisMin[ desc.planeAxisY ], desc.axisMax[ desc.planeAxisY ],
				plane_bb.Min, plane_bb.GetSize(), planeRes, planeRes );
			dl->AddRect( plane_bb.Min, plane_bb.Max, ImGui::GetColorU32( ImGuiCol_Border ) );
		}

		// Dot on plane
		float dotU = ImSaturate( ImNormalize01( comp[ desc.planeAxisX ], desc.axisMin[ desc.planeAxisX ], desc.axisMax[ desc.planeAxisX ] ) );
		float dotV = ImSaturate( ImNormalize01( comp[ desc.planeAxisY ], desc.axisMin[ desc.planeAxisY ], desc.axisMax[ desc.planeAxisY ] ) );
		ImVec2 dotPos( ImLerp( plane_bb.Min.x, plane_bb.Max.x, dotU ),
					   ImLerp( plane_bb.Min.y, plane_bb.Max.y, dotV ) );

		bool isDraggingPlane = ( g.ActiveId == id && *pDragMode == 1 );
		ImU32 dotOutCol = ImGui::GetColorU32( dwStyle.Colors[ isDraggingPlane ? StyleColor_ColorPicker_DotOutlineActive : StyleColor_ColorPicker_DotOutline ] );
		{
			float dr, dg, db;
			desc.spaceToSRGB( dr, dg, db, comp[0], comp[1], comp[2] );
			dr = ImSaturate( dr ); dg = ImSaturate( dg ); db = ImSaturate( db );
			ImU32 dotFill = IM_COL32( ( int )( dr * 255.0f + 0.5f ), ( int )( dg * 255.0f + 0.5f ), ( int )( db * 255.0f + 0.5f ), 255 );
			dl->AddCircleFilled( dotPos, dotRadius + 1.0f, IM_COL32( 0, 0, 0, 120 ) );
			dl->AddCircleFilled( dotPos, dotRadius, dotFill );
			dl->AddCircle( dotPos, dotRadius, IM_COL32_WHITE, 0, 2.0f );
			dl->AddCircle( dotPos, dotRadius + 1.0f, dotOutCol, 0, isDraggingPlane ? 2.0f : 1.0f );
		}

		// Crosshairs on plane
		{
			ImU32 crossCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_ColorPicker_Crosshair ] );
			dl->AddLine( ImVec2( dotPos.x, plane_bb.Min.y ), ImVec2( dotPos.x, plane_bb.Max.y ), crossCol );
			dl->AddLine( ImVec2( plane_bb.Min.x, dotPos.y ), ImVec2( plane_bb.Max.x, dotPos.y ), crossCol );
		}

		// Vertical slider
		{
			int sliderAxis = desc.sliderAxis;
			float sliderSegH = vslider_bb.GetHeight() / ( float )sliderRes;
			for ( int i = 0; i < sliderRes; ++i )
			{
				float t0 = ( float )i / ( float )sliderRes;
				float t1 = ( float )( i + 1 ) / ( float )sliderRes;
				float v0 = ImLerp( desc.axisMin[ sliderAxis ], desc.axisMax[ sliderAxis ], t0 );
				float v1 = ImLerp( desc.axisMin[ sliderAxis ], desc.axisMax[ sliderAxis ], t1 );

				float c0[3] = { comp[0], comp[1], comp[2] };
				float c1[3] = { comp[0], comp[1], comp[2] };
				c0[ sliderAxis ] = v0;
				c1[ sliderAxis ] = v1;

				float r0, g0, b0, r1, g1, b1;
				desc.spaceToSRGB( r0, g0, b0, c0[0], c0[1], c0[2] );
				desc.spaceToSRGB( r1, g1, b1, c1[0], c1[1], c1[2] );
				r0 = ImSaturate( r0 ); g0 = ImSaturate( g0 ); b0 = ImSaturate( b0 );
				r1 = ImSaturate( r1 ); g1 = ImSaturate( g1 ); b1 = ImSaturate( b1 );

				ImU32 col0 = IM_COL32( ( int )( r0 * 255.0f + 0.5f ), ( int )( g0 * 255.0f + 0.5f ), ( int )( b0 * 255.0f + 0.5f ), 255 );
				ImU32 col1 = IM_COL32( ( int )( r1 * 255.0f + 0.5f ), ( int )( g1 * 255.0f + 0.5f ), ( int )( b1 * 255.0f + 0.5f ), 255 );

				ImVec2 segMin( vslider_bb.Min.x, vslider_bb.Min.y + sliderSegH * i );
				ImVec2 segMax( vslider_bb.Max.x, vslider_bb.Min.y + sliderSegH * ( i + 1 ) );
				dl->AddRectFilledMultiColor( segMin, segMax, col0, col0, col1, col1 );
			}
			dl->AddRect( vslider_bb.Min, vslider_bb.Max, ImGui::GetColorU32( dwStyle.Colors[ StyleColor_ColorPicker_SliderOutline ] ) );

			// Slider handle
			float handleT = ImSaturate( ImNormalize01( comp[ sliderAxis ], desc.axisMin[ sliderAxis ], desc.axisMax[ sliderAxis ] ) );
			float handleY = ImLerp( vslider_bb.Min.y, vslider_bb.Max.y, handleT );
			float hh = 3.0f;
			ImVec2 handleMin( vslider_bb.Min.x - 1.0f, handleY - hh );
			ImVec2 handleMax( vslider_bb.Max.x + 1.0f, handleY + hh );

			float hr, hg, hb;
			desc.spaceToSRGB( hr, hg, hb, comp[0], comp[1], comp[2] );
			hr = ImSaturate( hr ); hg = ImSaturate( hg ); hb = ImSaturate( hb );
			ImU32 handleFill = IM_COL32( ( int )( hr * 255.0f + 0.5f ), ( int )( hg * 255.0f + 0.5f ), ( int )( hb * 255.0f + 0.5f ), 255 );

			dl->AddRectFilled( handleMin, handleMax, handleFill, 2.0f );
			dl->AddRect( handleMin, handleMax, ImGui::GetColorU32( dwStyle.Colors[ StyleColor_ColorPicker_SliderHandle ] ), 2.0f, 0, 1.5f );
		}

		// Component sliders
		for ( int ci = 0; ci < 3; ++ci )
		{
			ImColorPickerSlider1DData cbData;
			cbData.desc = &desc;
			cbData.comp[0] = comp[0]; cbData.comp[1] = comp[1]; cbData.comp[2] = comp[2];
			cbData.varyAxis = ci;

			DrawProceduralColor1DBilinear( dl, ColorPickerSlider1DCallback, &cbData,
				desc.axisMin[ci], desc.axisMax[ci],
				comp_bb[ci].Min, comp_bb[ci].GetSize(), 16 );
			dl->AddRect( comp_bb[ci].Min, comp_bb[ci].Max, ImGui::GetColorU32( ImGuiCol_Border ) );

			// Handle
			float t = ImSaturate( ImNormalize01( comp[ci], desc.axisMin[ci], desc.axisMax[ci] ) );
			float handleX = ImLerp( comp_bb[ci].Min.x, comp_bb[ci].Max.x, t );
			float hw = 3.0f;
			ImVec2 hMin( handleX - hw, comp_bb[ci].Min.y - 1.0f );
			ImVec2 hMax( handleX + hw, comp_bb[ci].Max.y + 1.0f );
			dl->AddRectFilled( hMin, hMax, IM_COL32_WHITE, 2.0f );
			dl->AddRect( hMin, hMax, IM_COL32( 0, 0, 0, 180 ), 2.0f );

			// Label
			char compLabel[32];
			ImFormatString( compLabel, IM_ARRAYSIZE( compLabel ), "%s: ", desc.axisName[ci] );
			ImVec2 textSize = ImGui::CalcTextSize( compLabel );
			ImVec2 textPos( comp_bb[ci].Min.x + 2.0f, comp_bb[ci].Min.y + ( compSliderH - textSize.y ) * 0.5f );
			dl->AddText( textPos, IM_COL32_WHITE, compLabel );

			// Value text
			char valStr[32];
			ImFormatString( valStr, IM_ARRAYSIZE( valStr ), desc.axisFormat[ci], comp[ci] );
			ImVec2 valSize = ImGui::CalcTextSize( valStr );
			ImVec2 valPos( comp_bb[ci].Max.x - valSize.x - 2.0f, comp_bb[ci].Min.y + ( compSliderH - valSize.y ) * 0.5f );
			dl->AddText( valPos, IM_COL32_WHITE, valStr );
		}

		// Label
		if ( label_size.x > 0.0f )
			ImGui::RenderText( ImVec2( plane_bb.Max.x + style.ItemInnerSpacing.x, plane_bb.Min.y + style.FramePadding.y ), label );

		// --- HIT TESTING ---
		ImVec2 mp = g.IO.MousePos;
		bool mouseInPlane = plane_bb.Contains( mp );
		bool mouseInVSlider = vslider_bb.Contains( mp );
		int mouseInComp = -1;
		for ( int i = 0; i < 3; ++i )
			if ( comp_bb[i].Contains( mp ) ) mouseInComp = i;

		// Hover cursor
		if ( hovered && g.ActiveId != id )
		{
			if ( mouseInPlane || mouseInVSlider || mouseInComp >= 0 )
				ImGui::SetMouseCursor( ImGuiMouseCursor_Hand );
		}

		// --- INTERACTIONS ---
		ImGui::PushID( id );

		if ( hovered && ImGui::IsMouseClicked( ImGuiMouseButton_Left ) )
		{
			int newMode = 0;
			if ( mouseInPlane ) newMode = 1;
			else if ( mouseInVSlider ) newMode = 2;
			else if ( mouseInComp >= 0 ) newMode = 3 + mouseInComp;

			if ( newMode > 0 )
			{
				*pDragMode = newMode;
				ImGui::SetActiveID( id, window );
				ImGui::SetFocusID( id, window );
				ImGui::FocusWindow( window );
				ImGui::SetKeyOwner( ImGuiKey_MouseLeft, id );
			}
		}

		if ( g.ActiveId == id && ImGui::IsMouseDown( ImGuiMouseButton_Left ) )
		{
			if ( *pDragMode == 1 ) // plane
			{
				float u = ImClamp( ( mp.x - plane_bb.Min.x ) / plane_bb.GetWidth(), 0.0f, 1.0f );
				float v = ImClamp( ( mp.y - plane_bb.Min.y ) / plane_bb.GetHeight(), 0.0f, 1.0f );
				comp[ desc.planeAxisX ] = ImLerp( desc.axisMin[ desc.planeAxisX ], desc.axisMax[ desc.planeAxisX ], u );
				comp[ desc.planeAxisY ] = ImLerp( desc.axisMin[ desc.planeAxisY ], desc.axisMax[ desc.planeAxisY ], v );
				value_changed = true;
			}
			else if ( *pDragMode == 2 ) // vslider
			{
				float t = ImClamp( ( mp.y - vslider_bb.Min.y ) / vslider_bb.GetHeight(), 0.0f, 1.0f );
				comp[ desc.sliderAxis ] = ImLerp( desc.axisMin[ desc.sliderAxis ], desc.axisMax[ desc.sliderAxis ], t );
				value_changed = true;
			}
			else if ( *pDragMode >= 3 && *pDragMode <= 5 ) // component sliders
			{
				int ci = *pDragMode - 3;
				float t = ImClamp( ( mp.x - comp_bb[ci].Min.x ) / comp_bb[ci].GetWidth(), 0.0f, 1.0f );
				comp[ci] = ImLerp( desc.axisMin[ci], desc.axisMax[ci], t );
				value_changed = true;
			}
		}

		if ( g.ActiveId == id && ImGui::IsMouseReleased( ImGuiMouseButton_Left ) )
		{
			ImGui::ClearActiveID();
			*pDragMode = 0;
		}

		ImGui::PopID();

		// Convert back to sRGB
		if ( value_changed )
		{
			// Persist space-native values so next frame doesn't lose them
			storage->SetFloat( idC0, comp[0] );
			storage->SetFloat( idC1, comp[1] );
			storage->SetFloat( idC2, comp[2] );

			desc.spaceToSRGB( color->x, color->y, color->z, comp[0], comp[1], comp[2] );
			color->x = ImSaturate( color->x );
			color->y = ImSaturate( color->y );
			color->z = ImSaturate( color->z );
			color->w = alpha;
			ImGui::MarkItemEdited( id );
		}

		return value_changed;
	}

	// --- Per-space wrappers ---

	// sRGB picker with configurable fixed axis
	static void sRGBIdentity( float& out_a, float& out_b, float& out_c, float a, float b, float c )
	{
		out_a = a; out_b = b; out_c = c;
	}

	bool ColorPickerSRGB( char const* label, ImVec4* color, int fixedAxis, ImVec2 size )
	{
		IM_UNUSED( size );
		int pX, pY, sA;
		switch ( fixedAxis )
		{
		case 0: pX = 1; pY = 2; sA = 0; break; // R fixed -> GB plane
		case 1: pX = 0; pY = 2; sA = 1; break; // G fixed -> RB plane
		default: pX = 0; pY = 1; sA = 2; break; // B fixed -> RG plane
		}
		const char* names[] = { "R", "G", "B" };
		ImColorPickerSpaceDesc desc;
		desc.sRGBToSpace = sRGBIdentity;
		desc.spaceToSRGB = sRGBIdentity;
		desc.axisName[0] = names[0]; desc.axisName[1] = names[1]; desc.axisName[2] = names[2];
		desc.axisFormat[0] = "%.3f"; desc.axisFormat[1] = "%.3f"; desc.axisFormat[2] = "%.3f";
		desc.axisMin[0] = 0.0f; desc.axisMin[1] = 0.0f; desc.axisMin[2] = 0.0f;
		desc.axisMax[0] = 1.0f; desc.axisMax[1] = 1.0f; desc.axisMax[2] = 1.0f;
		desc.planeAxisX = pX; desc.planeAxisY = pY; desc.sliderAxis = sA;
		return ColorPickerInternal( label, color, desc );
	}

	bool ColorPickerHSV( char const* label, ImVec4* color, ImVec2 size )
	{
		IM_UNUSED( size );
		ImColorPickerSpaceDesc desc;
		desc.sRGBToSpace = ColorConvertRGBtoHSV;
		desc.spaceToSRGB = ColorConvertHSVtoRGB;
		desc.axisName[0] = "H"; desc.axisName[1] = "S"; desc.axisName[2] = "V";
		desc.axisFormat[0] = "%.3f"; desc.axisFormat[1] = "%.3f"; desc.axisFormat[2] = "%.3f";
		desc.axisMin[0] = 0.0f; desc.axisMin[1] = 0.0f; desc.axisMin[2] = 0.0f;
		desc.axisMax[0] = 1.0f; desc.axisMax[1] = 1.0f; desc.axisMax[2] = 1.0f;
		desc.planeAxisX = 0; desc.planeAxisY = 1; desc.sliderAxis = 2; // H on X, S on Y, V on slider
		return ColorPickerInternal( label, color, desc );
	}

	bool ColorPickerOkLab( char const* label, ImVec4* color, ImVec2 size )
	{
		IM_UNUSED( size );
		ImColorPickerSpaceDesc desc;
		desc.sRGBToSpace = ColorConvertRGBtoOKLAB;
		desc.spaceToSRGB = ColorConvertOKLABtoRGB;
		desc.axisName[0] = "L"; desc.axisName[1] = "a"; desc.axisName[2] = "b";
		desc.axisFormat[0] = "%.3f"; desc.axisFormat[1] = "%.3f"; desc.axisFormat[2] = "%.3f";
		desc.axisMin[0] = 0.0f; desc.axisMin[1] = -0.4f; desc.axisMin[2] = -0.4f;
		desc.axisMax[0] = 1.0f; desc.axisMax[1] = 0.4f;  desc.axisMax[2] = 0.4f;
		desc.planeAxisX = 1; desc.planeAxisY = 2; desc.sliderAxis = 0; // a on X, b on Y, L on slider
		return ColorPickerInternal( label, color, desc );
	}

	bool ColorPickerOkLCH( char const* label, ImVec4* color, ImVec2 size )
	{
		IM_UNUSED( size );
		ImColorPickerSpaceDesc desc;
		desc.sRGBToSpace = ColorConvertsRGBtoOKLCH;
		desc.spaceToSRGB = ColorConvertOKLCHtosRGB;
		desc.axisName[0] = "L"; desc.axisName[1] = "C"; desc.axisName[2] = "H";
		desc.axisFormat[0] = "%.3f"; desc.axisFormat[1] = "%.3f"; desc.axisFormat[2] = "%.3f";
		desc.axisMin[0] = 0.0f; desc.axisMin[1] = 0.0f; desc.axisMin[2] = 0.0f;
		desc.axisMax[0] = 1.0f; desc.axisMax[1] = 0.4f; desc.axisMax[2] = 1.0f;
		desc.planeAxisX = 1; desc.planeAxisY = 2; desc.sliderAxis = 0; // C on X, H on Y, L on slider
		return ColorPickerInternal( label, color, desc );
	}

	bool ColorPickerCIELab( char const* label, ImVec4* color, ImVec2 size )
	{
		IM_UNUSED( size );
		ImColorPickerSpaceDesc desc;
		desc.sRGBToSpace = ColorConvertsRGBtoCIELab;
		desc.spaceToSRGB = ColorConvertCIELabtosRGB;
		desc.axisName[0] = "L*"; desc.axisName[1] = "a*"; desc.axisName[2] = "b*";
		desc.axisFormat[0] = "%.1f"; desc.axisFormat[1] = "%.1f"; desc.axisFormat[2] = "%.1f";
		desc.axisMin[0] = 0.0f;  desc.axisMin[1] = -128.0f; desc.axisMin[2] = -128.0f;
		desc.axisMax[0] = 100.0f; desc.axisMax[1] = 127.0f;  desc.axisMax[2] = 127.0f;
		desc.planeAxisX = 1; desc.planeAxisY = 2; desc.sliderAxis = 0; // a* on X, b* on Y, L* on slider
		return ColorPickerInternal( label, color, desc );
	}

	// XYZ picker uses xyY for the plane, Y for the slider
	static void sRGBtoxyY_ForPicker( float& out_x, float& out_y, float& out_Y, float r, float g, float b )
	{
		float X, Y, Z;
		ColorConvertsRGBtoXYZ( X, Y, Z, r, g, b );
		ColorConvertXYZtoxyY( out_x, out_y, out_Y, X, Y, Z );
	}
	static void xyYtosRGB_ForPicker( float& out_r, float& out_g, float& out_b, float x, float y, float Y )
	{
		float X, Yout, Z;
		ColorConvertxyYtoXYZ( X, Yout, Z, x, y, Y );
		ColorConvertXYZtosRGB( out_r, out_g, out_b, X, Yout, Z );
	}

	bool ColorPickerXYZ( char const* label, ImVec4* color, ImVec2 size )
	{
		IM_UNUSED( size );
		ImColorPickerSpaceDesc desc;
		desc.sRGBToSpace = sRGBtoxyY_ForPicker;
		desc.spaceToSRGB = xyYtosRGB_ForPicker;
		desc.axisName[0] = "x"; desc.axisName[1] = "y"; desc.axisName[2] = "Y";
		desc.axisFormat[0] = "%.4f"; desc.axisFormat[1] = "%.4f"; desc.axisFormat[2] = "%.3f";
		desc.axisMin[0] = 0.0f; desc.axisMin[1] = 0.0f; desc.axisMin[2] = 0.0f;
		desc.axisMax[0] = 0.8f; desc.axisMax[1] = 0.9f; desc.axisMax[2] = 1.0f;
		desc.planeAxisX = 0; desc.planeAxisY = 1; desc.sliderAxis = 2; // x on X, y on Y, Y on slider
		return ColorPickerInternal( label, color, desc );
	}

	bool ColorPicker( char const* label, ImVec4* color, ImColorPickerSpace space, int fixedAxis, ImVec2 size )
	{
		switch ( space )
		{
		case ImColorPickerSpace_sRGB:  return ColorPickerSRGB( label, color, fixedAxis, size );
		case ImColorPickerSpace_HSV:   return ColorPickerHSV( label, color, size );
		case ImColorPickerSpace_OkLab: return ColorPickerOkLab( label, color, size );
		case ImColorPickerSpace_OkLCH: return ColorPickerOkLCH( label, color, size );
		case ImColorPickerSpace_CIELab: return ColorPickerCIELab( label, color, size );
		case ImColorPickerSpace_XYZ:   return ColorPickerXYZ( label, color, size );
		default: return false;
		}
	}

	//////////////////////////////////////////////////////////////////////////
	// Unit Field
	//////////////////////////////////////////////////////////////////////////

	static float UnitBaseToDisplay( ImUnitDef& u, float base )
	{
		if ( u.toDisplay ) return u.toDisplay( base, u.pUserData );
		return base * u.mul + u.add;
	}

	static float UnitDisplayToBase( ImUnitDef& u, float display )
	{
		if ( u.toBase ) return u.toBase( display, u.pUserData );
		return ( display - u.add ) / u.mul;
	}

	bool UnitField( char const* label, float* pValue, ImUnitDef* units, int unitCount, int* pSelectedUnit, float v_speed, float v_min, float v_max, const char* format )
	{
		ImGuiWindow* window = ImGui::GetCurrentWindow();
		if ( window->SkipItems )
			return false;

		ImGuiContext& g = *GImGui;
		const ImGuiStyle& style = g.Style;
		const ImGuiID id = window->GetID( label );
		const float w = ImGui::CalcItemWidth();
		const float frameH = ImGui::GetFrameHeight();

		const char* fmt = format ? format : "%.3f";
		int sel = *pSelectedUnit;
		if ( sel < 0 || sel >= unitCount ) sel = 0;
		ImUnitDef& unit = units[ sel ];

		// Convert base value to display value
		float displayValue = UnitBaseToDisplay( unit, *pValue );

		// ---- Top row: DragFloat with unit abbreviation ----
		const ImVec2 cursor = window->DC.CursorPos;
		const ImRect frameBB( cursor, ImVec2( cursor.x + w, cursor.y + frameH ) );

		// Format display string with abbreviation
		char valueBuf[ 128 ];
		ImFormatString( valueBuf, IM_ARRAYSIZE( valueBuf ), fmt, displayValue );
		char fullBuf[ 160 ];
		ImFormatString( fullBuf, IM_ARRAYSIZE( fullBuf ), "%s %s", valueBuf, unit.abbreviation );

		// Use DragScalar with custom format that includes abbreviation
		ImGui::PushID( id );
		ImGui::SetNextItemWidth( w );
		bool changed = ImGui::DragFloat( "##drag", &displayValue, v_speed, 0.0f, 0.0f, fullBuf );

		if ( changed )
		{
			float newBase = UnitDisplayToBase( unit, displayValue );
			// Clamp in base unit
			if ( v_min != v_max )
				newBase = ImClamp( newBase, v_min, v_max );
			*pValue = newBase;
		}

		// Label next to the value field (top row)
		const char* labelEnd = ImGui::FindRenderedTextEnd( label );
		if ( label != labelEnd )
		{
			ImGui::SameLine( 0, style.ItemInnerSpacing.x );
			ImGui::TextEx( label, labelEnd );
		}

		// ---- Bottom row: Unit selector (half frame height) ----
		const float selectorH = ImTrunc( frameH * 0.5f );
		const float fontSize = g.FontSize;
		const float smallFontScale = ( selectorH * 0.85f ) / fontSize; // text slightly smaller than row
		// Move cursor up to reduce gap between drag field and selector
		window->DC.CursorPos.y -= style.ItemSpacing.y - 1.0f;
		const ImVec2 selectorPos = window->DC.CursorPos;
		const ImRect selectorBB( selectorPos, ImVec2( selectorPos.x + w, selectorPos.y + selectorH ) );

		ImGui::ItemSize( selectorBB, 0.0f );
		if ( ImGui::ItemAdd( selectorBB, id + 1 ) )
		{
			ImDrawList* dl = window->DrawList;
			const ImU32 frameBg = ImGui::GetColorU32( ImGuiCol_FrameBg );
			const ImU32 borderCol = ImGui::GetColorU32( ImGuiCol_Border );
			const ImU32 textCol = ImGui::GetColorU32( ImGuiCol_Text );
			const ImU32 hoverCol = ImGui::GetColorU32( ImGuiCol_ButtonHovered );
			const ImU32 activeCol = ImGui::GetColorU32( ImGuiCol_ButtonActive );

			dl->AddRectFilled( selectorBB.Min, selectorBB.Max, frameBg, style.FrameRounding );
			dl->AddRect( selectorBB.Min, selectorBB.Max, borderCol, style.FrameRounding );

			// Arrow regions (square based on selector height)
			const float arrowW = selectorH;
			const ImRect leftArrowBB( selectorBB.Min, ImVec2( selectorBB.Min.x + arrowW, selectorBB.Max.y ) );
			const ImRect rightArrowBB( ImVec2( selectorBB.Max.x - arrowW, selectorBB.Min.y ), selectorBB.Max );
			const ImRect nameBB( ImVec2( leftArrowBB.Max.x, selectorBB.Min.y ), ImVec2( rightArrowBB.Min.x, selectorBB.Max.y ) );

			// Interaction
			const ImVec2 mousePos = g.IO.MousePos;
			bool hovLeft = leftArrowBB.Contains( mousePos );
			bool hovRight = rightArrowBB.Contains( mousePos );
			bool hovName = nameBB.Contains( mousePos );
			bool hovAny = selectorBB.Contains( mousePos );

			if ( hovAny && ImGui::IsMouseClicked( 0 ) )
			{
				if ( hovLeft )
					sel = ( sel - 1 + unitCount ) % unitCount;
				else // hovRight or hovName both cycle forward
					sel = ( sel + 1 ) % unitCount;
				*pSelectedUnit = sel;
			}

			const float smallFontSize = fontSize * smallFontScale;
			ImFont* font = g.Font;

			// Draw left arrow "<"
			{
				ImU32 col = hovLeft && ImGui::IsMouseDown( 0 ) ? activeCol : ( hovLeft ? hoverCol : textCol );
				ImVec2 center = leftArrowBB.GetCenter();
				float sz = selectorH * 0.25f;
				dl->AddTriangleFilled(
					ImVec2( center.x - sz, center.y ),
					ImVec2( center.x + sz * 0.5f, center.y - sz ),
					ImVec2( center.x + sz * 0.5f, center.y + sz ),
					col );
			}
			// Draw right arrow ">"
			{
				ImU32 col = hovRight && ImGui::IsMouseDown( 0 ) ? activeCol : ( hovRight ? hoverCol : textCol );
				ImVec2 center = rightArrowBB.GetCenter();
				float sz = selectorH * 0.25f;
				dl->AddTriangleFilled(
					ImVec2( center.x + sz, center.y ),
					ImVec2( center.x - sz * 0.5f, center.y - sz ),
					ImVec2( center.x - sz * 0.5f, center.y + sz ),
					col );
			}
			// Draw unit name centered (small text)
			{
				ImU32 col = ( hovName || hovRight || hovLeft ) ? hoverCol : textCol;
				if ( hovName && ImGui::IsMouseDown( 0 ) ) col = activeCol;
				const char* name = units[ sel ].name;
				ImVec2 textSize = font->CalcTextSizeA( smallFontSize, FLT_MAX, 0.0f, name );
				ImVec2 textPos( nameBB.Min.x + ( nameBB.GetWidth() - textSize.x ) * 0.5f,
								nameBB.Min.y + ( nameBB.GetHeight() - textSize.y ) * 0.5f );
				dl->AddText( font, smallFontSize, textPos, col, name );
			}
		}

		ImGui::PopID();

		return changed;
	}

	//////////////////////////////////////////////////////////////////////////
	// Paint Canvas
	//////////////////////////////////////////////////////////////////////////

	// --- Format helpers ---

	static int PaintBytesPerPixel( ImPlatform_PixelFormat fmt )
	{
		switch ( fmt )
		{
		case ImPlatform_PixelFormat_R8:      return 1;
		case ImPlatform_PixelFormat_RG8:     return 2;
		case ImPlatform_PixelFormat_RGB8:    return 3;
		case ImPlatform_PixelFormat_RGBA8:   return 4;
		case ImPlatform_PixelFormat_R16:     return 2;
		case ImPlatform_PixelFormat_RG16:    return 4;
		case ImPlatform_PixelFormat_RGBA16:  return 8;
		case ImPlatform_PixelFormat_R32F:    return 4;
		case ImPlatform_PixelFormat_RG32F:   return 8;
		case ImPlatform_PixelFormat_RGBA32F: return 16;
		default: return 4;
		}
	}

	static int PaintChannelCount( ImPlatform_PixelFormat fmt )
	{
		switch ( fmt )
		{
		case ImPlatform_PixelFormat_R8:
		case ImPlatform_PixelFormat_R16:
		case ImPlatform_PixelFormat_R32F:    return 1;
		case ImPlatform_PixelFormat_RG8:
		case ImPlatform_PixelFormat_RG16:
		case ImPlatform_PixelFormat_RG32F:   return 2;
		case ImPlatform_PixelFormat_RGB8:    return 3;
		case ImPlatform_PixelFormat_RGBA8:
		case ImPlatform_PixelFormat_RGBA16:
		case ImPlatform_PixelFormat_RGBA32F: return 4;
		default: return 4;
		}
	}

	static void PaintReadPixel( const void* pixels, int w, int x, int y, ImPlatform_PixelFormat fmt, float out[ 4 ] )
	{
		int bpp = PaintBytesPerPixel( fmt );
		const unsigned char* ptr = ( const unsigned char* )pixels + ( y * w + x ) * bpp;
		out[ 0 ] = out[ 1 ] = out[ 2 ] = 0.0f;
		out[ 3 ] = 1.0f;
		switch ( fmt )
		{
		case ImPlatform_PixelFormat_R8:      out[ 0 ] = ptr[ 0 ] / 255.0f; break;
		case ImPlatform_PixelFormat_RG8:     out[ 0 ] = ptr[ 0 ] / 255.0f; out[ 1 ] = ptr[ 1 ] / 255.0f; break;
		case ImPlatform_PixelFormat_RGB8:    out[ 0 ] = ptr[ 0 ] / 255.0f; out[ 1 ] = ptr[ 1 ] / 255.0f; out[ 2 ] = ptr[ 2 ] / 255.0f; break;
		case ImPlatform_PixelFormat_RGBA8:   out[ 0 ] = ptr[ 0 ] / 255.0f; out[ 1 ] = ptr[ 1 ] / 255.0f; out[ 2 ] = ptr[ 2 ] / 255.0f; out[ 3 ] = ptr[ 3 ] / 255.0f; break;
		case ImPlatform_PixelFormat_R16:     out[ 0 ] = ( ( const unsigned short* )ptr )[ 0 ] / 65535.0f; break;
		case ImPlatform_PixelFormat_RG16:    out[ 0 ] = ( ( const unsigned short* )ptr )[ 0 ] / 65535.0f; out[ 1 ] = ( ( const unsigned short* )ptr )[ 1 ] / 65535.0f; break;
		case ImPlatform_PixelFormat_RGBA16:  { const unsigned short* p = ( const unsigned short* )ptr; out[ 0 ] = p[ 0 ] / 65535.0f; out[ 1 ] = p[ 1 ] / 65535.0f; out[ 2 ] = p[ 2 ] / 65535.0f; out[ 3 ] = p[ 3 ] / 65535.0f; break; }
		case ImPlatform_PixelFormat_R32F:    out[ 0 ] = ( ( const float* )ptr )[ 0 ]; break;
		case ImPlatform_PixelFormat_RG32F:   out[ 0 ] = ( ( const float* )ptr )[ 0 ]; out[ 1 ] = ( ( const float* )ptr )[ 1 ]; break;
		case ImPlatform_PixelFormat_RGBA32F: { const float* p = ( const float* )ptr; out[ 0 ] = p[ 0 ]; out[ 1 ] = p[ 1 ]; out[ 2 ] = p[ 2 ]; out[ 3 ] = p[ 3 ]; break; }
		default: break;
		}
	}

	static void PaintWritePixel( void* pixels, int w, int x, int y, ImPlatform_PixelFormat fmt, const float in[ 4 ] )
	{
		int bpp = PaintBytesPerPixel( fmt );
		unsigned char* ptr = ( unsigned char* )pixels + ( y * w + x ) * bpp;
		switch ( fmt )
		{
		case ImPlatform_PixelFormat_R8:      ptr[ 0 ] = ( unsigned char )( ImSaturate( in[ 0 ] ) * 255.0f ); break;
		case ImPlatform_PixelFormat_RG8:     ptr[ 0 ] = ( unsigned char )( ImSaturate( in[ 0 ] ) * 255.0f ); ptr[ 1 ] = ( unsigned char )( ImSaturate( in[ 1 ] ) * 255.0f ); break;
		case ImPlatform_PixelFormat_RGB8:    ptr[ 0 ] = ( unsigned char )( ImSaturate( in[ 0 ] ) * 255.0f ); ptr[ 1 ] = ( unsigned char )( ImSaturate( in[ 1 ] ) * 255.0f ); ptr[ 2 ] = ( unsigned char )( ImSaturate( in[ 2 ] ) * 255.0f ); break;
		case ImPlatform_PixelFormat_RGBA8:   ptr[ 0 ] = ( unsigned char )( ImSaturate( in[ 0 ] ) * 255.0f ); ptr[ 1 ] = ( unsigned char )( ImSaturate( in[ 1 ] ) * 255.0f ); ptr[ 2 ] = ( unsigned char )( ImSaturate( in[ 2 ] ) * 255.0f ); ptr[ 3 ] = ( unsigned char )( ImSaturate( in[ 3 ] ) * 255.0f ); break;
		case ImPlatform_PixelFormat_R16:     ( ( unsigned short* )ptr )[ 0 ] = ( unsigned short )( ImSaturate( in[ 0 ] ) * 65535.0f ); break;
		case ImPlatform_PixelFormat_RG16:    ( ( unsigned short* )ptr )[ 0 ] = ( unsigned short )( ImSaturate( in[ 0 ] ) * 65535.0f ); ( ( unsigned short* )ptr )[ 1 ] = ( unsigned short )( ImSaturate( in[ 1 ] ) * 65535.0f ); break;
		case ImPlatform_PixelFormat_RGBA16:  { unsigned short* p = ( unsigned short* )ptr; p[ 0 ] = ( unsigned short )( ImSaturate( in[ 0 ] ) * 65535.0f ); p[ 1 ] = ( unsigned short )( ImSaturate( in[ 1 ] ) * 65535.0f ); p[ 2 ] = ( unsigned short )( ImSaturate( in[ 2 ] ) * 65535.0f ); p[ 3 ] = ( unsigned short )( ImSaturate( in[ 3 ] ) * 65535.0f ); break; }
		case ImPlatform_PixelFormat_R32F:    ( ( float* )ptr )[ 0 ] = in[ 0 ]; break;
		case ImPlatform_PixelFormat_RG32F:   ( ( float* )ptr )[ 0 ] = in[ 0 ]; ( ( float* )ptr )[ 1 ] = in[ 1 ]; break;
		case ImPlatform_PixelFormat_RGBA32F: { float* p = ( float* )ptr; p[ 0 ] = in[ 0 ]; p[ 1 ] = in[ 1 ]; p[ 2 ] = in[ 2 ]; p[ 3 ] = in[ 3 ]; break; }
		default: break;
		}
	}

	// --- Blending in float space ---

	static void PaintBlendPixel( float dst[ 4 ], const float src[ 4 ], int channels )
	{
		float sa = src[ 3 ];
		if ( sa <= 0.0f )
			return;

		if ( channels < 4 )
		{
			// No alpha channel: lerp each channel using src alpha
			if ( sa >= 1.0f ) { for ( int i = 0; i < channels; i++ ) dst[ i ] = src[ i ]; return; }
			for ( int i = 0; i < channels; i++ )
				dst[ i ] = dst[ i ] * ( 1.0f - sa ) + src[ i ] * sa;
			return;
		}

		// Full alpha compositing (source over)
		if ( sa >= 1.0f ) { for ( int i = 0; i < 4; i++ ) dst[ i ] = src[ i ]; return; }
		float da = dst[ 3 ];
		float oa = sa + da * ( 1.0f - sa );
		if ( oa <= 0.0f ) { for ( int i = 0; i < 4; i++ ) dst[ i ] = 0.0f; return; }
		for ( int i = 0; i < 3; i++ )
			dst[ i ] = ( src[ i ] * sa + dst[ i ] * da * ( 1.0f - sa ) ) / oa;
		dst[ 3 ] = oa;
	}

	// --- Brush ---

	static void PaintApplyBrush( ImPaintCanvasData* canvas, float cx, float cy )
	{
		float r = ImMax( canvas->BrushSize, 0.5f );
		int x0 = ImMax( 0, ( int )( cx - r ) );
		int y0 = ImMax( 0, ( int )( cy - r ) );
		int x1 = ImMin( canvas->Width - 1, ( int )( cx + r ) );
		int y1 = ImMin( canvas->Height - 1, ( int )( cy + r ) );
		float r2 = r * r;
		int channels = PaintChannelCount( canvas->Format );

		for ( int y = y0; y <= y1; y++ )
		{
			for ( int x = x0; x <= x1; x++ )
			{
				float dx = x + 0.5f - cx;
				float dy = y + 0.5f - cy;
				float d2 = dx * dx + dy * dy;
				if ( d2 > r2 ) continue;

				float alpha = canvas->BrushOpacity;
				if ( canvas->Brush == ImPaintBrush_Soft && canvas->Mode != ImPaintMode_BinaryMask && r > 0.0f )
				{
					float t = ImSqrt( d2 ) / r;
					float edge = canvas->BrushHardness;
					if ( t > edge )
						alpha *= 1.0f - ( t - edge ) / ( 1.0f - edge + 1e-5f );
				}

				float dst[ 4 ];
				PaintReadPixel( canvas->Pixels, canvas->Width, x, y, canvas->Format, dst );

				if ( canvas->Tool == ImPaintTool_Eraser )
				{
					// Reduce last channel (alpha if >=4ch, else intensity of ch0)
					if ( channels >= 4 )
						dst[ 3 ] = ImMax( 0.0f, dst[ 3 ] - alpha );
					else
						dst[ 0 ] = ImMax( 0.0f, dst[ 0 ] - alpha );
				}
				else
				{
					float src[ 4 ];
					switch ( canvas->Mode )
					{
					case ImPaintMode_BinaryMask:
						src[ 0 ] = src[ 1 ] = src[ 2 ] = 1.0f;
						src[ 3 ] = alpha;
						break;
					case ImPaintMode_Grayscale:
						src[ 0 ] = src[ 1 ] = src[ 2 ] = canvas->BrushColor.x;
						src[ 3 ] = alpha;
						break;
					default:
						src[ 0 ] = canvas->BrushColor.x;
						src[ 1 ] = canvas->BrushColor.y;
						src[ 2 ] = canvas->BrushColor.z;
						src[ 3 ] = alpha * canvas->BrushColor.w;
						break;
					}
					PaintBlendPixel( dst, src, channels );
				}

				PaintWritePixel( canvas->Pixels, canvas->Width, x, y, canvas->Format, dst );
			}
		}
		canvas->_TexDirty = true;
	}

	static void PaintStrokeTo( ImPaintCanvasData* canvas, float x0, float y0, float x1, float y1 )
	{
		float dx = x1 - x0;
		float dy = y1 - y0;
		float dist = ImSqrt( dx * dx + dy * dy );
		float step = ImMax( 1.0f, canvas->BrushSize * 0.25f );
		int steps = ImMax( 1, ( int )( dist / step ) );

		for ( int i = 1; i <= steps; i++ )
		{
			float t = ( float )i / ( float )steps;
			PaintApplyBrush( canvas, x0 + dx * t, y0 + dy * t );
		}
	}

	// --- Texture management ---

	static void PaintEnsureTexture( ImPaintCanvasData* canvas )
	{
		// Recreate if dimensions or format changed
		if ( canvas->_TexID != ImTextureID_Invalid &&
			( canvas->_TexW != canvas->Width || canvas->_TexH != canvas->Height || canvas->_TexFmt != canvas->Format ) )
		{
			ImPlatform_DestroyTexture( canvas->_TexID );
			canvas->_TexID = ImTextureID_Invalid;
		}

		// Create
		if ( canvas->_TexID == ImTextureID_Invalid )
		{
			ImPlatform_TextureDesc desc = ImPlatform_TextureDesc_Default( canvas->Width, canvas->Height );
			desc.format = canvas->Format;
			desc.min_filter = ImPlatform_TextureFilter_Nearest;
			desc.mag_filter = ImPlatform_TextureFilter_Nearest;
			canvas->_TexID = ImPlatform_CreateTexture( canvas->Pixels, &desc );
			canvas->_TexW = canvas->Width;
			canvas->_TexH = canvas->Height;
			canvas->_TexFmt = canvas->Format;
			canvas->_TexDirty = false;
		}

		// Update
		if ( canvas->_TexDirty )
		{
			ImPlatform_UpdateTexture( canvas->_TexID, canvas->Pixels, 0, 0, canvas->Width, canvas->Height );
			canvas->_TexDirty = false;
		}
	}

	// --- Render ---

	static void PaintRenderCanvas( ImDrawList* dl, ImRect bb, ImPaintCanvasData* canvas )
	{
		// Checkerboard background
		float checkSz = 8.0f;
		ImU32 checkA = IM_COL32( 180, 180, 180, 255 );
		ImU32 checkB = IM_COL32( 220, 220, 220, 255 );
		dl->AddRectFilled( bb.Min, bb.Max, checkA );
		for ( float cy = bb.Min.y; cy < bb.Max.y; cy += checkSz )
		{
			for ( float cx = bb.Min.x; cx < bb.Max.x; cx += checkSz )
			{
				int ix = ( int )( ( cx - bb.Min.x ) / checkSz );
				int iy = ( int )( ( cy - bb.Min.y ) / checkSz );
				if ( ( ix + iy ) & 1 )
				{
					float ex = ImMin( cx + checkSz, bb.Max.x );
					float ey = ImMin( cy + checkSz, bb.Max.y );
					dl->AddRectFilled( ImVec2( cx, cy ), ImVec2( ex, ey ), checkB );
				}
			}
		}

		// Upload and draw texture
		PaintEnsureTexture( canvas );
		if ( canvas->_TexID != ImTextureID_Invalid )
			dl->AddImage( canvas->_TexID, bb.Min, bb.Max );

		// Border
		dl->AddRect( bb.Min, bb.Max, IM_COL32( 128, 128, 128, 255 ) );
	}

	bool PaintCanvas( char const* label, ImPaintCanvasData* canvas, ImVec2 size )
	{
		ImGuiWindow* window = ImGui::GetCurrentWindow();
		if ( window->SkipItems )
			return false;
		if ( !canvas || !canvas->Pixels )
			return false;

		ImGuiContext& g = *GImGui;
		const ImGuiStyle& style = g.Style;
		const ImGuiID id = window->GetID( label );

		if ( size.x <= 0.0f ) size.x = ImGui::CalcItemWidth();
		if ( size.y <= 0.0f ) size.y = size.x * canvas->Height / canvas->Width;

		const ImVec2 pos = window->DC.CursorPos;
		const ImRect bb( pos, ImVec2( pos.x + size.x, pos.y + size.y ) );

		ImGui::ItemSize( bb );
		if ( !ImGui::ItemAdd( bb, id ) )
			return false;

		bool modified = false;
		ImDrawList* dl = window->DrawList;

		// Render
		PaintRenderCanvas( dl, bb, canvas );

		// Mouse mapping
		float pixW = bb.GetWidth() / canvas->Width;
		float pixH = bb.GetHeight() / canvas->Height;
		ImVec2 mp = g.IO.MousePos;
		float cx = ImClamp( ( mp.x - bb.Min.x ) / pixW, 0.0f, ( float )canvas->Width );
		float cy = ImClamp( ( mp.y - bb.Min.y ) / pixH, 0.0f, ( float )canvas->Height );

		bool hovered = ImGui::ItemHoverable( bb, id, g.LastItemData.ItemFlags );
		if ( IsMouseOverExpandButton( id, bb ) ) hovered = false;

		// Click to start painting
		if ( hovered && ImGui::IsMouseClicked( 0, ImGuiInputFlags_None, id ) )
		{
			ImGui::SetActiveID( id, window );
			ImGui::SetFocusID( id, window );
			ImGui::FocusWindow( window );
			ImGui::SetKeyOwner( ImGuiKey_MouseLeft, id );
			canvas->_LastPos = ImVec2( cx, cy );
			PaintApplyBrush( canvas, cx, cy );
			modified = true;
		}
		else if ( g.ActiveId == id )
		{
			if ( ImGui::IsMouseDown( 0 ) )
			{
				float dx = cx - canvas->_LastPos.x;
				float dy = cy - canvas->_LastPos.y;
				if ( dx * dx + dy * dy > 0.25f )
				{
					PaintStrokeTo( canvas, canvas->_LastPos.x, canvas->_LastPos.y, cx, cy );
					canvas->_LastPos = ImVec2( cx, cy );
					modified = true;
				}
			}
			else
			{
				ImGui::ClearActiveID();
			}
		}

		// Brush cursor
		if ( hovered || g.ActiveId == id )
		{
			float screenR = ImMax( canvas->BrushSize * pixW, 1.0f );
			ImGui::GetForegroundDrawList()->AddCircle( mp, screenR, IM_COL32( 255, 255, 255, 200 ), 0, 1.0f );
			ImGui::GetForegroundDrawList()->AddCircle( mp, screenR + 1.0f, IM_COL32( 0, 0, 0, 120 ), 0, 1.0f );
		}

		// Label
		const char* labelEnd = ImGui::FindRenderedTextEnd( label );
		if ( label != labelEnd )
		{
			ImGui::SameLine( 0, style.ItemInnerSpacing.x );
			ImGui::TextEx( label, labelEnd );
		}

		// Expand button
		bool* pExpanded = WidgetExpandButton( id, bb );
		if ( pExpanded && *pExpanded )
		{
			if ( BeginExpandedWindow( label, id, pExpanded, ImVec2( 800, 500 ) ) )
			{
				ImVec2 avail = ImGui::GetContentRegionAvail();
				float panelW = avail.x * 0.75f;
				float panelH = avail.y;
				// Fit canvas in panel preserving aspect ratio
				float aspect = ( float )canvas->Width / ( float )canvas->Height;
				float fitW, fitH;
				if ( panelW / panelH > aspect )
				{
					fitH = panelH;
					fitW = panelH * aspect;
				}
				else
				{
					fitW = panelW;
					fitH = panelW / aspect;
				}
				// Left: canvas
				if ( PaintCanvas( "##exp", canvas, ImVec2( fitW, fitH ) ) )
					modified = true;
				ImGui::SameLine();
				// Right: controls
				ImGui::BeginChild( "##info", ImVec2( 0, avail.y ), ImGuiChildFlags_Borders );

				ImGui::TextUnformatted( "Tool" );
				if ( ImGui::RadioButton( "Brush", canvas->Tool == ImPaintTool_Brush ) ) canvas->Tool = ImPaintTool_Brush;
				ImGui::SameLine();
				if ( ImGui::RadioButton( "Eraser", canvas->Tool == ImPaintTool_Eraser ) ) canvas->Tool = ImPaintTool_Eraser;

				if ( canvas->Mode != ImPaintMode_BinaryMask )
				{
					ImGui::Separator();
					ImGui::TextUnformatted( "Brush" );
					if ( ImGui::RadioButton( "Hard", canvas->Brush == ImPaintBrush_Hard ) ) canvas->Brush = ImPaintBrush_Hard;
					ImGui::SameLine();
					if ( ImGui::RadioButton( "Soft", canvas->Brush == ImPaintBrush_Soft ) ) canvas->Brush = ImPaintBrush_Soft;
				}

				ImGui::Separator();
				ImGui::TextUnformatted( "Size" );
				ImGui::SetNextItemWidth( -FLT_MIN );
				ImGui::SliderFloat( "##size", &canvas->BrushSize, 1.0f, 64.0f, "%.0f" );

				if ( canvas->Mode != ImPaintMode_BinaryMask && canvas->Brush == ImPaintBrush_Soft )
				{
					ImGui::TextUnformatted( "Hardness" );
					ImGui::SetNextItemWidth( -FLT_MIN );
					ImGui::SliderFloat( "##hardness", &canvas->BrushHardness, 0.0f, 1.0f, "%.2f" );
				}

				ImGui::TextUnformatted( "Opacity" );
				ImGui::SetNextItemWidth( -FLT_MIN );
				ImGui::SliderFloat( "##opacity", &canvas->BrushOpacity, 0.0f, 1.0f, "%.2f" );

				if ( canvas->Mode == ImPaintMode_Grayscale )
				{
					ImGui::Separator();
					ImGui::TextUnformatted( "Intensity" );
					ImGui::SetNextItemWidth( -FLT_MIN );
					ImGui::SliderFloat( "##intensity", &canvas->BrushColor.x, 0.0f, 1.0f, "%.2f" );
					canvas->BrushColor.y = canvas->BrushColor.z = canvas->BrushColor.x;
				}
				else if ( canvas->Mode == ImPaintMode_Color )
				{
					ImGui::Separator();
					ImGui::ColorEdit4( "Color", &canvas->BrushColor.x );
				}

				ImGui::Separator();
				if ( ImGui::Button( "Clear" ) )
				{
					int totalBytes = canvas->Width * canvas->Height * PaintBytesPerPixel( canvas->Format );
					memset( canvas->Pixels, 0, totalBytes );
					canvas->_TexDirty = true;
					modified = true;
				}

				ImGui::EndChild();
			}
			EndExpandedWindow();
		}

		return modified;
	}

	//////////////////////////////////////////////////////////////////////////
	// Transform Gizmo
	//////////////////////////////////////////////////////////////////////////

	// Helper: compute object corners from transform + size
	static void ComputeObjectCorners( ImVec2 canvasCenter, float canvasW, float canvasH,
		const ImTransformData& tr, ImVec2 size, ImVec2* corners, ImVec2* edgeMids, ImVec2* outCenter,
		float* outHw, float* outHh, float* outCosR, float* outSinR )
	{
		float imgAR = size.x / size.y;
		float canvasAR = canvasW / canvasH;
		float baseW, baseH;
		if ( imgAR > canvasAR ) { baseW = canvasW; baseH = canvasW / imgAR; }
		else                    { baseH = canvasH; baseW = canvasH * imgAR; }

		float hw = baseW * tr.Scale.x * 0.5f;
		float hh = baseH * tr.Scale.y * 0.5f;
		ImVec2 center( canvasCenter.x + tr.Translation.x,
					   canvasCenter.y + tr.Translation.y );
		float cosR = ImCos( tr.Rotation );
		float sinR = ImSin( tr.Rotation );

		ImVec2 local[ 4 ] = { { -hw, -hh }, { hw, -hh }, { hw, hh }, { -hw, hh } };
		for ( int i = 0; i < 4; ++i )
		{
			float rx = local[ i ].x * cosR - local[ i ].y * sinR;
			float ry = local[ i ].x * sinR + local[ i ].y * cosR;
			corners[ i ] = ImVec2( center.x + rx, center.y + ry );
		}
		if ( edgeMids )
		{
			for ( int i = 0; i < 4; ++i )
				edgeMids[ i ] = ImVec2( ( corners[ i ].x + corners[ ( i + 1 ) % 4 ].x ) * 0.5f,
										( corners[ i ].y + corners[ ( i + 1 ) % 4 ].y ) * 0.5f );
		}
		*outCenter = center;
		*outHw = hw;
		*outHh = hh;
		*outCosR = cosR;
		*outSinR = sinR;
	}

	// Helper: point-in-rotated-rect test
	static bool PointInRotatedRect( ImVec2 point, ImVec2 center, float hw, float hh, float cosR, float sinR )
	{
		float mx = point.x - center.x;
		float my = point.y - center.y;
		float lx =  mx * cosR + my * sinR;
		float ly = -mx * sinR + my * cosR;
		return ( ImFabs( lx ) <= hw && ImFabs( ly ) <= hh );
	}

	bool TransformGizmo( char const* label, ImTransformData* transforms, ImVec2* sizes, int count, int* selectedIndex,
		ImTransformGizmoCallbacks const* callbacks, ImTransformGizmoFlags flags, ImVec2 canvasSize )
	{
		ImGuiWindow* window = ImGui::GetCurrentWindow();
		if ( window->SkipItems )
			return false;

		ImGuiContext& g = *GImGui;
		ImWidgetsStyle& dwStyle = GetStyle();
		const ImGuiID id = window->GetID( label );
		const bool nonUniform = ( flags & ImTransformGizmoFlags_NonUniformScale ) != 0;

		// Style
		const float handleSz     = dwStyle.Gizmo_HandleSize;
		const float rotHandleOff = dwStyle.Gizmo_RotationHandleOffset;
		const float outlineThick = dwStyle.Gizmo_OutlineThickness;
		const ImU32 colCanvas    = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_Gizmo_Canvas ] );
		const ImU32 colOutline   = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_Gizmo_Outline ] );
		const ImU32 colHandle    = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_Gizmo_Handle ] );
		const ImU32 colHandleAct = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_Gizmo_HandleActive ] );
		const ImU32 colBorder    = ImGui::GetColorU32( ImGuiCol_Border );
		const ImU32 colOutlineDim = IM_COL32( 255, 255, 255, 60 );

		// Canvas size
		float cw = ( canvasSize.x > 0.0f ) ? canvasSize.x : ImGui::GetContentRegionAvail().x;
		float ch = ( canvasSize.y > 0.0f ) ? canvasSize.y : 400.0f;

		// Register item
		ImRect canvasBB( window->DC.CursorPos, window->DC.CursorPos + ImVec2( cw, ch ) );
		ImGui::ItemSize( canvasBB );
		if ( !ImGui::ItemAdd( canvasBB, id, &canvasBB ) )
			return false;

		ImDrawList* dl = window->DrawList;
		ImVec2 canvasCenter( canvasBB.Min.x + cw * 0.5f, canvasBB.Min.y + ch * 0.5f );

		// Draw canvas background
		dl->AddRectFilled( canvasBB.Min, canvasBB.Max, colCanvas );
		dl->AddRect( canvasBB.Min, canvasBB.Max, colBorder );
		dl->PushClipRect( canvasBB.Min, canvasBB.Max, true );

		int sel = ( selectedIndex && *selectedIndex >= 0 && *selectedIndex < count ) ? *selectedIndex : -1;

		// Draw all objects (back to front)
		for ( int n = 0; n < count; ++n )
		{
			ImVec2 corners[ 4 ], edgeMids[ 4 ], center;
			float hw, hh, cosR, sinR;
			ComputeObjectCorners( canvasCenter, cw, ch, transforms[ n ], sizes[ n ], corners, edgeMids, &center, &hw, &hh, &cosR, &sinR );

			if ( callbacks && callbacks->DrawFn )
			{
				ImTransformGizmoDrawParams dp;
				dp.DrawList = dl;
				dp.Center   = center;
				dp.HalfW    = hw;  dp.HalfH = hh;
				dp.CosR     = cosR; dp.SinR = sinR;
				dp.Index    = n;
				for ( int i = 0; i < 4; ++i ) dp.Corners[ i ] = corners[ i ];
				callbacks->DrawFn( dp, callbacks->DrawData );
			}

			if ( n == sel )
			{
				// Full outline + handles drawn after all images
			}
			else
			{
				// Dim outline for unselected images
				for ( int i = 0; i < 4; ++i )
					dl->AddLine( corners[ i ], corners[ ( i + 1 ) % 4 ], colOutlineDim, 1.0f );
			}
		}

		// Draw handles for selected image
		ImVec2 selCorners[ 4 ] = {};
		ImVec2 selEdgeMids[ 4 ] = {};
		ImVec2 selCenter = canvasCenter;
		float selHw = 0, selHh = 0, selCosR = 1, selSinR = 0;
		ImVec2 rotHandle = canvasCenter;

		if ( sel >= 0 )
		{
			ComputeObjectCorners( canvasCenter, cw, ch, transforms[ sel ], sizes[ sel ], selCorners, selEdgeMids,
				&selCenter, &selHw, &selHh, &selCosR, &selSinR );

			// Bounding box outline
			for ( int i = 0; i < 4; ++i )
				dl->AddLine( selCorners[ i ], selCorners[ ( i + 1 ) % 4 ], colOutline, outlineThick );

			// Rotation handle
			ImVec2 topMid = selEdgeMids[ 0 ]; // midpoint of TL-TR edge
			ImVec2 upDir( selSinR, -selCosR );
			rotHandle = ImVec2( topMid.x + upDir.x * rotHandleOff,
								topMid.y + upDir.y * rotHandleOff );
			dl->AddLine( topMid, rotHandle, colOutline, 1.0f );

			// Determine active action for coloring
			ImGuiStorage* storage = &window->StateStorage;
			const ImGuiID actionKey = id + 1000;
			const ImGuiID handleKey = id + 1001;
			int curAction = ( g.ActiveId == id ) ? storage->GetInt( actionKey, 0 ) : 0;
			int curHandle = storage->GetInt( handleKey, -1 );

			// Corner handles
			for ( int i = 0; i < 4; ++i )
			{
				bool active = ( curAction == 2 && curHandle == i );
				ImU32 hCol = active ? colHandleAct : colHandle;
				dl->AddRectFilled( selCorners[ i ] - ImVec2( handleSz, handleSz ),
								   selCorners[ i ] + ImVec2( handleSz, handleSz ), hCol );
				dl->AddRect( selCorners[ i ] - ImVec2( handleSz, handleSz ),
							 selCorners[ i ] + ImVec2( handleSz, handleSz ), colBorder );
			}

			// Edge midpoint handles (non-uniform scale)
			if ( nonUniform )
			{
				float edgeSz = handleSz * 0.8f;
				for ( int i = 0; i < 4; ++i )
				{
					bool active = ( curAction == 4 && curHandle == i );
					ImU32 hCol = active ? colHandleAct : colHandle;
					dl->AddRectFilled( selEdgeMids[ i ] - ImVec2( edgeSz, edgeSz ),
									   selEdgeMids[ i ] + ImVec2( edgeSz, edgeSz ), hCol );
					dl->AddRect( selEdgeMids[ i ] - ImVec2( edgeSz, edgeSz ),
								 selEdgeMids[ i ] + ImVec2( edgeSz, edgeSz ), colBorder );
				}
			}

			// Rotation handle circle
			{
				bool active = ( curAction == 3 );
				ImU32 hCol = active ? colHandleAct : colHandle;
				dl->AddCircleFilled( rotHandle, handleSz, hCol );
				dl->AddCircle( rotHandle, handleSz, colBorder );
			}

			// Center dot
			dl->AddCircleFilled( selCenter, 3.0f, colOutline );
			dl->AddCircle( selCenter, 3.0f, colBorder );
		}

		dl->PopClipRect();

		// --- Interaction ---
		bool hovered = ImGui::ItemHoverable( canvasBB, id, g.LastItemData.ItemFlags );
		bool value_changed = false;

		ImGuiStorage* storage = &window->StateStorage;
		const ImGuiID actionKey      = id + 1000;
		const ImGuiID handleKey      = id + 1001;
		const ImGuiID startAngleKey  = id + 1002;
		const ImGuiID startRotKey    = id + 1003;
		const ImGuiID startDistKey   = id + 1004;
		const ImGuiID startScaleXKey = id + 1005;
		const ImGuiID startScaleYKey = id + 1006;

		if ( g.ActiveId == id && sel >= 0 )
		{
			ImTransformData* tr = &transforms[ sel ];
			int action = storage->GetInt( actionKey, 0 );

			if ( ImGui::IsMouseDown( 0 ) )
			{
				ImVec2 mouse = g.IO.MousePos;
				ImVec2 delta = g.IO.MouseDelta;

				if ( action == 1 ) // Translate
				{
					tr->Translation.x += delta.x;
					tr->Translation.y += delta.y;
					if ( delta.x != 0.0f || delta.y != 0.0f )
						value_changed = true;
				}
				else if ( action == 2 ) // Scale (uniform from corner)
				{
					float newDist = ImSqrt(
						( mouse.x - selCenter.x ) * ( mouse.x - selCenter.x ) +
						( mouse.y - selCenter.y ) * ( mouse.y - selCenter.y ) );
					float startDist = storage->GetFloat( startDistKey, 1.0f );
					if ( startDist > 1.0f )
					{
						float ratio = newDist / startDist;
						float sx = storage->GetFloat( startScaleXKey, 1.0f ) * ratio;
						float sy = storage->GetFloat( startScaleYKey, 1.0f ) * ratio;
						if ( sx > 0.01f && sy > 0.01f )
						{
							tr->Scale.x = sx;
							tr->Scale.y = sy;
							value_changed = true;
						}
					}
				}
				else if ( action == 3 ) // Rotate
				{
					float angle = ImAtan2( mouse.y - selCenter.y, mouse.x - selCenter.x );
					float startAngle = storage->GetFloat( startAngleKey, 0.0f );
					float startRot = storage->GetFloat( startRotKey, 0.0f );
					tr->Rotation = startRot + ( angle - startAngle );
					value_changed = true;
				}
				else if ( action == 4 ) // Non-uniform scale (edge handle)
				{
					int edge = storage->GetInt( handleKey, 0 );
					// Project mouse delta onto the edge's normal axis in local space
					// Edges: 0=top, 1=right, 2=bottom, 3=left
					// Top/Bottom affect Y scale, Left/Right affect X scale
					float mx = mouse.x - selCenter.x;
					float my = mouse.y - selCenter.y;
					// Transform to local space
					float lx =  mx * selCosR + my * selSinR;
					float ly = -mx * selSinR + my * selCosR;
					float startSX = storage->GetFloat( startScaleXKey, 1.0f );
					float startSY = storage->GetFloat( startScaleYKey, 1.0f );
					float startDist = storage->GetFloat( startDistKey, 1.0f );
					if ( startDist > 1.0f )
					{
						if ( edge == 0 || edge == 2 ) // top/bottom → Y scale
						{
							float newDist = ImFabs( ly );
							tr->Scale.y = startSY * ( newDist / startDist );
							if ( tr->Scale.y < 0.01f ) tr->Scale.y = 0.01f;
						}
						else // left/right → X scale
						{
							float newDist = ImFabs( lx );
							tr->Scale.x = startSX * ( newDist / startDist );
							if ( tr->Scale.x < 0.01f ) tr->Scale.x = 0.01f;
						}
						value_changed = true;
					}
				}
			}
			else
			{
				storage->SetInt( actionKey, 0 );
				ImGui::ClearActiveID();
			}
		}
		else if ( hovered && ImGui::IsMouseClicked( 0 ) )
		{
			ImVec2 mouse = g.IO.MousePos;
			bool handled = false;

			// If we have a selected image, check its handles first
			if ( sel >= 0 )
			{
				// 1) Rotation handle
				float rotDist = ImSqrt(
					( mouse.x - rotHandle.x ) * ( mouse.x - rotHandle.x ) +
					( mouse.y - rotHandle.y ) * ( mouse.y - rotHandle.y ) );
				if ( rotDist <= handleSz * 2.0f )
				{
					storage->SetInt( actionKey, 3 );
					float angle = ImAtan2( mouse.y - selCenter.y, mouse.x - selCenter.x );
					storage->SetFloat( startAngleKey, angle );
					storage->SetFloat( startRotKey, transforms[ sel ].Rotation );
					ImGui::SetKeyOwner( ImGuiKey_MouseLeft, id );
					ImGui::SetActiveID( id, window );
					ImGui::SetFocusID( id, window );
					handled = true;
				}

				// 2) Corner handles (uniform scale)
				if ( !handled )
				{
					for ( int i = 0; i < 4; ++i )
					{
						float cd = ImSqrt(
							( mouse.x - selCorners[ i ].x ) * ( mouse.x - selCorners[ i ].x ) +
							( mouse.y - selCorners[ i ].y ) * ( mouse.y - selCorners[ i ].y ) );
						if ( cd <= handleSz * 2.0f )
						{
							storage->SetInt( actionKey, 2 );
							storage->SetInt( handleKey, i );
							float dist = ImSqrt(
								( mouse.x - selCenter.x ) * ( mouse.x - selCenter.x ) +
								( mouse.y - selCenter.y ) * ( mouse.y - selCenter.y ) );
							storage->SetFloat( startDistKey, dist );
							storage->SetFloat( startScaleXKey, transforms[ sel ].Scale.x );
							storage->SetFloat( startScaleYKey, transforms[ sel ].Scale.y );
							ImGui::SetKeyOwner( ImGuiKey_MouseLeft, id );
							ImGui::SetActiveID( id, window );
							ImGui::SetFocusID( id, window );
							handled = true;
							break;
						}
					}
				}

				// 3) Edge midpoint handles (non-uniform scale)
				if ( !handled && nonUniform )
				{
					float edgeHit = handleSz * 2.0f;
					for ( int i = 0; i < 4; ++i )
					{
						float cd = ImSqrt(
							( mouse.x - selEdgeMids[ i ].x ) * ( mouse.x - selEdgeMids[ i ].x ) +
							( mouse.y - selEdgeMids[ i ].y ) * ( mouse.y - selEdgeMids[ i ].y ) );
						if ( cd <= edgeHit )
						{
							storage->SetInt( actionKey, 4 );
							storage->SetInt( handleKey, i );
							// Store distance along the relevant axis
							float mx = mouse.x - selCenter.x;
							float my = mouse.y - selCenter.y;
							float lx =  mx * selCosR + my * selSinR;
							float ly = -mx * selSinR + my * selCosR;
							float dist = ( i == 0 || i == 2 ) ? ImFabs( ly ) : ImFabs( lx );
							storage->SetFloat( startDistKey, dist );
							storage->SetFloat( startScaleXKey, transforms[ sel ].Scale.x );
							storage->SetFloat( startScaleYKey, transforms[ sel ].Scale.y );
							ImGui::SetKeyOwner( ImGuiKey_MouseLeft, id );
							ImGui::SetActiveID( id, window );
							ImGui::SetFocusID( id, window );
							handled = true;
							break;
						}
					}
				}
			}

			// 4) Click on any image body → select it (or translate if already selected)
			if ( !handled )
			{
				// Check images in reverse order (front to back) for selection
				int hitImage = -1;
				for ( int n = count - 1; n >= 0; --n )
				{
					ImVec2 c[ 4 ], center;
					float hw, hh, cosR, sinR;
					ComputeObjectCorners( canvasCenter, cw, ch, transforms[ n ], sizes[ n ], c, NULL, &center, &hw, &hh, &cosR, &sinR );
					if ( PointInRotatedRect( mouse, center, hw, hh, cosR, sinR ) )
					{
						hitImage = n;
						break;
					}
				}

				if ( hitImage >= 0 )
				{
					if ( hitImage == sel )
					{
						// Already selected → start translating
						storage->SetInt( actionKey, 1 );
						ImGui::SetKeyOwner( ImGuiKey_MouseLeft, id );
						ImGui::SetActiveID( id, window );
						ImGui::SetFocusID( id, window );
					}
					else
					{
						// Select this image
						if ( selectedIndex )
							*selectedIndex = hitImage;
						value_changed = true;
					}
					handled = true;
				}
			}

			// 5) Click on empty canvas → deselect
			if ( !handled && selectedIndex )
			{
				*selectedIndex = -1;
				value_changed = true;
			}
		}

		// Expand button
		bool* pExpanded = WidgetExpandButton( id, canvasBB );
		if ( pExpanded && *pExpanded )
		{
			// Persistent non-uniform scale toggle for the expanded window
			const ImGuiID nonUniformKey = id ^ 0xABC10000;
			bool nonUniformExp = window->StateStorage.GetBool( nonUniformKey, ( flags & ImTransformGizmoFlags_NonUniformScale ) != 0 );
			ImTransformGizmoFlags expFlags = nonUniformExp
				? ( flags | ImTransformGizmoFlags_NonUniformScale )
				: ( flags & ~ImTransformGizmoFlags_NonUniformScale );

			if ( BeginExpandedWindow( label, id, pExpanded, ImVec2( 1000, 700 ) ) )
			{
				ImVec2 avail = ImGui::GetContentRegionAvail();
				float widgetW = avail.x * 0.75f;
				// Left: gizmo
				if ( TransformGizmo( "##exp", transforms, sizes, count, selectedIndex, callbacks, expFlags, ImVec2( widgetW, avail.y ) ) )
					value_changed = true;
				ImGui::SameLine();
				// Right: info panel
				ImGui::BeginChild( "##info", ImVec2( 0, avail.y ), ImGuiChildFlags_Borders );

				// Options
				ImGui::TextUnformatted( "Options" );
				if ( ImGui::Checkbox( "Non-uniform scale##nu", &nonUniformExp ) )
					window->StateStorage.SetBool( nonUniformKey, nonUniformExp );

				// Layer info + ordering
				ImGui::Separator();
				ImGui::Text( "%d object%s", count, count != 1 ? "s" : "" );
				int s = ( selectedIndex && *selectedIndex >= 0 && *selectedIndex < count ) ? *selectedIndex : -1;
				if ( s >= 0 )
				{
					ImTransformData& tr = transforms[ s ];
					ImGui::Separator();
					ImGui::Text( "Selected: %d", s );

					// Layer ordering
					ImGui::Spacing();
					ImGui::TextUnformatted( "Order" );
					float hw = ( ImGui::GetContentRegionAvail().x - ImGui::GetStyle().ItemSpacing.x ) * 0.5f;
					bool canBack  = s > 0;
					bool canFront = s < count - 1;
					if ( !canBack ) ImGui::BeginDisabled();
					if ( ImGui::Button( "< Back##ord", ImVec2( hw, 0 ) ) )
					{
						ImSwap( transforms[ s ], transforms[ s - 1 ] ); ImSwap( sizes[ s ], sizes[ s - 1 ] );
						if ( callbacks && callbacks->SwapFn ) callbacks->SwapFn( s, s - 1, callbacks->SwapData );
						*selectedIndex = s - 1;
						value_changed = true;
					}
					if ( !canBack ) ImGui::EndDisabled();
					ImGui::SameLine();
					if ( !canFront ) ImGui::BeginDisabled();
					if ( ImGui::Button( "Front >##ord", ImVec2( hw, 0 ) ) )
					{
						ImSwap( transforms[ s ], transforms[ s + 1 ] ); ImSwap( sizes[ s ], sizes[ s + 1 ] );
						if ( callbacks && callbacks->SwapFn ) callbacks->SwapFn( s, s + 1, callbacks->SwapData );
						*selectedIndex = s + 1;
						value_changed = true;
					}
					if ( !canFront ) ImGui::EndDisabled();
					if ( !canBack ) ImGui::BeginDisabled();
					if ( ImGui::Button( "|< Background##ord", ImVec2( hw, 0 ) ) )
					{
						for ( int i = s; i > 0; --i ) { ImSwap( transforms[ i ], transforms[ i - 1 ] ); ImSwap( sizes[ i ], sizes[ i - 1 ] ); if ( callbacks && callbacks->SwapFn ) callbacks->SwapFn( i, i - 1, callbacks->SwapData ); }
						*selectedIndex = 0;
						value_changed = true;
					}
					if ( !canBack ) ImGui::EndDisabled();
					ImGui::SameLine();
					if ( !canFront ) ImGui::BeginDisabled();
					if ( ImGui::Button( "Foreground >|##ord", ImVec2( hw, 0 ) ) )
					{
						for ( int i = s; i < count - 1; ++i ) { ImSwap( transforms[ i ], transforms[ i + 1 ] ); ImSwap( sizes[ i ], sizes[ i + 1 ] ); if ( callbacks && callbacks->SwapFn ) callbacks->SwapFn( i, i + 1, callbacks->SwapData ); }
						*selectedIndex = count - 1;
						value_changed = true;
					}
					if ( !canFront ) ImGui::EndDisabled();

					// Transform controls
					ImGui::Spacing();
					ImGui::TextUnformatted( "Translation" );
					ImGui::SetNextItemWidth( -FLT_MIN );
					if ( ImGui::DragFloat2( "##tr", &tr.Translation.x, 1.0f, -FLT_MAX, FLT_MAX, "%.1f" ) )
						value_changed = true;
					ImGui::Spacing();
					ImGui::TextUnformatted( "Scale" );
					ImGui::SetNextItemWidth( -FLT_MIN );
					if ( ImGui::DragFloat2( "##sc", &tr.Scale.x, 0.005f, 0.01f, FLT_MAX, "%.3f" ) )
						value_changed = true;
					ImGui::Spacing();
					ImGui::TextUnformatted( "Rotation (rad)" );
					ImGui::SetNextItemWidth( -FLT_MIN );
					if ( ImGui::DragFloat( "##rot", &tr.Rotation, 0.01f, -IM_PI, IM_PI, "%.3f" ) )
						value_changed = true;
					ImGui::Spacing();
					if ( ImGui::Button( "Reset##itg", ImVec2( -FLT_MIN, 0 ) ) )
					{
						tr.Translation = ImVec2( 0.0f, 0.0f );
						tr.Scale       = ImVec2( 1.0f, 1.0f );
						tr.Rotation    = 0.0f;
						value_changed  = true;
					}
				}
				else
				{
					ImGui::Spacing();
					ImGui::TextDisabled( "no selection" );
				}
				ImGui::EndChild();
			}
			EndExpandedWindow();
		}

		return value_changed;
	}

	//////////////////////////////////////////////////////////////////////////
	// Color Warper
	//////////////////////////////////////////////////////////////////////////

	// ---- HSL conversion ----
	void ColorConvertRGBtoHSL( float r, float g, float b, float& out_h, float& out_s, float& out_l )
	{
		float mx = ImMax( r, ImMax( g, b ) );
		float mn = ImMin( r, ImMin( g, b ) );
		float d = mx - mn;
		out_l = ( mx + mn ) * 0.5f;
		if ( d < 1e-6f )
		{
			out_h = 0.0f;
			out_s = 0.0f;
			return;
		}
		out_s = d / ( 1.0f - ImAbs( 2.0f * out_l - 1.0f ) + 1e-6f );
		if ( mx == r )		out_h = ImFmod( ( g - b ) / d, 6.0f );
		else if ( mx == g )	out_h = ( b - r ) / d + 2.0f;
		else				out_h = ( r - g ) / d + 4.0f;
		out_h /= 6.0f;
		if ( out_h < 0.0f ) out_h += 1.0f;
	}

	static float HslHueToRgb( float p, float q, float t )
	{
		if ( t < 0.0f ) t += 1.0f;
		if ( t > 1.0f ) t -= 1.0f;
		if ( t < 1.0f / 6.0f ) return p + ( q - p ) * 6.0f * t;
		if ( t < 1.0f / 2.0f ) return q;
		if ( t < 2.0f / 3.0f ) return p + ( q - p ) * ( 2.0f / 3.0f - t ) * 6.0f;
		return p;
	}

	void ColorConvertHSLtoRGB( float h, float s, float l, float& out_r, float& out_g, float& out_b )
	{
		if ( s < 1e-6f )
		{
			out_r = out_g = out_b = l;
			return;
		}
		float q = l < 0.5f ? l * ( 1.0f + s ) : l + s - l * s;
		float p = 2.0f * l - q;
		out_r = HslHueToRgb( p, q, h + 1.0f / 3.0f );
		out_g = HslHueToRgb( p, q, h );
		out_b = HslHueToRgb( p, q, h - 1.0f / 3.0f );
	}

	// ---- HSY conversion (BT.709 luma) ----
	void ColorConvertRGBtoHSY( float r, float g, float b, float& out_h, float& out_s, float& out_y )
	{
		out_y = 0.2126f * r + 0.7152f * g + 0.0722f * b;
		// Use HSV hue
		float mx = ImMax( r, ImMax( g, b ) );
		float mn = ImMin( r, ImMin( g, b ) );
		float d = mx - mn;
		if ( d < 1e-6f )
		{
			out_h = 0.0f;
			out_s = 0.0f;
			return;
		}
		if ( mx == r )		out_h = ImFmod( ( g - b ) / d, 6.0f );
		else if ( mx == g )	out_h = ( b - r ) / d + 2.0f;
		else				out_h = ( r - g ) / d + 4.0f;
		out_h /= 6.0f;
		if ( out_h < 0.0f ) out_h += 1.0f;
		// Saturation as chroma relative to max possible
		out_s = ( mx > 1e-6f ) ? d / mx : 0.0f;
	}

	void ColorConvertHSYtoRGB( float h, float s, float y, float& out_r, float& out_g, float& out_b )
	{
		if ( s < 1e-6f )
		{
			out_r = out_g = out_b = ImClamp( y, 0.0f, 1.0f );
			return;
		}

		// Pure hue direction at full saturation
		float r0, g0, b0;
		ImGui::ColorConvertHSVtoRGB( h, 1.0f, 1.0f, r0, g0, b0 );

		float y0 = 0.2126f * r0 + 0.7152f * g0 + 0.0722f * b0;
		if ( y0 < 1e-6f )
		{
			out_r = out_g = out_b = ImClamp( y, 0.0f, 1.0f );
			return;
		}

		// Scale pure hue to match target luma
		float k = y / y0;
		float rc = r0 * k;
		float gc = g0 * k;
		float bc = b0 * k;

		// If out of gamut, blend toward gray(y) to bring max channel to 1.0
		float maxC = ImMax( rc, ImMax( gc, bc ) );
		if ( maxC > 1.0f && maxC > y + 1e-6f )
		{
			float t = ( 1.0f - y ) / ( maxC - y );
			t = ImClamp( t, 0.0f, 1.0f );
			rc = y + t * ( rc - y );
			gc = y + t * ( gc - y );
			bc = y + t * ( bc - y );
		}

		// Apply saturation as interpolation between gray(y) and chromatic
		out_r = ImClamp( y + s * ( rc - y ), 0.0f, 1.0f );
		out_g = ImClamp( y + s * ( gc - y ), 0.0f, 1.0f );
		out_b = ImClamp( y + s * ( bc - y ), 0.0f, 1.0f );
	}

	// ---- HSP conversion (perceived brightness) ----
	void ColorConvertRGBtoHSP( float r, float g, float b, float& out_h, float& out_s, float& out_p )
	{
		out_p = ImSqrt( 0.299f * r * r + 0.587f * g * g + 0.114f * b * b );
		float mx = ImMax( r, ImMax( g, b ) );
		float mn = ImMin( r, ImMin( g, b ) );
		float d = mx - mn;
		if ( d < 1e-6f )
		{
			out_h = 0.0f;
			out_s = 0.0f;
			return;
		}
		if ( mx == r )		out_h = ImFmod( ( g - b ) / d, 6.0f );
		else if ( mx == g )	out_h = ( b - r ) / d + 2.0f;
		else				out_h = ( r - g ) / d + 4.0f;
		out_h /= 6.0f;
		if ( out_h < 0.0f ) out_h += 1.0f;
		out_s = ( mx > 1e-6f ) ? d / mx : 0.0f;
	}

	void ColorConvertHSPtoRGB( float h, float s, float p, float& out_r, float& out_g, float& out_b )
	{
		if ( s < 1e-6f )
		{
			out_r = out_g = out_b = ImClamp( p, 0.0f, 1.0f );
			return;
		}

		// Pure hue direction at full saturation
		float r0, g0, b0;
		ImGui::ColorConvertHSVtoRGB( h, 1.0f, 1.0f, r0, g0, b0 );

		float p0 = ImSqrt( 0.299f * r0 * r0 + 0.587f * g0 * g0 + 0.114f * b0 * b0 );
		if ( p0 < 1e-6f )
		{
			out_r = out_g = out_b = ImClamp( p, 0.0f, 1.0f );
			return;
		}

		// Scale pure hue to match target perceived brightness
		float k = p / p0;
		float rc = r0 * k;
		float gc = g0 * k;
		float bc = b0 * k;

		// If out of gamut, blend toward gray(p) to bring max channel to 1.0
		float maxC = ImMax( rc, ImMax( gc, bc ) );
		if ( maxC > 1.0f && maxC > p + 1e-6f )
		{
			float t = ( 1.0f - p ) / ( maxC - p );
			t = ImClamp( t, 0.0f, 1.0f );
			rc = p + t * ( rc - p );
			gc = p + t * ( gc - p );
			bc = p + t * ( bc - p );
		}

		// Apply saturation as interpolation between gray(p) and chromatic
		out_r = ImClamp( p + s * ( rc - p ), 0.0f, 1.0f );
		out_g = ImClamp( p + s * ( gc - p ), 0.0f, 1.0f );
		out_b = ImClamp( p + s * ( bc - p ), 0.0f, 1.0f );
	}

	// ---- HSP Log conversion (log-perceived brightness) ----
	void ColorConvertRGBtoHSPLog( float r, float g, float b, float& out_h, float& out_s, float& out_p )
	{
		float pLin = ImSqrt( 0.299f * r * r + 0.587f * g * g + 0.114f * b * b );
		out_p = ( pLin > 1e-6f ) ? ImLog( 1.0f + pLin * 99.0f ) / ImLog( 100.0f ) : 0.0f; // log [0,1] -> [0,1]
		float mx = ImMax( r, ImMax( g, b ) );
		float mn = ImMin( r, ImMin( g, b ) );
		float d = mx - mn;
		if ( d < 1e-6f )
		{
			out_h = 0.0f;
			out_s = 0.0f;
			return;
		}
		if ( mx == r )		out_h = ImFmod( ( g - b ) / d, 6.0f );
		else if ( mx == g )	out_h = ( b - r ) / d + 2.0f;
		else				out_h = ( r - g ) / d + 4.0f;
		out_h /= 6.0f;
		if ( out_h < 0.0f ) out_h += 1.0f;
		out_s = ( mx > 1e-6f ) ? d / mx : 0.0f;
	}

	void ColorConvertHSPLogtoRGB( float h, float s, float pLog, float& out_r, float& out_g, float& out_b )
	{
		// Invert log: pLin = (10^(pLog * 2) - 1) / 99
		float pLin = ( ImPow( 100.0f, pLog ) - 1.0f ) / 99.0f;
		ColorConvertHSPtoRGB( h, s, pLin, out_r, out_g, out_b );
	}

	// Sample disc color for the warper background
	static ImU32 ColorWarperSampleDisc( ImColorWarperSpace space, float normRadius, float angle, float thirdAxis )
	{
		float r, g, b;
		float h = angle / ( 2.0f * IM_PI );
		if ( h < 0.0f ) h += 1.0f;
		if ( h > 1.0f ) h -= 1.0f;

		switch ( space )
		{
		default:
		case ImColorWarperSpace_HSV: ImGui::ColorConvertHSVtoRGB( h, normRadius, thirdAxis, r, g, b ); break;
		case ImColorWarperSpace_HSL: ColorConvertHSLtoRGB( h, normRadius, thirdAxis, r, g, b ); break;
		case ImColorWarperSpace_HSY: ColorConvertHSYtoRGB( h, normRadius, thirdAxis, r, g, b ); break;
		case ImColorWarperSpace_HSP: ColorConvertHSPtoRGB( h, normRadius, thirdAxis, r, g, b ); break;
		case ImColorWarperSpace_HSPLog: ColorConvertHSPLogtoRGB( h, normRadius, thirdAxis, r, g, b ); break;
		case ImColorWarperSpace_OkLCH:
		{
			float c = normRadius * kOkLCHMaxChroma;
			ColorConvertOKLCHtosRGB( r, g, b, thirdAxis, c, h );
			break;
		}
		case ImColorWarperSpace_OkLab:
		{
			// Disc maps a/b plane; normRadius = distance from neutral, angle = direction
			float labA = normRadius * kOkLCHMaxChroma * ImCos( angle );
			float labB = normRadius * kOkLCHMaxChroma * ImSin( angle );
			ColorConvertOKLABtoRGB( r, g, b, thirdAxis, labA, labB );
			break;
		}
		}

		r = ImClamp( r, 0.0f, 1.0f );
		g = ImClamp( g, 0.0f, 1.0f );
		b = ImClamp( b, 0.0f, 1.0f );
		return IM_COL32( ( int )( r * 255.0f + 0.5f ), ( int )( g * 255.0f + 0.5f ), ( int )( b * 255.0f + 0.5f ), 255 );
	}

	// ChromaLuma: extract brightness from the selected color space
	static float ChromaLumaBrightness( ImColorWarperSpace space, float r, float g, float b )
	{
		float h, s, third;
		switch ( space )
		{
		default:
		case ImColorWarperSpace_HSV:  ImGui::ColorConvertRGBtoHSV( r, g, b, h, s, third ); return third;
		case ImColorWarperSpace_HSL:  ColorConvertRGBtoHSL( r, g, b, h, s, third ); return third;
		case ImColorWarperSpace_HSY:  ColorConvertRGBtoHSY( r, g, b, h, s, third ); return third;
		case ImColorWarperSpace_HSP:  ColorConvertRGBtoHSP( r, g, b, h, s, third ); return third;
		case ImColorWarperSpace_HSPLog: ColorConvertRGBtoHSPLog( r, g, b, h, s, third ); return third;
		case ImColorWarperSpace_OkLab:
		case ImColorWarperSpace_OkLCH:
		{
			float L, la, lb;
			ColorConvertRGBtoOKLAB( L, la, lb, r, g, b );
			return L;
		}
		}
	}

	// ChromaLuma: decompose RGB into two rotated opponent axes [-0.5,0.5] and space-dependent brightness [0,1]
	// axisAngle (radians) rotates the Cb/Cr axes — at 0 the defaults are Yellow-Blue (axis1) and Green-Red (axis2)
	static void ChromaLumaDecompose( ImColorWarperSpace space, float r, float g, float b,
									 float& out_axis1, float& out_axis2, float& out_brightness,
									 float axisAngle = 0.0f )
	{
		// Standard BT.601 opponent axes
		float y601 = 0.299f * r + 0.587f * g + 0.114f * b;
		float cb = ( b - y601 ) / 1.772f;  // [-0.5, 0.5] yellow(-) to blue(+)
		float cr = ( r - y601 ) / 1.402f;  // [-0.5, 0.5] green(-) to red(+)

		// Rotate by axis angle
		float cosA = ImCos( axisAngle );
		float sinA = ImSin( axisAngle );
		out_axis1 = cb * cosA - cr * sinA;
		out_axis2 = cb * sinA + cr * cosA;

		// Brightness from selected color space
		out_brightness = ChromaLumaBrightness( space, r, g, b );
	}

	// ChromaLuma background: reconstruct color from axis value and brightness via BT.601 YCbCr inverse
	// axisVal in [-1,1], brightness in [0,1] (used as Y), isSecondGrid selects axis2, axisAngle rotates
	static ImU32 ChromaLumaSampleBG( float axisVal, float brightness, bool isSecondGrid, float axisAngle, float satScale )
	{
		// Map axis value to the rotated Cb/Cr component ([-0.5, 0.5])
		float a1 = isSecondGrid ? 0.0f : ( axisVal * 0.5f * satScale );
		float a2 = isSecondGrid ? ( axisVal * 0.5f * satScale ) : 0.0f;

		// Un-rotate to recover original Cb/Cr
		float cosA = ImCos( axisAngle );
		float sinA = ImSin( axisAngle );
		float cb = a1 * cosA + a2 * sinA;
		float cr = -a1 * sinA + a2 * cosA;

		// BT.601 inverse: Y ≈ brightness (approximation — actual Y601 differs from per-space brightness)
		float Y = brightness;
		float rv = Y + 1.402f * cr;
		float bv = Y + 1.772f * cb;
		float gv = ( Y - 0.299f * rv - 0.114f * bv ) / 0.587f;

		rv = ImClamp( rv, 0.0f, 1.0f );
		gv = ImClamp( gv, 0.0f, 1.0f );
		bv = ImClamp( bv, 0.0f, 1.0f );
		return IM_COL32( ( int )( rv * 255.0f + 0.5f ), ( int )( gv * 255.0f + 0.5f ), ( int )( bv * 255.0f + 0.5f ), 255 );
	}

	// Draw warper background disc (circular mode)
	static void DrawColorWarperDisc( ImDrawList* dl, ImVec2 center, float radius, ImColorWarperSpace space, float thirdAxis, int numSectors, int numRings )
	{
		ImVec2 const uv = ImGui::GetFontTexUvWhitePixel();
		int totalQuads = numSectors * numRings;
		dl->PrimReserve( totalQuads * 6, totalQuads * 4 );

		float const sectorAngle = 2.0f * IM_PI / ( float )numSectors;

		for ( int ring = 0; ring < numRings; ++ring )
		{
			float innerR = ( float )ring / numRings * radius;
			float outerR = ( float )( ring + 1 ) / numRings * radius;
			float innerNorm = ( float )ring / numRings;
			float outerNorm = ( float )( ring + 1 ) / numRings;

			for ( int sector = 0; sector < numSectors; ++sector )
			{
				float a0 = sector * sectorAngle;
				float a1 = ( sector + 1 ) * sectorAngle;

				ImVec2 p00 = center + ImVec2( ImCos( a0 ) * innerR, ImSin( a0 ) * innerR );
				ImVec2 p10 = center + ImVec2( ImCos( a0 ) * outerR, ImSin( a0 ) * outerR );
				ImVec2 p11 = center + ImVec2( ImCos( a1 ) * outerR, ImSin( a1 ) * outerR );
				ImVec2 p01 = center + ImVec2( ImCos( a1 ) * innerR, ImSin( a1 ) * innerR );

				ImU32 c00 = ColorWarperSampleDisc( space, innerNorm, a0, thirdAxis );
				ImU32 c10 = ColorWarperSampleDisc( space, outerNorm, a0, thirdAxis );
				ImU32 c11 = ColorWarperSampleDisc( space, outerNorm, a1, thirdAxis );
				ImU32 c01 = ColorWarperSampleDisc( space, innerNorm, a1, thirdAxis );

				ImDrawIdx idx = ( ImDrawIdx )dl->_VtxCurrentIdx;
				dl->PrimWriteIdx( idx + 0 ); dl->PrimWriteIdx( idx + 1 ); dl->PrimWriteIdx( idx + 2 );
				dl->PrimWriteIdx( idx + 0 ); dl->PrimWriteIdx( idx + 2 ); dl->PrimWriteIdx( idx + 3 );
				dl->PrimWriteVtx( p00, uv, c00 ); dl->PrimWriteVtx( p10, uv, c10 );
				dl->PrimWriteVtx( p11, uv, c11 ); dl->PrimWriteVtx( p01, uv, c01 );
			}
		}
	}

	// Draw warper background square (square mode)
	static void DrawColorWarperSquare( ImDrawList* dl, ImRect bb, ImColorWarperSpace space, float thirdAxis, int numH, int numS )
	{
		ImVec2 const uv = ImGui::GetFontTexUvWhitePixel();
		int totalQuads = numH * numS;
		dl->PrimReserve( totalQuads * 6, totalQuads * 4 );
		float w = bb.GetWidth();
		float h = bb.GetHeight();

		if ( space == ImColorWarperSpace_OkLab )
		{
			// Cartesian a/b plane: X = a [-maxChroma, +maxChroma], Y = b [-maxChroma, +maxChroma]
			for ( int yi = 0; yi < numS; ++yi )
			{
				float t0 = ( float )yi / numS;
				float t1 = ( float )( yi + 1 ) / numS;
				float b0 = ( 1.0f - t0 ) * kOkLCHMaxChroma * 2.0f - kOkLCHMaxChroma; // top = +max, bottom = -max
				float b1 = ( 1.0f - t1 ) * kOkLCHMaxChroma * 2.0f - kOkLCHMaxChroma;
				float y0 = bb.Min.y + t0 * h;
				float y1 = bb.Min.y + t1 * h;

				for ( int xi = 0; xi < numH; ++xi )
				{
					float u0 = ( float )xi / numH;
					float u1 = ( float )( xi + 1 ) / numH;
					float a0 = u0 * kOkLCHMaxChroma * 2.0f - kOkLCHMaxChroma; // left = -max, right = +max
					float a1 = u1 * kOkLCHMaxChroma * 2.0f - kOkLCHMaxChroma;
					float x0 = bb.Min.x + u0 * w;
					float x1 = bb.Min.x + u1 * w;

					auto sampleOkLab = [&]( float la, float lb ) -> ImU32 {
						float r, g, bv;
						ColorConvertOKLABtoRGB( r, g, bv, thirdAxis, la, lb );
						r = ImClamp( r, 0.0f, 1.0f );
						g = ImClamp( g, 0.0f, 1.0f );
						bv = ImClamp( bv, 0.0f, 1.0f );
						return IM_COL32( ( int )( r * 255.0f + 0.5f ), ( int )( g * 255.0f + 0.5f ), ( int )( bv * 255.0f + 0.5f ), 255 );
					};

					ImDrawIdx idx = ( ImDrawIdx )dl->_VtxCurrentIdx;
					dl->PrimWriteIdx( idx + 0 ); dl->PrimWriteIdx( idx + 1 ); dl->PrimWriteIdx( idx + 2 );
					dl->PrimWriteIdx( idx + 0 ); dl->PrimWriteIdx( idx + 2 ); dl->PrimWriteIdx( idx + 3 );
					dl->PrimWriteVtx( ImVec2( x0, y0 ), uv, sampleOkLab( a0, b0 ) );
					dl->PrimWriteVtx( ImVec2( x1, y0 ), uv, sampleOkLab( a1, b0 ) );
					dl->PrimWriteVtx( ImVec2( x1, y1 ), uv, sampleOkLab( a1, b1 ) );
					dl->PrimWriteVtx( ImVec2( x0, y1 ), uv, sampleOkLab( a0, b1 ) );
				}
			}
		}
		else
		{
			// Polar unwrap: X = hue [0,1], Y = sat/chroma [0,1]
			for ( int si = 0; si < numS; ++si )
			{
				float s0 = ( float )si / numS;
				float s1 = ( float )( si + 1 ) / numS;
				float y0 = bb.Max.y - s0 * h; // bottom = sat 0, top = sat 1
				float y1 = bb.Max.y - s1 * h;

				for ( int hi = 0; hi < numH; ++hi )
				{
					float h0 = ( float )hi / numH;
					float h1 = ( float )( hi + 1 ) / numH;
					float x0 = bb.Min.x + h0 * w;
					float x1 = bb.Min.x + h1 * w;

					float a0 = h0 * 2.0f * IM_PI;
					float a1 = h1 * 2.0f * IM_PI;

					ImU32 c00 = ColorWarperSampleDisc( space, s0, a0, thirdAxis );
					ImU32 c10 = ColorWarperSampleDisc( space, s0, a1, thirdAxis );
					ImU32 c11 = ColorWarperSampleDisc( space, s1, a1, thirdAxis );
					ImU32 c01 = ColorWarperSampleDisc( space, s1, a0, thirdAxis );

					ImDrawIdx idx = ( ImDrawIdx )dl->_VtxCurrentIdx;
					dl->PrimWriteIdx( idx + 0 ); dl->PrimWriteIdx( idx + 1 ); dl->PrimWriteIdx( idx + 2 );
					dl->PrimWriteIdx( idx + 0 ); dl->PrimWriteIdx( idx + 2 ); dl->PrimWriteIdx( idx + 3 );
					dl->PrimWriteVtx( ImVec2( x0, y0 ), uv, c00 ); dl->PrimWriteVtx( ImVec2( x1, y0 ), uv, c10 );
					dl->PrimWriteVtx( ImVec2( x1, y1 ), uv, c11 ); dl->PrimWriteVtx( ImVec2( x0, y1 ), uv, c01 );
				}
			}
		}
	}

	// Convert (hue 0..1, sat 0..1) to screen position
	static ImVec2 WarperHueSatToScreenCircular( float hue, float sat, ImVec2 center, float radius )
	{
		float a = hue * 2.0f * IM_PI;
		return ImVec2( center.x + ImCos( a ) * sat * radius, center.y + ImSin( a ) * sat * radius );
	}

	static ImVec2 WarperHueSatToScreenSquare( float hue, float sat, ImRect bb )
	{
		return ImVec2( bb.Min.x + hue * bb.GetWidth(), bb.Max.y - sat * bb.GetHeight() );
	}

	bool ColorWarper( char const* label, ImColorWarperData* data, ImColorWarperMode mode, ImColorWarperSpace space, float thirdAxis, ImColorWarperOverlay const* signalOverlay, ImColorWarperSignalColor signalColor, float axisAngle, ImVec2 size )
	{
		ImGuiWindow* window = ImGui::GetCurrentWindow();
		if ( window->SkipItems )
			return false;

		ImGuiContext& g = *GImGui;
		ImGuiStyle const& style = g.Style;
		ImWidgetsStyle& dwStyle = GetStyle();
		ImGuiID const id = window->GetID( label );
		ImVec2 const label_size = ImGui::CalcTextSize( label, NULL, true );

		if ( data->Offsets.Size == 0 )
			data->Init( data->HueDivisions, data->SatDivisions );

		float pointRadius = dwStyle.ColorWarper_PointRadius;
		float hitRadius = dwStyle.ColorWarper_HitRadius;
		float gridThick = dwStyle.ColorWarper_GridThickness;
		int discSectors = ( int )dwStyle.ColorWarper_DiscSectors;
		int discRings = ( int )dwStyle.ColorWarper_DiscRings;

		// Layout
		float side = size.x > 0.0f ? size.x : ( size.y > 0.0f ? size.y : ImGui::GetContentRegionAvail().x );
		if ( side < 50.0f ) side = 200.0f;
		ImVec2 frameSize( side, side );
		if ( label_size.x > 0.0f )
			frameSize.x += style.ItemInnerSpacing.x + label_size.x;

		ImRect const frame_bb( window->DC.CursorPos, window->DC.CursorPos + frameSize );
		ImRect const content_bb( window->DC.CursorPos, window->DC.CursorPos + ImVec2( side, side ) );
		ImGui::ItemSize( frameSize, style.FramePadding.y );
		if ( !ImGui::ItemAdd( frame_bb, id ) )
			return false;

		bool hovered = ImGui::ItemHoverable( content_bb, id, ImGuiItemFlags_None );
		if ( IsMouseOverExpandButton( id, content_bb ) ) hovered = false;
		bool value_changed = false;

		ImDrawList* dl = window->DrawList;
		ImVec2 center = content_bb.GetCenter();
		float radius = side * 0.5f - 1.0f;

		// Background
		if ( mode == ImColorWarperMode_Circular )
		{
			dl->AddCircleFilled( center, radius, IM_COL32( 0, 0, 0, 255 ) );
			DrawColorWarperDisc( dl, center, radius, space, thirdAxis, discSectors, discRings );
			dl->AddCircle( center, radius, ImGui::GetColorU32( ImGuiCol_Border ) );
		}
		else if ( mode == ImColorWarperMode_Square )
		{
			dl->AddRectFilled( content_bb.Min, content_bb.Max, IM_COL32( 0, 0, 0, 255 ) );
			DrawColorWarperSquare( dl, content_bb, space, thirdAxis, discSectors, discRings );
			dl->AddRect( content_bb.Min, content_bb.Max, ImGui::GetColorU32( ImGuiCol_Border ) );
		}
		else // ChromaLuma — two squares side by side
		{
			float halfW = content_bb.GetWidth() * 0.5f - 2.0f;
			ImRect leftBB( content_bb.Min, ImVec2( content_bb.Min.x + halfW, content_bb.Max.y ) );
			ImRect rightBB( ImVec2( content_bb.Max.x - halfW, content_bb.Min.y ), content_bb.Max );

			// Draw both squares with space-aware background
			for ( int sq = 0; sq < 2; ++sq )
			{
				ImRect const& bb = ( sq == 0 ) ? leftBB : rightBB;
				bool isSecond = ( sq == 1 );
				dl->AddRectFilled( bb.Min, bb.Max, IM_COL32( 0, 0, 0, 255 ) );
				float w = bb.GetWidth(), h = bb.GetHeight();
				int nX = 32, nY = 16;
				ImVec2 uv = ImGui::GetFontTexUvWhitePixel();
				dl->PrimReserve( nX * nY * 6, nX * nY * 4 );
				for ( int yi = 0; yi < nY; ++yi )
				{
					float br0 = 1.0f - ( float )yi / nY;
					float br1 = 1.0f - ( float )( yi + 1 ) / nY;
					for ( int xi = 0; xi < nX; ++xi )
					{
						float a0 = ( ( float )xi / nX - 0.5f ) * 2.0f;
						float a1 = ( ( float )( xi + 1 ) / nX - 0.5f ) * 2.0f;
						ImVec2 p0( bb.Min.x + ( float )xi / nX * w, bb.Min.y + ( float )yi / nY * h );
						ImVec2 p1( bb.Min.x + ( float )( xi + 1 ) / nX * w, bb.Min.y + ( float )( yi + 1 ) / nY * h );
						ImDrawIdx idx = ( ImDrawIdx )dl->_VtxCurrentIdx;
						dl->PrimWriteIdx( idx ); dl->PrimWriteIdx( idx + 1 ); dl->PrimWriteIdx( idx + 2 );
						dl->PrimWriteIdx( idx ); dl->PrimWriteIdx( idx + 2 ); dl->PrimWriteIdx( idx + 3 );
						dl->PrimWriteVtx( p0, uv, ChromaLumaSampleBG( a0, br0, isSecond, axisAngle, thirdAxis ) );
						dl->PrimWriteVtx( ImVec2( p1.x, p0.y ), uv, ChromaLumaSampleBG( a1, br0, isSecond, axisAngle, thirdAxis ) );
						dl->PrimWriteVtx( p1, uv, ChromaLumaSampleBG( a1, br1, isSecond, axisAngle, thirdAxis ) );
						dl->PrimWriteVtx( ImVec2( p0.x, p1.y ), uv, ChromaLumaSampleBG( a0, br1, isSecond, axisAngle, thirdAxis ) );
					}
				}
				dl->AddRect( bb.Min, bb.Max, ImGui::GetColorU32( ImGuiCol_Border ) );
			}
		}

		// Signal overlay (sampled pixel point cloud)
		if ( signalOverlay && signalOverlay->SampleCount > 0 )
		{
			dl->PushClipRect( content_bb.Min, content_bb.Max, true );

			float dotR = dwStyle.CIEChromaticity_SignalRadius;
			float signalAlphaF = ImClamp( dwStyle.CIEChromaticity_SignalAlpha, 0.0f, 1.0f );
			ImU8 alphaU8 = ( ImU8 )( signalAlphaF * 255.0f );

			// Flat color (with alpha override)
			ImU32 flatCol = 0;
			if ( signalColor == ImColorWarperSignalColor_Flat )
			{
				ImVec4 sigF = dwStyle.Colors[ StyleColor_CIEChromaticity_Signal ];
				sigF.w = signalAlphaF;
				flatCol = ImGui::GetColorU32( sigF );
			}

			// ChromaLuma sub-rects
			float clHalfW = content_bb.GetWidth() * 0.5f - 2.0f;
			ImRect clLeftBB( content_bb.Min, ImVec2( content_bb.Min.x + clHalfW, content_bb.Max.y ) );
			ImRect clRightBB( ImVec2( content_bb.Max.x - clHalfW, content_bb.Min.y ), content_bb.Max );

			int const kMaxPerBatch = 16000;
			int total = signalOverlay->SampleCount;
			// ChromaLuma draws 2 dots per sample
			int dotsPerSample = ( mode == ImColorWarperMode_ChromaLuma ) ? 2 : 1;
			int totalDots = total * dotsPerSample;
			int inBatch = 0;
			dl->PrimReserve( ImMin( totalDots, kMaxPerBatch ) * 6, ImMin( totalDots, kMaxPerBatch ) * 4 );
			ImVec2 uv = ImGui::GetFontTexUvWhitePixel();

			float const* rgb = signalOverlay->SampledRGB.Data;
			for ( int i = 0; i < total; ++i )
			{
				float r = rgb[ i * 3 + 0 ];
				float g2 = rgb[ i * 3 + 1 ];
				float b = rgb[ i * 3 + 2 ];

				ImU32 col;
				if ( signalColor == ImColorWarperSignalColor_PixelColor )
				{
					ImU8 pR = ( ImU8 )( ImClamp( r, 0.0f, 1.0f ) * 255.0f );
					ImU8 pG = ( ImU8 )( ImClamp( g2, 0.0f, 1.0f ) * 255.0f );
					ImU8 pB = ( ImU8 )( ImClamp( b, 0.0f, 1.0f ) * 255.0f );
					col = IM_COL32( pR, pG, pB, alphaU8 );
				}
				else
				{
					col = flatCol;
				}

				if ( mode == ImColorWarperMode_ChromaLuma )
				{
					// Decompose into rotated opponent axes [-0.5,0.5] and space-dependent brightness [0,1]
					float axis1, axis2, brightness;
					ChromaLumaDecompose( space, r, g2, b, axis1, axis2, brightness, axisAngle );

					// Normalize from [-0.5,0.5] to [0,1] for screen mapping
					float a1Norm = axis1 + 0.5f;
					float a2Norm = axis2 + 0.5f;

					// Left square: axis1 vs brightness
					ImVec2 posL;
					posL.x = clLeftBB.Min.x + a1Norm * clLeftBB.GetWidth();
					posL.y = clLeftBB.Min.y + ( 1.0f - brightness ) * clLeftBB.GetHeight();
					{
						ImVec2 p0( posL.x - dotR, posL.y - dotR );
						ImVec2 p1( posL.x + dotR, posL.y + dotR );
						ImDrawIdx pidx = ( ImDrawIdx )dl->_VtxCurrentIdx;
						dl->PrimWriteIdx( pidx ); dl->PrimWriteIdx( pidx + 1 ); dl->PrimWriteIdx( pidx + 2 );
						dl->PrimWriteIdx( pidx ); dl->PrimWriteIdx( pidx + 2 ); dl->PrimWriteIdx( pidx + 3 );
						dl->PrimWriteVtx( p0, uv, col );
						dl->PrimWriteVtx( ImVec2( p1.x, p0.y ), uv, col );
						dl->PrimWriteVtx( p1, uv, col );
						dl->PrimWriteVtx( ImVec2( p0.x, p1.y ), uv, col );
					}

					// Right square: axis2 vs brightness
					ImVec2 posR;
					posR.x = clRightBB.Min.x + a2Norm * clRightBB.GetWidth();
					posR.y = clRightBB.Min.y + ( 1.0f - brightness ) * clRightBB.GetHeight();
					{
						ImVec2 p0( posR.x - dotR, posR.y - dotR );
						ImVec2 p1( posR.x + dotR, posR.y + dotR );
						ImDrawIdx pidx = ( ImDrawIdx )dl->_VtxCurrentIdx;
						dl->PrimWriteIdx( pidx ); dl->PrimWriteIdx( pidx + 1 ); dl->PrimWriteIdx( pidx + 2 );
						dl->PrimWriteIdx( pidx ); dl->PrimWriteIdx( pidx + 2 ); dl->PrimWriteIdx( pidx + 3 );
						dl->PrimWriteVtx( p0, uv, col );
						dl->PrimWriteVtx( ImVec2( p1.x, p0.y ), uv, col );
						dl->PrimWriteVtx( p1, uv, col );
						dl->PrimWriteVtx( ImVec2( p0.x, p1.y ), uv, col );
					}

					inBatch += 2;
				}
				else
				{
					// Convert RGB to hue/sat in the current color space
					float h = 0.0f, s = 0.0f, third = 0.0f;
					ImVec2 pos;
					bool posComputed = false;

					switch ( space )
					{
					case ImColorWarperSpace_HSV:
						ImGui::ColorConvertRGBtoHSV( r, g2, b, h, s, third );
						break;
					case ImColorWarperSpace_HSL:
						ColorConvertRGBtoHSL( r, g2, b, h, s, third );
						break;
					case ImColorWarperSpace_HSY:
						ColorConvertRGBtoHSY( r, g2, b, h, s, third );
						break;
					case ImColorWarperSpace_HSP:
						ColorConvertRGBtoHSP( r, g2, b, h, s, third );
						break;
					case ImColorWarperSpace_HSPLog:
						ColorConvertRGBtoHSPLog( r, g2, b, h, s, third );
						break;
					case ImColorWarperSpace_OkLCH:
					{
						float L, C, H;
						ColorConvertsRGBtoOKLCH( L, C, H, r, g2, b );
						h = H;
						s = ImClamp( C / kOkLCHMaxChroma, 0.0f, 1.0f );
						break;
					}
					case ImColorWarperSpace_OkLab:
					{
						float L, la, lb;
						ColorConvertRGBtoOKLAB( L, la, lb, r, g2, b );
						if ( mode == ImColorWarperMode_Square )
						{
							// Cartesian a/b mapping: a → X, b → Y
							float aNorm = la / ( kOkLCHMaxChroma * 2.0f ) + 0.5f;
							float bNorm = 1.0f - ( lb / ( kOkLCHMaxChroma * 2.0f ) + 0.5f );
							pos.x = content_bb.Min.x + aNorm * content_bb.GetWidth();
							pos.y = content_bb.Min.y + bNorm * content_bb.GetHeight();
							posComputed = true;
						}
						else
						{
							// Circular: polar form (same as OkLCH on a disc)
							float dist = ImSqrt( la * la + lb * lb );
							s = ImClamp( dist / kOkLCHMaxChroma, 0.0f, 1.0f );
							h = ImAtan2( lb, la ) / ( 2.0f * IM_PI );
							if ( h < 0.0f ) h += 1.0f;
						}
						break;
					}
					default:
						ImGui::ColorConvertRGBtoHSV( r, g2, b, h, s, third );
						break;
					}

					if ( !posComputed )
					{
						if ( mode == ImColorWarperMode_Circular )
							pos = WarperHueSatToScreenCircular( h, s, center, radius );
						else
							pos = WarperHueSatToScreenSquare( h, s, content_bb );
					}

					ImVec2 p0( pos.x - dotR, pos.y - dotR );
					ImVec2 p1( pos.x + dotR, pos.y + dotR );
					ImDrawIdx pidx = ( ImDrawIdx )dl->_VtxCurrentIdx;
					dl->PrimWriteIdx( pidx ); dl->PrimWriteIdx( pidx + 1 ); dl->PrimWriteIdx( pidx + 2 );
					dl->PrimWriteIdx( pidx ); dl->PrimWriteIdx( pidx + 2 ); dl->PrimWriteIdx( pidx + 3 );
					dl->PrimWriteVtx( p0, uv, col );
					dl->PrimWriteVtx( ImVec2( p1.x, p0.y ), uv, col );
					dl->PrimWriteVtx( p1, uv, col );
					dl->PrimWriteVtx( ImVec2( p0.x, p1.y ), uv, col );

					++inBatch;
				}

				if ( inBatch >= kMaxPerBatch && ( i + 1 ) < total )
				{
					int remaining = ImMin( ( total - i - 1 ) * dotsPerSample, kMaxPerBatch );
					dl->PrimReserve( remaining * 6, remaining * 4 );
					inBatch = 0;
				}
			}

			dl->PopClipRect();
		}

		// Clip
		dl->PushClipRect( content_bb.Min, content_bb.Max, true );

		ImU32 gridCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_ColorWarper_GridLine ] );
		ImU32 pointOutCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_ColorWarper_PointOutline ] );
		ImU32 pointActCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_ColorWarper_PointOutlineActive ] );
		ImU32 pointFillCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_ColorWarper_PointFill ] );
		ImU32 pointMovedCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_ColorWarper_PointFillMoved ] );

		int hueDivs = data->HueDivisions;
		int satDivs = data->SatDivisions;

		// Helper: get screen pos for a grid point
		auto getScreenPos = [&]( int hi, int si ) -> ImVec2
		{
			ImVec2 wp = data->GetWarpedPos( hi, si );
			if ( mode == ImColorWarperMode_Circular )
				return WarperHueSatToScreenCircular( wp.x, wp.y, center, radius );
			else
				return WarperHueSatToScreenSquare( wp.x, wp.y, content_bb );
		};

		// Draw mesh grid lines
		// Saturation rings (connect hue points at same saturation)
		for ( int si = 0; si <= satDivs; ++si )
		{
			for ( int hi = 0; hi < hueDivs; ++hi )
			{
				ImVec2 p0 = getScreenPos( hi, si );
				ImVec2 p1 = getScreenPos( hi + 1, si ); // wraps via %HueDivisions
				dl->AddLine( p0, p1, gridCol, gridThick );
			}
		}
		// Hue spokes (connect saturation points at same hue)
		for ( int hi = 0; hi < hueDivs; ++hi )
		{
			for ( int si = 0; si < satDivs; ++si )
			{
				ImVec2 p0 = getScreenPos( hi, si );
				ImVec2 p1 = getScreenPos( hi, si + 1 );
				dl->AddLine( p0, p1, gridCol, gridThick );
			}
		}

		// Hit testing: find closest point to mouse
		int hovered_point = -1;
		ImVec2 mp = g.IO.MousePos;
		if ( hovered )
		{
			float bestDistSq = hitRadius * hitRadius;
			for ( int si = 0; si <= satDivs; ++si )
			{
				for ( int hi = 0; hi < hueDivs; ++hi )
				{
					int idx = data->PointIndex( hi, si );
					if ( data->Pinned[ idx ] )
						continue;
					ImVec2 sp = getScreenPos( hi, si );
					float dsq = ( sp.x - mp.x ) * ( sp.x - mp.x ) + ( sp.y - mp.y ) * ( sp.y - mp.y );
					if ( dsq < bestDistSq )
					{
						bestDistSq = dsq;
						hovered_point = idx;
					}
				}
			}
		}

		// Draw control points
		for ( int si = 0; si <= satDivs; ++si )
		{
			for ( int hi = 0; hi < hueDivs; ++hi )
			{
				int idx = data->PointIndex( hi, si );
				ImVec2 sp = getScreenPos( hi, si );
				bool hasMoved = ( ImLengthSqr( data->Offsets[ idx ] ) > 1e-6f );
				bool isPinned = data->Pinned[ idx ];
				bool isSelected = ( idx == data->SelectedIdx );
				bool isHovered = ( idx == hovered_point );

				ImU32 fillCol = isPinned ? ImGui::GetColorU32( ImVec4( 0.2f, 0.2f, 0.8f, 0.9f ) ) :
							   ( hasMoved ? pointMovedCol : pointFillCol );
				ImU32 outCol = isSelected ? pointActCol : pointOutCol;
				float r = isHovered ? pointRadius + 2.0f : pointRadius;

				dl->AddCircleFilled( sp, r, fillCol );
				dl->AddCircle( sp, r, outCol, 0, isSelected ? 2.0f : 1.0f );
			}
		}

		dl->PopClipRect();

		// Interaction
		int* pDragIdx = ( int* )ImGui::GetStateStorage()->GetIntRef( id, -1 );

		if ( hovered && ImGui::IsMouseClicked( ImGuiMouseButton_Left ) )
		{
			if ( hovered_point >= 0 )
			{
				*pDragIdx = hovered_point;
				data->SelectedIdx = hovered_point;
				ImGui::SetActiveID( id, window );
				ImGui::SetFocusID( id, window );
				ImGui::FocusWindow( window );
				ImGui::SetKeyOwner( ImGuiKey_MouseLeft, id );
			}
		}

		// Double-click to reset point
		if ( hovered && ImGui::IsMouseDoubleClicked( ImGuiMouseButton_Left ) )
		{
			if ( hovered_point >= 0 )
			{
				data->Offsets[ hovered_point ] = ImVec2( 0.0f, 0.0f );
				value_changed = true;
			}
		}

		// Right-click context menu
		if ( hovered && ImGui::IsMouseClicked( ImGuiMouseButton_Right ) && hovered_point >= 0 )
		{
			data->SelectedIdx = hovered_point;
			ImGui::OpenPopupOnItemClick( "##warper_ctx", ImGuiPopupFlags_MouseButtonRight );
		}

		if ( ImGui::BeginPopup( "##warper_ctx" ) )
		{
			int sel = data->SelectedIdx;
			if ( sel >= 0 && sel < data->Offsets.Size )
			{
				if ( ImGui::MenuItem( "Reset Point" ) )
				{
					data->Offsets[ sel ] = ImVec2( 0.0f, 0.0f );
					value_changed = true;
				}
				bool pinned = data->Pinned[ sel ];
				if ( ImGui::MenuItem( pinned ? "Unpin" : "Pin" ) )
					data->Pinned[ sel ] = !pinned;
				ImGui::Separator();
				if ( ImGui::MenuItem( "Reset All" ) )
				{
					data->Reset();
					value_changed = true;
				}
			}
			ImGui::EndPopup();
		}

		// Dragging
		if ( g.ActiveId == id && ImGui::IsMouseDragging( ImGuiMouseButton_Left ) )
		{
			int dragIdx = *pDragIdx;
			if ( dragIdx >= 0 && dragIdx < data->Offsets.Size && !data->Pinned[ dragIdx ] )
			{
				ImVec2 delta = g.IO.MouseDelta;
				if ( mode == ImColorWarperMode_Circular )
				{
					// Convert screen delta to (hue, sat) delta in polar space
					// Get current screen position of the dragged point
					int si = dragIdx / hueDivs;
					int hi = dragIdx % hueDivs;
					ImVec2 curScreen = getScreenPos( hi, si );
					ImVec2 newScreen = curScreen + delta;

					// Convert both to hue/sat
					ImVec2 relCur = ImVec2( curScreen.x - center.x, curScreen.y - center.y );
					ImVec2 relNew = ImVec2( newScreen.x - center.x, newScreen.y - center.y );

					float curAngle = atan2f( relCur.y, relCur.x ) / ( 2.0f * IM_PI );
					float newAngle = atan2f( relNew.y, relNew.x ) / ( 2.0f * IM_PI );
					float curDist = ImSqrt( relCur.x * relCur.x + relCur.y * relCur.y ) / radius;
					float newDist = ImSqrt( relNew.x * relNew.x + relNew.y * relNew.y ) / radius;

					float dH = newAngle - curAngle;
					if ( dH > 0.5f ) dH -= 1.0f;
					if ( dH < -0.5f ) dH += 1.0f;
					float dS = newDist - curDist;

					data->Offsets[ dragIdx ].x += dH;
					data->Offsets[ dragIdx ].y += dS;

					// Sync center points (all points at satIdx=0 share same offset)
					if ( si == 0 )
					{
						for ( int h = 0; h < hueDivs; ++h )
						{
							int cIdx = data->PointIndex( h, 0 );
							data->Offsets[ cIdx ] = data->Offsets[ dragIdx ];
						}
					}
				}
				else // Square
				{
					float dH = delta.x / content_bb.GetWidth();
					float dS = -delta.y / content_bb.GetHeight();
					data->Offsets[ dragIdx ].x += dH;
					data->Offsets[ dragIdx ].y += dS;
				}
				value_changed = true;
			}
		}

		if ( g.ActiveId == id && !ImGui::IsMouseDown( ImGuiMouseButton_Left ) )
		{
			*pDragIdx = -1;
			ImGui::ClearActiveID();
		}

		// Hover cursor
		if ( hovered && hovered_point >= 0 && g.ActiveId != id )
			ImGui::SetMouseCursor( ImGuiMouseCursor_Hand );

		// Delete key: reset selected point
		if ( data->SelectedIdx >= 0 && data->SelectedIdx < data->Offsets.Size && hovered && ImGui::IsKeyPressed( ImGuiKey_Delete ) )
		{
			if ( !data->Pinned[ data->SelectedIdx ] )
			{
				data->Offsets[ data->SelectedIdx ] = ImVec2( 0.0f, 0.0f );
				value_changed = true;
			}
		}

		// Tooltip on hovered point
		if ( hovered_point >= 0 && hovered && g.ActiveId != id )
		{
			int hi = hovered_point % hueDivs;
			int si = hovered_point / hueDivs;
			ImVec2 off = data->Offsets[ hovered_point ];
			bool pinned = data->Pinned[ hovered_point ];
			ImGui::SetTooltip( "Point [%d,%d]%s\nHue shift: %.3f  Sat shift: %.3f",
				hi, si, pinned ? " (pinned)" : "", off.x, off.y );
		}

		// Label
		if ( label_size.x > 0.0f )
			ImGui::RenderText( ImVec2( content_bb.Max.x + style.ItemInnerSpacing.x, content_bb.Min.y + style.FramePadding.y ), label );

		if ( value_changed )
			ImGui::MarkItemEdited( id );

		// Expand button
		bool* pExpanded = WidgetExpandButton( id, content_bb );
		if ( pExpanded && *pExpanded )
		{
			if ( BeginExpandedWindow( label, id, pExpanded, ImVec2( 800, 400 ) ) )
			{
				ImVec2 avail = ImGui::GetContentRegionAvail();
				float widgetW = avail.x * 0.75f;
				// Left: widget
				if ( ColorWarper( "##exp", data, mode, space, thirdAxis, signalOverlay, signalColor, axisAngle, ImVec2( widgetW, avail.y ) ) )
					value_changed = true;
				ImGui::SameLine();
				// Right: info / edit
				ImGui::BeginChild( "##info", ImVec2( 0, avail.y ), ImGuiChildFlags_Borders );
				char const* modeNames[] = { "Circular", "Square", "Chroma/Luma" };
				char const* spaceNames[] = { "HSV", "HSL", "HSY", "HSP", "HSP Log", "OkLab", "OkLCH" };
				ImGui::TextUnformatted( "Mode" );
				ImGui::TextUnformatted( modeNames[ ImClamp( ( int )mode, 0, 2 ) ] );
				ImGui::Spacing();
				ImGui::TextUnformatted( "Space" );
				ImGui::TextUnformatted( spaceNames[ ImClamp( ( int )space, 0, 6 ) ] );
				ImGui::Spacing();
				char const* thirdAxisNames[] = { "Value", "Lightness", "Luma", "Brightness", "Brightness (Log)", "Lightness", "Lightness" };
				ImGui::TextUnformatted( thirdAxisNames[ ImClamp( ( int )space, 0, 6 ) ] );
				ImGui::Text( "%.2f", thirdAxis );
				if ( mode == ImColorWarperMode_ChromaLuma )
				{
					ImGui::Spacing();
					ImGui::TextUnformatted( "Axis Angle" );
					ImGui::Text( "%.1f deg", axisAngle * 180.0f / IM_PI );
				}
				if ( data->SelectedIdx >= 0 && data->SelectedIdx < data->Offsets.Size )
				{
					ImGui::Separator();
					ImGui::TextUnformatted( "Point" );
					ImGui::Text( "%d", data->SelectedIdx );
					ImGui::Spacing();
					ImGui::TextUnformatted( "Offset X" );
					ImGui::SetNextItemWidth( -FLT_MIN );
					if ( ImGui::DragFloat( "##offx", &data->Offsets[ data->SelectedIdx ].x, 0.001f, -1.0f, 1.0f, "%.3f" ) )
						value_changed = true;
					ImGui::TextUnformatted( "Offset Y" );
					ImGui::SetNextItemWidth( -FLT_MIN );
					if ( ImGui::DragFloat( "##offy", &data->Offsets[ data->SelectedIdx ].y, 0.001f, -1.0f, 1.0f, "%.3f" ) )
						value_changed = true;
					ImGui::Spacing();
					ImGui::TextUnformatted( "Pinned" );
					ImGui::TextUnformatted( data->Pinned[ data->SelectedIdx ] ? "Yes" : "No" );
				}
				ImGui::EndChild();
			}
			EndExpandedWindow();
		}

		return value_changed;
	}

	//////////////////////////////////////////////////////////////////////////
	// Color Curve (Hue vs Hue, Hue vs Sat, etc.)
	//////////////////////////////////////////////////////////////////////////

	float ColorCurveDefaultValue( ImColorCurveMode mode )
	{
		switch ( mode )
		{
		case ImColorCurveMode_HueVsHue:  return 0.0f;
		case ImColorCurveMode_HueVsSat:  return 1.0f;
		case ImColorCurveMode_HueVsLum:  return 0.0f;
		case ImColorCurveMode_LumVsSat:  return 1.0f;
		case ImColorCurveMode_SatVsSat:  return 1.0f;
		default: return 0.0f;
		}
	}

	void ColorCurveRange( ImColorCurveMode mode, float* out_min, float* out_max )
	{
		switch ( mode )
		{
		case ImColorCurveMode_HueVsHue:  *out_min = -0.5f; *out_max = 0.5f;  break;
		case ImColorCurveMode_HueVsSat:  *out_min = 0.0f;  *out_max = 2.0f;  break;
		case ImColorCurveMode_HueVsLum:  *out_min = -1.0f; *out_max = 1.0f;  break;
		case ImColorCurveMode_LumVsSat:  *out_min = 0.0f;  *out_max = 2.0f;  break;
		case ImColorCurveMode_SatVsSat:  *out_min = 0.0f;  *out_max = 2.0f;  break;
		default: *out_min = 0.0f; *out_max = 1.0f; break;
		}
	}

	const char* ColorCurveModeName( ImColorCurveMode mode )
	{
		switch ( mode )
		{
		case ImColorCurveMode_HueVsHue:  return "Hue vs Hue";
		case ImColorCurveMode_HueVsSat:  return "Hue vs Sat";
		case ImColorCurveMode_HueVsLum:  return "Hue vs Lum";
		case ImColorCurveMode_LumVsSat:  return "Lum vs Sat";
		case ImColorCurveMode_SatVsSat:  return "Sat vs Sat";
		default: return "Unknown";
		}
	}

	static bool ColorCurveIsCyclic( ImColorCurveMode mode )
	{
		return mode <= ImColorCurveMode_HueVsLum;
	}

	static float CatmullRom( float p0, float p1, float p2, float p3, float t )
	{
		float t2 = t * t;
		float t3 = t2 * t;
		return 0.5f * (
			( 2.0f * p1 ) +
			( -p0 + p2 ) * t +
			( 2.0f * p0 - 5.0f * p1 + 4.0f * p2 - p3 ) * t2 +
			( -p0 + 3.0f * p1 - 3.0f * p2 + p3 ) * t3 );
	}

	// Advanced segment sampling: evaluate a segment between two keys using the key's segment type
	static float ColorCurveAdvancedSegSample( ImColorCurveKey const& k0, ImColorCurveKey const& k1, float t )
	{
		ImCurveEditorSeg seg = k0.Segment;

		if ( seg == ImCurveEditorSeg_CubicBezier )
		{
			// Hermite cubic using tangent slopes
			float span = ImMax( k1.Position - k0.Position, 1e-6f );
			float m1 = ( k0.TangentRight.x > 1e-6f ) ? ( k0.TangentRight.y / k0.TangentRight.x ) : 0.0f;
			float m2 = ( k1.TangentLeft.x < -1e-6f ) ? ( k1.TangentLeft.y / k1.TangentLeft.x ) : 0.0f;
			float t2 = t * t;
			float t3 = t2 * t;
			return ( 2.0f * t3 - 3.0f * t2 + 1.0f ) * k0.Value
				 + ( t3 - 2.0f * t2 + t ) * span * m1
				 + ( -2.0f * t3 + 3.0f * t2 ) * k1.Value
				 + ( t3 - t2 ) * span * m2;
		}

		// Step, linear, and easing functions
		float easedT = CurveEditorEvalEasing( seg, t );
		return k0.Value + ( k1.Value - k0.Value ) * easedT;
	}

	float ColorCurveSample( ImColorCurveData const& curve, ImColorCurveMode mode, float x, bool advancedSegments )
	{
		bool cyclic = ColorCurveIsCyclic( mode );
		float defaultY = ColorCurveDefaultValue( mode );
		int n = curve.Keys.Size;

		if ( n == 0 ) return defaultY;
		if ( n == 1 ) return curve.Keys[ 0 ].Value;

		// Advanced mode: use per-key segment types
		if ( advancedSegments )
		{
			float cx = cyclic ? ( x - ImFloor( x ) ) : x;
			if ( !cyclic )
			{
				if ( cx <= curve.Keys[ 0 ].Position ) return curve.Keys[ 0 ].Value;
				if ( cx >= curve.Keys[ n - 1 ].Position ) return curve.Keys[ n - 1 ].Value;
			}
			for ( int i = 0; i < n - 1; ++i )
			{
				if ( cx >= curve.Keys[ i ].Position && cx < curve.Keys[ i + 1 ].Position )
				{
					float span = curve.Keys[ i + 1 ].Position - curve.Keys[ i ].Position;
					if ( span < 1e-6f ) return curve.Keys[ i ].Value;
					float t = ( cx - curve.Keys[ i ].Position ) / span;
					return ColorCurveAdvancedSegSample( curve.Keys[ i ], curve.Keys[ i + 1 ], t );
				}
			}
			if ( cyclic && n >= 2 )
			{
				// Wrap-around segment: last key -> first key
				float segStart = curve.Keys[ n - 1 ].Position;
				float segEnd = curve.Keys[ 0 ].Position + 1.0f;
				float wx = ( cx < curve.Keys[ 0 ].Position ) ? cx + 1.0f : cx;
				float span = segEnd - segStart;
				if ( span < 1e-6f ) return curve.Keys[ n - 1 ].Value;
				float t = ( wx - segStart ) / span;
				return ColorCurveAdvancedSegSample( curve.Keys[ n - 1 ], curve.Keys[ 0 ], t );
			}
			return curve.Keys[ n - 1 ].Value;
		}

		if ( cyclic )
			x = x - ImFloor( x );

		// Find segment
		int seg = -1;
		float segStart = 0.0f, segEnd = 0.0f;

		for ( int i = 0; i < n - 1; ++i )
		{
			if ( x >= curve.Keys[ i ].Position && x < curve.Keys[ i + 1 ].Position )
			{
				seg = i;
				segStart = curve.Keys[ i ].Position;
				segEnd = curve.Keys[ i + 1 ].Position;
				break;
			}
		}

		if ( seg == -1 )
		{
			if ( cyclic )
			{
				seg = n - 1;
				segStart = curve.Keys[ n - 1 ].Position;
				segEnd = curve.Keys[ 0 ].Position + 1.0f;
				if ( x < curve.Keys[ 0 ].Position )
					x += 1.0f;
			}
			else
			{
				if ( x <= curve.Keys[ 0 ].Position ) return curve.Keys[ 0 ].Value;
				return curve.Keys[ n - 1 ].Value;
			}
		}

		float span = segEnd - segStart;
		if ( span < 1e-6f ) return curve.Keys[ seg % n ].Value;

		float t = ( x - segStart ) / span;

		float v0, v1, v2, v3;

		if ( cyclic )
		{
			int i1 = seg % n;
			int i2 = ( seg + 1 ) % n;
			int i0 = ( seg - 1 + n ) % n;
			int i3 = ( seg + 2 ) % n;
			v0 = curve.Keys[ i0 ].Value;
			v1 = curve.Keys[ i1 ].Value;
			v2 = curve.Keys[ i2 ].Value;
			v3 = curve.Keys[ i3 ].Value;
		}
		else
		{
			v1 = curve.Keys[ seg ].Value;
			v2 = curve.Keys[ seg + 1 ].Value;
			v0 = ( seg > 0 ) ? curve.Keys[ seg - 1 ].Value : ( 2.0f * v1 - v2 );
			v3 = ( seg + 2 < n ) ? curve.Keys[ seg + 2 ].Value : ( 2.0f * v2 - v1 );

			// Non-uniform Catmull-Rom for proper tangent estimation with uneven key spacing
			float x1 = segStart;
			float x2 = segEnd;
			float x0 = ( seg > 0 ) ? curve.Keys[ seg - 1 ].Position : ( x1 - span );
			float x3 = ( seg + 2 < n ) ? curve.Keys[ seg + 2 ].Position : ( x2 + span );

			float d01 = ImMax( x1 - x0, 1e-6f );
			float d12 = ImMax( span, 1e-6f );
			float d23 = ImMax( x3 - x2, 1e-6f );
			float d02 = ImMax( x2 - x0, 1e-6f );
			float d13 = ImMax( x3 - x1, 1e-6f );

			float m1 = d12 / d02 * ( ( v1 - v0 ) / d01 ) + d01 / d02 * ( ( v2 - v1 ) / d12 );
			float m2 = d23 / d13 * ( ( v2 - v1 ) / d12 ) + d12 / d13 * ( ( v3 - v2 ) / d23 );

			float t2 = t * t;
			float t3 = t2 * t;
			return ( 2.0f * t3 - 3.0f * t2 + 1.0f ) * v1
				 + ( t3 - 2.0f * t2 + t ) * d12 * m1
				 + ( -2.0f * t3 + 3.0f * t2 ) * v2
				 + ( t3 - t2 ) * d12 * m2;
		}

		return CatmullRom( v0, v1, v2, v3, t ); // cyclic path
	}

	// Background color for a given X position depending on mode
	static ImU32 ColorCurveBgSample( ImColorCurveMode mode, float t, float alpha )
	{
		float r, g, b;

		switch ( mode )
		{
		case ImColorCurveMode_HueVsHue:
		case ImColorCurveMode_HueVsSat:
		case ImColorCurveMode_HueVsLum:
			ImGui::ColorConvertHSVtoRGB( t, 0.85f, 0.85f, r, g, b );
			break;
		case ImColorCurveMode_LumVsSat:
			r = g = b = t;
			break;
		case ImColorCurveMode_SatVsSat:
			ImGui::ColorConvertHSVtoRGB( 0.0f, t, 1.0f, r, g, b );
			break;
		default:
			r = g = b = 0.5f;
			break;
		}

		return IM_COL32( ( int )( r * 255.0f + 0.5f ), ( int )( g * 255.0f + 0.5f ), ( int )( b * 255.0f + 0.5f ), ( int )( alpha * 255.0f + 0.5f ) );
	}

	// Coordinate transforms
	static ImVec2 ColorCurveToScreen( float pos, float val, ImRect const& bb, float yMin, float yMax )
	{
		float sx = ImLerp( bb.Min.x, bb.Max.x, pos );
		float sy = ImLerp( bb.Max.y, bb.Min.y, ( val - yMin ) / ( yMax - yMin ) );
		return ImVec2( sx, sy );
	}

	static ImVec2 ScreenToColorCurve( ImVec2 screenPos, ImRect const& bb, float yMin, float yMax )
	{
		float pos = ( screenPos.x - bb.Min.x ) / bb.GetWidth();
		float val = yMin + ( 1.0f - ( screenPos.y - bb.Min.y ) / bb.GetHeight() ) * ( yMax - yMin );
		return ImVec2( pos, val );
	}

	bool ColorCurve( char const* label, ImColorCurveData* curve, ImColorCurveMode mode, ImHistogramData const* histogramOverlay, bool advancedSegments, ImVec2 size )
	{
		ImGuiWindow* window = ImGui::GetCurrentWindow();
		if ( window->SkipItems )
			return false;

		ImGuiContext& g = *GImGui;
		const ImGuiStyle& style = g.Style;
		ImWidgetsStyle& dwStyle = GetStyle();
		const ImGuiID id = window->GetID( label );

		const float w = ( size.x > 0.0f ) ? size.x : ImGui::CalcItemWidth();
		const float h = ( size.y > 0.0f ) ? size.y : dwStyle.ColorCurve_DefaultHeight;

		ImVec2 label_size = ImGui::CalcTextSize( label, NULL, true );

		const ImRect frame_bb( window->DC.CursorPos, window->DC.CursorPos + ImVec2( w, h ) );
		const ImRect total_bb( frame_bb.Min, ImVec2( frame_bb.Max.x + ( label_size.x > 0.0f ? style.ItemInnerSpacing.x + label_size.x : 0.0f ), frame_bb.Max.y ) );

		ImGui::ItemSize( total_bb, style.FramePadding.y );
		if ( !ImGui::ItemAdd( total_bb, id, &frame_bb, 0 ) )
			return false;

		bool hovered = ImGui::ItemHoverable( frame_bb, id, g.LastItemData.ItemFlags );
		if ( IsMouseOverExpandButton( id, frame_bb ) ) hovered = false;

		bool value_changed = false;
		int& selected = curve->SelectedIdx;
		bool cyclic = ColorCurveIsCyclic( mode );

		float yMin, yMax;
		ColorCurveRange( mode, &yMin, &yMax );
		float defaultY = ColorCurveDefaultValue( mode );

		// Auto-initialize with two identity keys if empty
		if ( curve->Keys.Size == 0 )
		{
			curve->AddKey( 0.0f, defaultY );
			curve->AddKey( 1.0f, defaultY );
		}

		float keyRadius = dwStyle.ColorCurve_KeyRadius;
		float lineThick = dwStyle.ColorCurve_LineThickness;
		float hitRadius = keyRadius * 1.6f;

		ImDrawList* dl = window->DrawList;

		// --- HIT TESTING ---
		bool frame_contains_mouse = frame_bb.Contains( g.IO.MousePos );

		int hovered_key = -1;
		float closest_dist_sq = hitRadius * hitRadius;
		for ( int i = 0; i < curve->Keys.Size; ++i )
		{
			ImVec2 kScreen = ColorCurveToScreen( curve->Keys[ i ].Position, curve->Keys[ i ].Value, frame_bb, yMin, yMax );
			float dSq = ImLengthSqr( g.IO.MousePos - kScreen );
			if ( dSq < closest_dist_sq )
			{
				closest_dist_sq = dSq;
				hovered_key = i;
			}
		}

		// Find hovered tangent handle (only for selected key, only in advanced mode)
		int hovered_tangent = 0;
		ImGuiID dragTargetKey = ImGui::GetID( "##ccDragTgt" );
		int& dragTarget = *ImGui::GetStateStorage()->GetIntRef( dragTargetKey, 0 );
		if ( advancedSegments && selected >= 0 && selected < curve->Keys.Size )
		{
			ImColorCurveKey const& sk = curve->Keys[ selected ];
			bool showRight = ( sk.Segment == ImCurveEditorSeg_CubicBezier && selected < curve->Keys.Size - 1 );
			bool showLeft = ( selected > 0 && curve->Keys[ selected - 1 ].Segment == ImCurveEditorSeg_CubicBezier );
			float tanHitSq = ( hitRadius + 2.0f ) * ( hitRadius + 2.0f );
			ImVec2 tanLScreen = showLeft ? ColorCurveToScreen( sk.Position + sk.TangentLeft.x, sk.Value + sk.TangentLeft.y, frame_bb, yMin, yMax ) : ImVec2();
			ImVec2 tanRScreen = showRight ? ColorCurveToScreen( sk.Position + sk.TangentRight.x, sk.Value + sk.TangentRight.y, frame_bb, yMin, yMax ) : ImVec2();
			hovered_tangent = HitTestBezierHandles( g.IO.MousePos, tanLScreen, tanRScreen, showLeft, showRight, tanHitSq );
		}

		// --- DRAWING ---

		// Frame background
		ImU32 frame_col = ImGui::GetColorU32( g.ActiveId == id ? ImGuiCol_FrameBgActive : hovered ? ImGuiCol_FrameBgHovered : ImGuiCol_FrameBg );
		ImGui::RenderFrame( frame_bb.Min, frame_bb.Max, frame_col, true, g.Style.FrameRounding );

		dl->PushClipRect( frame_bb.Min, frame_bb.Max, true );

		// Background color tint (low opacity across full area)
		{
			int bgSegs = 32;
			float segW = frame_bb.GetWidth() / ( float )bgSegs;
			for ( int i = 0; i < bgSegs; ++i )
			{
				float t0 = ( float )i / ( float )bgSegs;
				float t1 = ( float )( i + 1 ) / ( float )bgSegs;
				ImU32 c0 = ColorCurveBgSample( mode, t0, 0.15f );
				ImU32 c1 = ColorCurveBgSample( mode, t1, 0.15f );
				ImVec2 rMin( frame_bb.Min.x + segW * i, frame_bb.Min.y );
				ImVec2 rMax( frame_bb.Min.x + segW * ( i + 1 ), frame_bb.Max.y );
				dl->AddRectFilledMultiColor( rMin, rMax, c0, c1, c1, c0 );
			}
		}

		// Bottom color reference strip
		{
			float stripH = 6.0f;
			int stripSegs = 32;
			float segW = frame_bb.GetWidth() / ( float )stripSegs;
			for ( int i = 0; i < stripSegs; ++i )
			{
				float t0 = ( float )i / ( float )stripSegs;
				float t1 = ( float )( i + 1 ) / ( float )stripSegs;
				ImU32 c0 = ColorCurveBgSample( mode, t0, 1.0f );
				ImU32 c1 = ColorCurveBgSample( mode, t1, 1.0f );
				ImVec2 rMin( frame_bb.Min.x + segW * i, frame_bb.Max.y - stripH );
				ImVec2 rMax( frame_bb.Min.x + segW * ( i + 1 ), frame_bb.Max.y );
				dl->AddRectFilledMultiColor( rMin, rMax, c0, c1, c1, c0 );
			}
		}

		// Optional luminance histogram overlay
		if ( histogramOverlay && histogramOverlay->BinCount > 0 && histogramOverlay->PeakCount > 0 )
		{
			ImU32 histCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_ColorCurve_HistogramOverlay ] );
			int binCount = histogramOverlay->BinCount;
			float frameW = frame_bb.GetWidth();
			float frameH = frame_bb.GetHeight();
			ImU32 const* bins = histogramOverlay->Bins.Data; // first channel only (luminance)

			float invPeak = 1.0f / ( float )histogramOverlay->PeakCount;

			for ( int i = 0; i < binCount; ++i )
			{
				float t0 = ( float )i / ( float )binCount;
				float t1 = ( float )( i + 1 ) / ( float )binCount;
				float barH = ( float )bins[ i ] * invPeak;

				ImVec2 rMin( frame_bb.Min.x + t0 * frameW, frame_bb.Max.y - barH * frameH );
				ImVec2 rMax( frame_bb.Min.x + t1 * frameW, frame_bb.Max.y );
				dl->AddRectFilled( rMin, rMax, histCol );
			}
		}

		// Grid lines
		{
			ImU32 gridCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_ColorCurve_Grid ] );
			int gridDivX = 10;
			int gridDivY = 4;
			for ( int i = 1; i < gridDivX; ++i )
			{
				float sx = frame_bb.Min.x + ( frame_bb.GetWidth() * i / ( float )gridDivX );
				dl->AddLine( ImVec2( sx, frame_bb.Min.y ), ImVec2( sx, frame_bb.Max.y ), gridCol );
			}
			for ( int i = 1; i < gridDivY; ++i )
			{
				float sy = frame_bb.Min.y + ( frame_bb.GetHeight() * i / ( float )gridDivY );
				dl->AddLine( ImVec2( frame_bb.Min.x, sy ), ImVec2( frame_bb.Max.x, sy ), gridCol );
			}
		}

		// Neutral / default line
		{
			ImU32 neutralCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_ColorCurve_NeutralLine ] );
			ImVec2 nLeft = ColorCurveToScreen( 0.0f, defaultY, frame_bb, yMin, yMax );
			ImVec2 nRight = ColorCurveToScreen( 1.0f, defaultY, frame_bb, yMin, yMax );
			dl->AddLine( nLeft, nRight, neutralCol, 1.5f );
		}

		// Curve polyline
		{
			ImU32 curveCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_ColorCurve_Line ] );
			int sampleCount = ( int )( w * 0.5f );
			if ( sampleCount < 64 ) sampleCount = 64;

			ImVec2 prev = ColorCurveToScreen( 0.0f,
				curve->Keys.Size > 0 ? ColorCurveSample( *curve, mode, 0.0f, advancedSegments ) : defaultY,
				frame_bb, yMin, yMax );

			for ( int s = 1; s <= sampleCount; ++s )
			{
				float t = ( float )s / ( float )sampleCount;
				float val = curve->Keys.Size > 0 ? ColorCurveSample( *curve, mode, t, advancedSegments ) : defaultY;
				ImVec2 cur = ColorCurveToScreen( t, val, frame_bb, yMin, yMax );
				dl->AddLine( prev, cur, curveCol, lineThick );
				prev = cur;
			}
		}

		// Keys
		for ( int i = 0; i < curve->Keys.Size; ++i )
		{
			ImVec2 kScreen = ColorCurveToScreen( curve->Keys[ i ].Position, curve->Keys[ i ].Value, frame_bb, yMin, yMax );
			bool isSelected = ( i == selected );
			bool isHovered = ( i == hovered_key );
			float radius = isHovered ? keyRadius + 2.0f : keyRadius;

			// For hue modes, tint key with the hue at its position; indicate selection via outline
			ImU32 keyCol;
			if ( mode <= ImColorCurveMode_HueVsLum )
			{
				float hr, hg, hb;
				ImGui::ColorConvertHSVtoRGB( curve->Keys[ i ].Position, 0.9f, 1.0f, hr, hg, hb );
				keyCol = IM_COL32( ( int )( hr * 255.0f + 0.5f ), ( int )( hg * 255.0f + 0.5f ), ( int )( hb * 255.0f + 0.5f ), 255 );
			}
			else
			{
				keyCol = ImGui::GetColorU32( dwStyle.Colors[ isSelected ? StyleColor_ColorCurve_KeySelected : ( isHovered ? StyleColor_ColorCurve_KeyHovered : StyleColor_ColorCurve_Key ) ] );
			}
			ImU32 outCol = isSelected ? IM_COL32_WHITE : ImGui::GetColorU32( dwStyle.Colors[ StyleColor_ColorCurve_KeyOutline ] );
			float outThk = isSelected ? 2.5f : 1.5f;

			dl->AddCircleFilled( kScreen, radius, keyCol );
			dl->AddCircle( kScreen, radius, outCol, 0, outThk );
		}

		// Draw tangent handles for selected key (advanced mode)
		if ( advancedSegments && selected >= 0 && selected < curve->Keys.Size )
		{
			ImColorCurveKey const& sk = curve->Keys[ selected ];
			bool showRight = ( sk.Segment == ImCurveEditorSeg_CubicBezier && selected < curve->Keys.Size - 1 );
			bool showLeft = ( selected > 0 && curve->Keys[ selected - 1 ].Segment == ImCurveEditorSeg_CubicBezier );
			ImVec2 keyScreen = ColorCurveToScreen( sk.Position, sk.Value, frame_bb, yMin, yMax );
			ImU32 tangentCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_CurveEditor_TangentLine ] );
			ImU32 tangentHovCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_CurveEditor_TangentHovered ] );
			ImVec2 tanLScreen = showLeft ? ColorCurveToScreen( sk.Position + sk.TangentLeft.x, sk.Value + sk.TangentLeft.y, frame_bb, yMin, yMax ) : ImVec2();
			ImVec2 tanRScreen = showRight ? ColorCurveToScreen( sk.Position + sk.TangentRight.x, sk.Value + sk.TangentRight.y, frame_bb, yMin, yMax ) : ImVec2();
			DrawBezierHandles( dl, keyScreen, tanLScreen, tanRScreen, showLeft, showRight,
							   hovered_tangent, tangentCol, tangentHovCol, lineThick, keyRadius * 0.7f );
		}

		// Hover feedback
		if ( hovered && frame_contains_mouse && g.ActiveId != id )
		{
			if ( hovered_key >= 0 )
			{
				ImGui::SetMouseCursor( ImGuiMouseCursor_Hand );
			}
			else
			{
				// Crosshair for "add" hint
				ImVec2 mp = g.IO.MousePos;
				ImU32 crossCol = ImGui::GetColorU32( dwStyle.Colors[ StyleColor_ColorCurve_Crosshair ] );
				dl->AddLine( ImVec2( mp.x, frame_bb.Min.y ), ImVec2( mp.x, frame_bb.Max.y ), crossCol );
				dl->AddLine( ImVec2( frame_bb.Min.x, mp.y ), ImVec2( frame_bb.Max.x, mp.y ), crossCol );
			}
		}

		dl->PopClipRect();

		// Border
		dl->AddRect( frame_bb.Min, frame_bb.Max, ImGui::GetColorU32( ImGuiCol_Border ) );

		// Label
		if ( label_size.x > 0.0f )
			ImGui::RenderText( ImVec2( frame_bb.Max.x + style.ItemInnerSpacing.x, frame_bb.Min.y + style.FramePadding.y ), label );

		// --- INTERACTIONS ---
		ImGui::PushID( id );

		// Click on tangent handle: select and start drag
		if ( advancedSegments && hovered_tangent != 0 && ImGui::IsMouseClicked( ImGuiMouseButton_Left ) && hovered && frame_contains_mouse )
		{
			dragTarget = hovered_tangent;
			ImGui::SetActiveID( id, window );
			ImGui::SetFocusID( id, window );
			ImGui::FocusWindow( window );
			ImGui::SetKeyOwner( ImGuiKey_MouseLeft, id );
		}
		// Click on key: select and start drag
		else if ( hovered_key >= 0 && ImGui::IsMouseClicked( ImGuiMouseButton_Left ) && hovered && frame_contains_mouse )
		{
			selected = hovered_key;
			dragTarget = 0;
			ImGui::SetActiveID( id, window );
			ImGui::SetFocusID( id, window );
			ImGui::FocusWindow( window );
			ImGui::SetKeyOwner( ImGuiKey_MouseLeft, id );
		}
		// Click on empty area: add key
		else if ( hovered_key == -1 && hovered_tangent == 0 && ImGui::IsMouseClicked( ImGuiMouseButton_Left ) && hovered && frame_contains_mouse )
		{
			ImVec2 curvePos = ScreenToColorCurve( g.IO.MousePos, frame_bb, yMin, yMax );
			float pos = ImClamp( curvePos.x, 0.0f, 1.0f );
			float val = ImClamp( curvePos.y, yMin, yMax );
			int newIdx = curve->AddKey( pos, val );
			selected = newIdx;
			dragTarget = 0;
			value_changed = true;
			ImGui::SetActiveID( id, window );
			ImGui::SetFocusID( id, window );
			ImGui::FocusWindow( window );
			ImGui::SetKeyOwner( ImGuiKey_MouseLeft, id );
		}

		// Drag
		if ( g.ActiveId == id && ImGui::IsMouseDragging( ImGuiMouseButton_Left ) && selected >= 0 && selected < curve->Keys.Size )
		{
			if ( advancedSegments && dragTarget != 0 )
			{
				// Drag tangent handle
				ImVec2 prev = ScreenToColorCurve( g.IO.MousePos - g.IO.MouseDelta, frame_bb, yMin, yMax );
				ImVec2 curr = ScreenToColorCurve( g.IO.MousePos, frame_bb, yMin, yMax );
				ImVec2 delta( curr.x - prev.x, curr.y - prev.y );
				ImColorCurveKey& k = curve->Keys[ selected ];
				if ( dragTarget == -1 )
				{
					k.TangentLeft = ImVec2( k.TangentLeft.x + delta.x, k.TangentLeft.y + delta.y );
					if ( k.TangentLeft.x > 0.0f ) k.TangentLeft.x = 0.0f;
					EnforceTangentMode( k.TangentLeft, k.TangentRight, k.TangentMode, -1 );
				}
				else
				{
					k.TangentRight = ImVec2( k.TangentRight.x + delta.x, k.TangentRight.y + delta.y );
					if ( k.TangentRight.x < 0.0f ) k.TangentRight.x = 0.0f;
					EnforceTangentMode( k.TangentLeft, k.TangentRight, k.TangentMode, 1 );
				}
				value_changed = true;
			}
			else
			{
				// Drag key
				ImVec2 curvePos = ScreenToColorCurve( g.IO.MousePos, frame_bb, yMin, yMax );

				float newPos = curvePos.x;
				if ( cyclic )
					newPos = newPos - floorf( newPos );
				else
					newPos = ImClamp( newPos, 0.0f, 1.0f );

				float newVal = ImClamp( curvePos.y, yMin, yMax );

				curve->Keys[ selected ].Position = newPos;
				curve->Keys[ selected ].Value = newVal;
				curve->SortKeys();

				// Re-find selected after sort
				for ( int i = 0; i < curve->Keys.Size; ++i )
				{
					if ( curve->Keys[ i ].Position == newPos && curve->Keys[ i ].Value == newVal )
					{
						selected = i;
						break;
					}
				}

				value_changed = true;

				// Drag far below/above: delete
				if ( ( g.IO.MousePos.y > frame_bb.Max.y + 30.0f || g.IO.MousePos.y < frame_bb.Min.y - 30.0f ) && curve->Keys.Size > 0 )
				{
					curve->RemoveKey( selected );
					selected = -1;
					ImGui::ClearActiveID();
					value_changed = true;
				}
			}
		}

		// Release
		if ( g.ActiveId == id && ImGui::IsMouseReleased( ImGuiMouseButton_Left ) )
		{
			ImGui::ClearActiveID();
		}

		// Right-click: context menu
		if ( hovered_key >= 0 && ImGui::IsMouseClicked( ImGuiMouseButton_Right ) && hovered && frame_contains_mouse )
		{
			selected = hovered_key;
			ImGui::OpenPopup( "##ColorCurveCtx" );
		}

		if ( ImGui::BeginPopup( "##ColorCurveCtx" ) )
		{
			if ( selected >= 0 && selected < curve->Keys.Size )
			{
				ImGui::Text( "Key %d: pos=%.3f val=%.3f", selected, curve->Keys[ selected ].Position, curve->Keys[ selected ].Value );
				ImGui::Separator();
				if ( ImGui::MenuItem( "Reset to Default" ) )
				{
					curve->Keys[ selected ].Value = defaultY;
					value_changed = true;
				}
				if ( ImGui::MenuItem( "Remove Key" ) )
				{
					curve->RemoveKey( selected );
					selected = -1;
					value_changed = true;
				}
			}
			ImGui::EndPopup();
		}

		// Double-click on key: reset value to default
		if ( hovered_key >= 0 && ImGui::IsMouseDoubleClicked( ImGuiMouseButton_Left ) && hovered && frame_contains_mouse )
		{
			curve->Keys[ hovered_key ].Value = defaultY;
			selected = hovered_key;
			value_changed = true;
		}

		// Delete key
		if ( selected >= 0 && ImGui::IsKeyPressed( ImGuiKey_Delete ) && hovered )
		{
			if ( curve->RemoveKey( selected ) )
			{
				selected = -1;
				value_changed = true;
			}
		}

		// Arrow key nudging
		if ( selected >= 0 && selected < curve->Keys.Size && hovered )
		{
			ImGui::SetKeyOwner( ImGuiKey_LeftArrow, id );
			ImGui::SetKeyOwner( ImGuiKey_RightArrow, id );
			ImGui::SetKeyOwner( ImGuiKey_UpArrow, id );
			ImGui::SetKeyOwner( ImGuiKey_DownArrow, id );
			float stepX = 1.0f / ImMax( frame_bb.GetWidth(), 1.0f );
			float stepY = ( yMax - yMin ) / ImMax( frame_bb.GetHeight(), 1.0f );
			if ( ImGui::GetIO().KeyShift )
			{
				stepX *= 10.0f;
				stepY *= 10.0f;
			}
			bool nudged = false;
			float newPos = curve->Keys[ selected ].Position;
			float newVal = curve->Keys[ selected ].Value;
			if ( ImGui::IsKeyPressed( ImGuiKey_LeftArrow ) )  { newPos -= stepX; nudged = true; }
			if ( ImGui::IsKeyPressed( ImGuiKey_RightArrow ) ) { newPos += stepX; nudged = true; }
			if ( ImGui::IsKeyPressed( ImGuiKey_UpArrow ) )    { newVal += stepY; nudged = true; }
			if ( ImGui::IsKeyPressed( ImGuiKey_DownArrow ) )  { newVal -= stepY; nudged = true; }
			if ( nudged )
			{
				curve->Keys[ selected ].Position = ImClamp( newPos, 0.0f, 1.0f );
				curve->Keys[ selected ].Value = ImClamp( newVal, yMin, yMax );
				curve->SortKeys();
				value_changed = true;
			}
		}

		// Tooltip on hovered key
		if ( hovered_key >= 0 && hovered_key < curve->Keys.Size && hovered && g.ActiveId != id )
		{
			ImGui::SetTooltip( "Key %d: pos=%.3f val=%.3f", hovered_key,
				curve->Keys[ hovered_key ].Position, curve->Keys[ hovered_key ].Value );
		}

		ImGui::PopID();

		if ( value_changed )
			ImGui::MarkItemEdited( id );

		// Expand button
		bool* pExpanded = WidgetExpandButton( id, frame_bb );
		if ( pExpanded && *pExpanded )
		{
			if ( BeginExpandedWindow( label, id, pExpanded, ImVec2( 800, 400 ) ) )
			{
				ImVec2 avail = ImGui::GetContentRegionAvail();
				float widgetW = avail.x * 0.75f;
				// Left: widget
				if ( ColorCurve( "##exp", curve, mode, histogramOverlay, advancedSegments, ImVec2( widgetW, avail.y ) ) )
					value_changed = true;
				ImGui::SameLine();
				// Right: info / edit
				ImGui::BeginChild( "##info", ImVec2( 0, avail.y ), ImGuiChildFlags_Borders );
				float ccYMin, ccYMax;
				ColorCurveRange( mode, &ccYMin, &ccYMax );
				ImGui::TextUnformatted( "Mode" );
				ImGui::TextUnformatted( ColorCurveModeName( mode ) );
				ImGui::Spacing();
				ImGui::TextUnformatted( "Keys" );
				ImGui::Text( "%d", curve->Keys.Size );
				if ( curve->SelectedIdx >= 0 && curve->SelectedIdx < curve->Keys.Size )
				{
					ImColorCurveKey& ck = curve->Keys[ curve->SelectedIdx ];
					ImGui::Separator();
					ImGui::TextUnformatted( "Selected" );
					ImGui::Text( "%d", curve->SelectedIdx );
					ImGui::Spacing();
					ImGui::TextUnformatted( "Position" );
					ImGui::SetNextItemWidth( -FLT_MIN );
					if ( ImGui::DragFloat( "##pos", &ck.Position, 0.001f, 0.0f, 1.0f, "%.3f" ) )
					{
						curve->SortKeys();
						value_changed = true;
					}
					ImGui::TextUnformatted( "Value" );
					ImGui::SetNextItemWidth( -FLT_MIN );
					if ( ImGui::DragFloat( "##val", &ck.Value, 0.001f, ccYMin, ccYMax, "%.3f" ) )
						value_changed = true;
					// Advanced segment controls (only in modal)
					if ( advancedSegments )
					{
						ImGui::Spacing();
						ImGui::TextUnformatted( "Segment" );
						if ( ImGui::Button( CurveEditorSegName( ck.Segment ), ImVec2( -FLT_MIN, 0 ) ) )
							ImGui::OpenPopup( "##ccSegPopup" );
						if ( ImGui::BeginPopup( "##ccSegPopup" ) )
						{
							if ( ImCurveEditorSegmentMenu( &ck.Segment, ck.Segment ) )
							{
								if ( ck.Segment == ImCurveEditorSeg_CubicBezier )
								{
									int si = curve->SelectedIdx;
									float segWidth = 0.1f;
									if ( si < curve->Keys.Size - 1 )
										segWidth = ( curve->Keys[ si + 1 ].Position - ck.Position ) * 0.33f;
									ck.TangentRight = ImVec2( segWidth, 0.0f );
									if ( si < curve->Keys.Size - 1 )
										curve->Keys[ si + 1 ].TangentLeft = ImVec2( -segWidth, 0.0f );
								}
								value_changed = true;
							}
							ImGui::EndPopup();
						}
						// Tangent mode (only for bezier keys)
						bool hasBezier = ( ck.Segment == ImCurveEditorSeg_CubicBezier )
							|| ( curve->SelectedIdx > 0 && curve->Keys[ curve->SelectedIdx - 1 ].Segment == ImCurveEditorSeg_CubicBezier );
						if ( hasBezier )
						{
							if ( TangentModeUI( ck.TangentLeft, ck.TangentRight, ck.TangentMode ) )
								value_changed = true;
						}
					}
				}
				ImGui::EndChild();
			}
			EndExpandedWindow();
		}

		return value_changed;
	}

